        self.client.force_login(self.user)
        self.assertEqual(self.client.post('/workshop/add/', {'item_id': 'abc'}).status_code, 400)
        self.assertEqual(self.client.post('/workshop/add/', {'item_id': 99999999}).status_code, 404)

