class TouchAbsentStatsTests(SimpleTestCase):
    """Touch forked before the Dofus 2.30 percent damage and resist stats."""

    FINAL_ABSENT = [
        '% Melee Damage', '% Ranged Damage', '% Weapon Damage', '% Spell Damage',
        '% Melee Resist', '% Ranged Resist', '% Weapon Resist',
    ]
    KEPT = ['Critical Damage', 'Pushback Damage', 'Critical Resist', 'Pushback Resist']

    def _items(self):
        from fashionistapulp.structure import get_structure
        touch = get_structure('touch')
        return touch, touch.get_concatenated_items_lists()

    def test_no_touch_item_carries_final_damage_or_resist(self):
        touch, items = self._items()
        for name in self.FINAL_ABSENT:
            stat = touch.get_stat_by_name(name)
            self.assertIsNotNone(stat, '%s missing from touch stat table' % name)
            offenders = [it.name for it in items if stat.id in dict(it.stats)]
            self.assertEqual(offenders, [],
                             '%s should not appear on any touch item, found: %s'
                             % (name, offenders[:5]))

    def test_touch_still_carries_critical_and_pushback_stats(self):
        # Weapons are excluded from get_concatenated_items_lists, so read the raw db.
        import os, sqlite3, fashionistapulp
        db = os.path.join(os.path.dirname(fashionistapulp.__file__), 'items_touch.db')
        c = sqlite3.connect(db)
        present = set(r[0] for r in c.execute('SELECT DISTINCT stat FROM stats_of_item'))
        by_key = {k: i for i, k in c.execute('SELECT id, key FROM stats')}
        for key in ['cridam', 'pshdam', 'crires', 'pshres']:
            self.assertIn(by_key[key], present,
                          'touch should keep the %s stat on gear' % key)
        c.close()

    def test_touch_carries_pvp_resists(self):
        touch, items = self._items()
        stat = touch.get_stat_by_name('% Air Resist in PVP')
        n = sum(1 for it in items if stat.id in dict(it.stats))
        self.assertGreater(n, 0, 'touch gear should carry PvP resists')


class NoEmDashInGuidesTests(SimpleTestCase):
    """No em or en dash in any guide field."""

    def test_no_guide_field_contains_an_em_or_en_dash(self):
        from chardata import guides_content
        offenders = []
        for slug, variant, language, fields in guides_content.iter_content_blocks():
            for field_name, value in fields.items():
                if isinstance(value, str) and ('—' in value or '–' in value):
                    offenders.append('%s/%s/%s/%s' % (slug, variant, language, field_name))
        self.assertEqual(
            offenders, [],
            'em/en dash found in guide content (use ., :, , or parentheses): %s' % offenders)

    def test_no_dash_in_templates_or_catalogs(self):
        import glob
        import io
        import os

        banned = ('—', '–', '&mdash;', '&ndash;')
        here = os.path.dirname(os.path.abspath(__file__))
        scan = glob.glob(os.path.join(here, 'templates', 'chardata', '*'))
        scan += glob.glob(os.path.join(here, '..', 'locale', '*',
                                       'LC_MESSAGES', '*.po'))
        offenders = []
        for path in scan:
            if not os.path.isfile(path):
                continue
            text = io.open(path, encoding='utf-8', errors='replace').read()
            for token in banned:
                if token in text:
                    offenders.append('%s (%s)' % (os.path.basename(path), token))
        self.assertEqual(
            offenders, [],
            'em/en dash in rendered sources (use ., :, &middot; or |): %s' % offenders)


class GuideBodyLinksKeepTheVersionTests(TestCase):
    """Links in a guide body keep the reader's version."""

    def test_a_body_link_carries_the_version(self):
        from chardata.guides_view import add_version_prefix
        self.assertEqual('<a href="/retro/setup/">x</a>',
                         add_version_prefix('<a href="/setup/">x</a>', 'retro'))
        self.assertEqual('<a href="/beta/guides/critical-hits/">x</a>',
                         add_version_prefix('<a href="/guides/critical-hits/">x</a>',
                                            'beta'))

    def test_it_leaves_alone_what_it_should(self):
        from chardata.guides_view import add_version_prefix
        for html, version in (('<a href="/touch/forgemagie/">x</a>', 'touch'),
                              ('<a href="/setup/">x</a>', 'dofus3'),
                              ('<a href="https://www.ankama.com/">x</a>', 'retro'),
                              ('<a href="/static/a.png">x</a>', 'retro')):
            with self.subTest(html=html, version=version):
                self.assertEqual(html, add_version_prefix(html, version))

    def test_the_hub_cards_stay_in_the_version(self):
        import re
        for version in ('retro', 'touch', 'beta', 'dofus2'):
            response = self.client.get('/%s/guides/' % version)
            body = response.content.decode('utf-8')
            grid = body.split('fm-guides-grid', 1)[-1].split('fm-guides-cta', 1)[0]
            cards = set(re.findall(r'href="([^"]*/guides/[^"]+)"', grid))
            with self.subTest(version=version):
                self.assertTrue(cards, 'the hub lists no guide at all')
                self.assertEqual([], [c for c in cards
                                      if not c.startswith('/%s/' % version)])

    def test_the_pages_serve_links_that_stay_in_the_version(self):
        import re
        from chardata.guides_content import ordered_slugs
        for version in ('retro', 'touch'):
            for slug in ordered_slugs()[:6]:
                response = self.client.get('/%s/guides/%s/' % (version, slug))
                body = response.content.decode('utf-8')
                article = body.split('<article', 1)[-1].split('</article>', 1)[0]
                strays = [href for href in re.findall(r'href="(/[^"]*)"', article)
                          if not href.startswith('/%s/' % version)
                          and not href.startswith('/static')]
                with self.subTest(version=version, guide=slug):
                    self.assertEqual([], strays)


class GuideMetaDescriptionLengthTests(SimpleTestCase):
    """Guide desc is the meta description, Google truncates past ~160 chars."""

    MAX_DESC = 160

    def test_guide_descriptions_fit_the_search_snippet(self):
        from chardata import guides_content
        offenders = []
        for slug, variant, language, fields in guides_content.iter_content_blocks():
            desc = fields.get('desc', '')
