class PlaceholdersSurviveTranslationTests(SimpleTestCase):
    """A translation keeps its source's placeholders, msgfmt does not check."""

    LANGS = ('fr', 'es', 'pt', 'de')
    CATALOGS = ('django.po', 'djangojs.po')
    MARK = re.compile(r'%\(\w+\)[a-z]|%[sd]|\{\w+\}')

    def test_every_translation_keeps_the_placeholders_of_its_source(self):
        try:
            import polib
        except ImportError:
            self.skipTest('polib not installed')
        offenders = []
        for lang in self.LANGS:
            for catalog in self.CATALOGS:
                path = os.path.join(os.path.dirname(__file__), '..', 'locale',
                                    lang, 'LC_MESSAGES', catalog)
                if not os.path.exists(path):
                    continue
                for entry in polib.pofile(path):
                    if entry.obsolete or not entry.msgstr:
                        continue
                    wanted = sorted(self.MARK.findall(entry.msgid))
                    for text in [entry.msgstr] + list(
                            entry.msgstr_plural.values()):
                        if text and sorted(self.MARK.findall(text)) != wanted:
                            offenders.append(
                                '%s/%s: %s -> %s' % (lang, catalog,
                                                     entry.msgid[:40],
                                                     text[:60]))
        self.assertEqual(offenders, [],
                         'a translation changed its placeholders: %s' % offenders)


class NoMojibakeInTranslationsTests(SimpleTestCase):
    """A wrong-encoding .po turns accents into ? and still passes msgfmt."""

    LANGS = ('en', 'fr', 'es', 'pt', 'de')
    CATALOGS = ('django.po', 'djangojs.po')
    MOJIBAKE = re.compile(r'[^\W\d_]\?[^\W\d_]', re.UNICODE)

    @staticmethod
    def _suspicious(msgid, text):
        if NoMojibakeInTranslationsTests.MOJIBAKE.search(text):
            return True
        body = text.rstrip()
        if body.endswith('?'):
            body = body[:-1]
        return body.count('?') > msgid.count('?')

    def test_no_question_mark_mojibake_in_any_msgstr(self):
        try:
            import polib
        except ImportError:
            self.skipTest('polib not installed')
        offenders = []
        for lang in self.LANGS:
            for catalog in self.CATALOGS:
                path = os.path.join(os.path.dirname(__file__), '..', 'locale',
                                    lang, 'LC_MESSAGES', catalog)
                if not os.path.exists(path):
                    continue
                for entry in polib.pofile(path):
                    if entry.obsolete:
                        continue
                    candidates = [entry.msgstr] + list(entry.msgstr_plural.values())
                    for text in candidates:
                        if text and self._suspicious(entry.msgid, text):
                            offenders.append('%s/%s: %s -> %s'
                                             % (lang, catalog, entry.msgid[:40],
                                                text[:60]))
        self.assertEqual(
            offenders, [],
            'mojibake question marks found in translations (broken accents, '
            'rewrite the .po in UTF-8): %s' % offenders)


class StatRangeTests(TestCase):
    """Both ends of a stat roll are stored, the solver uses the best roll."""

    def test_the_range_is_stored_but_the_solver_still_reads_the_best_roll(self):
        from fashionistapulp.structure import get_structure
        structure = get_structure('dofus3')
        item = structure.get_item_by_name('Tynril Hat')
        self.assertIsNotNone(item)
        vitality = structure.get_stat_by_key('vit').id
        self.assertEqual(item.stat_ranges[vitality], (201, 250))
        self.assertIn((vitality, 250), item.stats)
        action_points = structure.get_stat_by_key('ap').id
        self.assertNotIn(action_points, item.stat_ranges)

    def test_retro_characteristics_carry_their_range_too(self):
        """Retro 1.29 carries #min#max on characteristics too."""
        from fashionistapulp.structure import get_structure
        structure = get_structure('retro')
        vitality = structure.get_stat_by_key('vit').id

        bonus = structure.get_item_by_name('Moowish Belt')
        self.assertIsNotNone(bonus, msg='the Retro item this test names is gone')
        self.assertEqual((151, 300), bonus.stat_ranges[vitality])
        self.assertIn((vitality, 300), bonus.stats)

        # A malus keeps its best roll, the end nearest zero
        malus = structure.get_item_by_name('Fwell Sword')
        self.assertIsNotNone(malus, msg='the Retro item this test names is gone')
        self.assertEqual((-8, -4), malus.stat_ranges[vitality])
        self.assertIn((vitality, -4), malus.stats)

    def test_the_item_page_shows_the_range_in_each_language(self):
        expected = {'en': '201 to 250', 'fr': '201 à 250', 'es': '201 a 250',
                    'pt': '201 a 250', 'de': '201 bis 250'}
        for language, text in expected.items():
            resp = self.client.get('/encyclopedia/item/equipment/8699-x/',
                                   HTTP_ACCEPT_LANGUAGE=language, follow=True)
            self.assertEqual(resp.status_code, 200)
            with self.subTest(language=language):
                self.assertContains(resp, text)

    def test_every_version_with_range_data_shows_it(self):
        from fashionistapulp.structure import get_structure
        # Same sword in four games: the roll differs per version.
        expected = {'dofus3': ('44', '7 à 10'), 'beta': ('44', '7 à 10'),
                    'dofus2': ('44', '7 à 10'), 'touch': ('47', '11 à 15')}
        prefixes = {'dofus3': '', 'beta': '/beta', 'dofus2': '/dofus2',
                    'touch': '/touch'}
        for version, (ankama_id, text) in expected.items():
            resp = self.client.get('%s/encyclopedia/item/equipment/%s-x/'
                                   % (prefixes[version], ankama_id),
                                   HTTP_ACCEPT_LANGUAGE='fr', follow=True)
            with self.subTest(version=version):
                self.assertEqual(resp.status_code, 200)
                self.assertContains(resp, text)

    def test_retro_shows_its_stat_ranges_like_the_other_versions(self):
        """retro_raw/itemstats_fr.json carries #min#max on characteristics."""
        import sqlite3
        from fashionistapulp.fashionista_config import get_items_db_path
        conn = sqlite3.connect(get_items_db_path('retro'))
        try:
            ranged = conn.execute(
                'SELECT COUNT(*) FROM stats_of_item '
                'WHERE min_value IS NOT NULL AND max_value IS NOT NULL '
                'AND min_value <> max_value').fetchone()[0]
            outside = conn.execute(
                'SELECT COUNT(*) FROM stats_of_item '
                'WHERE min_value IS NOT NULL AND max_value IS NOT NULL '
                'AND (value < min_value OR value > max_value)').fetchone()[0]
        finally:
            conn.close()
        self.assertGreater(ranged, 10000)
        # Catches ranges stored against the wrong row
        self.assertEqual(0, outside)

        # Vitality rolls 151 to 300 on this one
        resp = self.client.get('/retro/encyclopedia/item/equipment/2807-x/',
                               HTTP_ACCEPT_LANGUAGE='fr', follow=True)
        self.assertEqual(resp.status_code, 200)
        self.assertContains(resp, '151 à 300')

        # A fixed Strength still shows a bare number
        resp = self.client.get('/retro/encyclopedia/item/equipment/44-x/',
                               HTTP_ACCEPT_LANGUAGE='fr', follow=True)
        self.assertEqual(resp.status_code, 200)
        self.assertContains(resp, 'Force')


class StatRangeInThePickerTests(TestCase):
    """Roll range in the item picker, same wording as the encyclopedia."""

    def _stat_lines(self, item_name, version='dofus3'):
        from chardata.solution_result import evolve_result_item
        from fashionistapulp.modelresult import ModelResultItem
        from fashionistapulp.structure import get_structure, set_current_game_version
        self.addCleanup(set_current_game_version, 'dofus3')
        set_current_game_version(version)
        structure = get_structure(version)
        item = structure.get_item_by_name(item_name)
        self.assertIsNotNone(item, item_name)
        result_item = ModelResultItem(item)
        evolve_result_item(result_item)
        return {line.text: line for line in result_item.stats_lines}

    def test_a_varying_stat_carries_its_range_and_a_fixed_one_does_not(self):
        lines = self._stat_lines('Tynril Hat')
        self.assertEqual(lines['250 Vitality'].range_text, '201 to 250')
        self.assertEqual(lines['1 AP'].range_text, None)

    def test_the_range_is_worded_in_the_reader_language(self):
        from django.utils import translation
        expected = {'en': '201 to 250', 'fr': '201 à 250', 'es': '201 a 250',
                    'pt': '201 a 250', 'de': '201 bis 250'}
        for language, text in expected.items():
            with self.subTest(language=language):
                with translation.override(language):
                    lines = self._stat_lines('Tynril Hat')
                    ranges = [line.range_text for line in lines.values()
                              if line.range_text]
                    self.assertIn(text, ranges)

    def test_retro_items_carry_their_range_in_the_picker_too(self):
        """Adili Sword: a rolling bonus, a rolling malus and a fixed stat."""
        lines = self._stat_lines('Adili Sword', version='retro')
        self.assertTrue(lines)
        self.assertEqual('21 to 40', lines['40 Strength'].range_text)
        self.assertEqual('-10 to -9', lines['-9 Agility'].range_text)
        self.assertIsNone(lines['5 Intelligence'].range_text)

    def test_the_encyclopedia_and_the_picker_use_the_same_formatter(self):
        from chardata import encyclopedia_view
        from chardata import solution_result
        self.assertIs(encyclopedia_view.format_stat_range,
                      solution_result.format_stat_range)


class CharacterPreviewIsOffTests(TestCase):
    """Character preview off: every page shows the class avatar."""

    def _shared_build(self, owner=None):
        import pickle as _pickle
        from django.contrib.auth.models import User
        from chardata.models import Char
        from fashionistapulp.modelresult import ModelResultMinimal
        from fashionistapulp.structure import get_structure
        hat = next(item for item
                   in get_structure('dofus3').get_unique_items_by_type_and_level('Hat', 200)
                   if not item.removed and item.ankama_id)
        tag = 'off%d' % (Char.objects.count() + 1)
        if owner is None:
            owner = User.objects.create_user(tag, '%s@test.local' % tag,
                                             'pw-42-solid')
        char = Char.objects.create(
            name='OffBuild', char_name=tag, char_class='Iop',
            char_build='build', level=200, minimum_stats=b'',
            minimum_crits=b'', stats_weight=_pickle.dumps({'str': 1}),
            options=b'', inclusions=b'', exclusions=b'',
            minimal_solution=_pickle.dumps(ModelResultMinimal(
                {'hat': hat.id},
                {'options': {'ap_exo': False, 'mp_exo': False},
                 'origin': 'generated', 'char_level': 200,
                 'base_stats_by_attr': {'Vitality': 0, 'Wisdom': 0,
                                        'Strength': 0, 'Intelligence': 0,
                                        'Chance': 0, 'Agility': 0},
                 'locked_equips': {}}, {})),
            owner=owner, link_shared=True, game_version='dofus3')
        return owner, char

    def test_the_setting_is_off_in_the_shipped_configuration(self):
        from django.conf import settings
        self.assertFalse(getattr(settings, 'CHARACTER_PREVIEW', False))

    @override_settings(CHARACTER_PREVIEW=False)
    def test_no_look_is_built_while_it_is_off(self):
        from chardata.character_look import get_character_look, preview_is_on
        _owner, char = self._shared_build()
        self.assertFalse(preview_is_on())
        for version in ('dofus3', 'beta', 'dofus2', 'touch', 'retro'):
            self.assertIsNone(get_character_look(char, None, version), version)

    @override_settings(CHARACTER_PREVIEW=False)
    def test_a_build_page_shows_the_avatar_and_no_canvas(self):
        owner, char = self._shared_build()
        self.client.force_login(owner)
        resp = self.client.get('/solution/%d/' % char.pk)
        self.assertEqual(200, resp.status_code)
        body = resp.content.decode()
        for marker in ('character-preview', 'char-banner-controls',
                       'character_preview.js', 'char-banner-piece-box'):
            self.assertNotIn(marker, body, marker)
        self.assertIn('char-banner-avatar', body)
        self.assertNotIn('display:none', body.split('char-banner-avatar')[1][:80])

    @override_settings(CHARACTER_PREVIEW=False)
    def test_the_comparison_page_draws_no_character_either(self):
        owner, first = self._shared_build()
        second = self._shared_build(owner)[1]
        self.client.force_login(owner)
        resp = self.client.get('/compare_sets/%d/%d/' % (first.pk, second.pk))
        self.assertEqual(200, resp.status_code)
        body = resp.content.decode()
        self.assertNotIn('compare-preview-canvas', body)
        self.assertNotIn('character_preview.js', body)

    @override_settings(CHARACTER_PREVIEW=False)
    def test_the_account_page_hides_the_size_it_can_no_longer_use(self):
        owner, _char = self._shared_build()
        self.client.force_login(owner)
        resp = self.client.get('/manageaccount/', HTTP_ACCEPT_LANGUAGE='en')
        self.assertEqual(200, resp.status_code)
        self.assertNotIn('id="preview_size"', resp.content.decode())


@override_settings(CHARACTER_PREVIEW=True)
class CharacterLookTests(TestCase):
    """The preview needs a body and head per class, and a skin per shown piece."""

    def _char(self, char_class):
        from chardata.models import Char
        return Char.objects.create(
            name='look', char_name='hero', char_class=char_class, char_build='build',
            level=200, minimum_stats=b'', minimum_crits=b'', stats_weight=b'',
            options=b'', inclusions=b'', exclusions=b'', link_shared=False,
            game_version='dofus3')

    def test_every_class_the_site_offers_has_a_look(self):
        from fashionistapulp.dofus_constants import CHARACTER_CLASSES
        from chardata.character_look import CLASS_TO_BREED, _breed_looks
        looks = _breed_looks()
        for char_class in CHARACTER_CLASSES:
            with self.subTest(char_class=char_class):
                breed = CLASS_TO_BREED.get(char_class)
                self.assertIsNotNone(breed, char_class)
                entry = looks.get('%d-0' % breed)
