class AdminAdSettingsTests(TestCase):
    """Ad settings live in the db, gen_config.json is read at boot only."""

    def setUp(self):
        from django.contrib.auth.models import User
        from django.core.cache import cache
        cache.clear()
        self.admin = User.objects.create_superuser(
            'adboss', 'adboss@example.com', 'pw')
        self.client.force_login(self.admin)

    def _post(self, **data):
        return self.client.post('/admin-ads-action/', data)

    def test_a_visitor_cannot_reach_the_form_or_the_action(self):
        self.client.logout()
        self.assertEqual(404, self.client.get('/admin-tools/').status_code)
        self.assertEqual(404, self._post(enabled='1').status_code)

    def test_saved_slot_ids_come_back_out_of_the_processor(self):
        from django.test import RequestFactory
        from chardata.context_processors import ads
        self.assertEqual(200, self._post(enabled='1',
                                         slot_home_top='2586036395').status_code)
        request = RequestFactory().get('/')
        request.game_version = 'dofus3'
        values = ads(request)
        self.assertTrue(values['ads_enabled'])
        self.assertEqual('2586036395', values['ad_slots']['home_top'])

    def test_the_switch_takes_effect_without_a_restart(self):
        from django.test import RequestFactory
        from chardata.context_processors import ads
        self._post(enabled='1', slot_home_top='2586036395')
        self._post(slot_home_top='2586036395')
        request = RequestFactory().get('/')
        request.game_version = 'dofus3'
        values = ads(request)
        self.assertFalse(values['ads_allowed'])
        self.assertEqual({}, values['ad_slots'])

    def _script_tag(self):
        import re
        body = self.client.get('/about/').content.decode('utf-8')
        found = re.search(r'<script[^>]*adsbygoogle\.js[^>]*>', body)
        self.assertIsNotNone(found, 'the adsense script is gone')
        return found.group(0), body

    def test_auto_ads_can_be_turned_off_without_losing_the_units(self):
        # data-ad-client on the script tag turns auto ads on
        self._post(enabled='1', auto='1', slot_footer='6811885155')
        tag, body = self._script_tag()
        self.assertIn('data-ad-client', tag)
        self.assertIn('6811885155', body)

        self._post(enabled='1', slot_footer='6811885155')
        tag, body = self._script_tag()
        self.assertNotIn('data-ad-client', tag)
        self.assertIn('6811885155', body)

    def test_a_slot_id_that_is_not_a_number_is_refused(self):
        resp = self._post(enabled='1', slot_home_top='<script>')
        self.assertEqual(400, resp.status_code)

    def test_the_form_shows_what_is_stored(self):
        self._post(enabled='1', slot_footer='6811885155')
        body = self.client.get('/admin-tools/').content.decode('utf-8')
        self.assertIn('6811885155', body)
        self.assertIn('admin-ads-form', body)


class SitemapIndexTests(TestCase):
    """Google refuses a sitemap over 50000 urls: one file per section."""

    LIMIT = 50000

    def _locs(self, path):
        import re
        resp = self.client.get(path)
        self.assertEqual(resp.status_code, 200, path)
        return re.findall(r'<loc>([^<]+)</loc>', resp.content.decode('utf-8'))

    def test_the_index_points_at_every_section(self):
        from fashionsite.urls import SITEMAP_SECTIONS
        children = self._locs('/sitemap.xml')
        self.assertEqual(len(children), len(SITEMAP_SECTIONS))
        for name, _builder in SITEMAP_SECTIONS:
            self.assertTrue(any(child.endswith('/sitemap-%s.xml' % name)
                                for child in children), name)

    def test_no_section_comes_near_the_limit(self):
        for child in self._locs('/sitemap.xml'):
            path = child.split('dofusfashionista.gg', 1)[1]
            with self.subTest(section=path):
                self.assertLess(len(self._locs(path)), self.LIMIT)

    def test_the_sections_together_still_cover_everything(self):
        total = sum(len(self._locs(child.split('dofusfashionista.gg', 1)[1]))
                    for child in self._locs('/sitemap.xml'))
        self.assertGreater(total, 30000)

    def test_a_section_nobody_publishes_is_not_served(self):
        self.assertEqual(self.client.get('/sitemap-nope.xml').status_code, 404)


class EncyclopediaPaginationTests(TestCase):
    """Hub pagination keeps the first and last pages in reach."""

    HUBS = ('/encyclopedia/', '/encyclopedia/monsters/', '/encyclopedia/sets/')

    def _links(self, path):
        import re
        html = self.client.get(path).content.decode('utf-8')
        block = re.search(r'<div class="encyclopedia-pagination">(.*?)</div>',
                          html, re.S)
        self.assertIsNotNone(block, path)
        return re.findall(r'page=(\d+)"', block.group(1))

    def test_the_first_and_last_pages_are_always_one_click_away(self):
        for hub in self.HUBS:
            with self.subTest(hub=hub):
                first = self._links(hub)
                self.assertTrue(first, hub)
                last = max(int(n) for n in first)
                if last < 8:
                    continue
                self.assertIn(str(last), first)
                middle = self._links('%s?page=%d' % (hub, last // 2))
                self.assertIn('1', middle, hub)
                self.assertIn(str(last), middle, hub)

    def test_the_window_around_the_current_page_is_still_there(self):
        links = self._links('/encyclopedia/monsters/?page=40')
        for near in ('37', '38', '39', '41', '42', '43'):
            self.assertIn(near, links)


class MonsterSitemapTests(SimpleTestCase):
    """Which monster pages are pushed for indexing."""

    def _submitted(self, game_version='dofus3'):
        import re
        from fashionsite import urls
        xml = urls._sitemap_encyclopedia_monsters('https://dofusfashionista.gg')
        prefix = '' if game_version == 'dofus3' else '/' + game_version
        out = set()
        for loc in re.findall(r'<loc>([^<]+)</loc>', xml):
            tail = loc.split('dofusfashionista.gg', 1)[1]
            head = tail.split('/')[1]
            known = head in ('beta', 'retro', 'touch', 'dofus2')
            if (('/' + head) if known else '') != prefix:
                continue
            found = re.search(r'/monster/(\d+)-', tail)
            if found:
                out.add(int(found.group(1)))
        return out

    def _counts(self, game_version='dofus3'):
        import sqlite3
        from fashionistapulp.fashionista_config import get_items_db_path
        conn = sqlite3.connect(get_items_db_path(game_version))
        try:
            return {row[0]: row[1] for row in conn.execute("""
                SELECT monster_ankama_id, COUNT(*) FROM (
                    SELECT monster_ankama_id FROM item_drops
                    UNION ALL SELECT monster_ankama_id FROM resource_drops)
                GROUP BY 1""")}
        finally:
            conn.close()

    def test_a_page_with_one_drop_but_stats_and_spells_is_worth_indexing(self):
        import sqlite3
        from chardata.encyclopedia_view import has_display_name
        from fashionistapulp.fashionista_config import get_items_db_path
        submitted = self._submitted()
        drops = self._counts()
        thin = [m for m, n in drops.items() if n < 2]
        conn = sqlite3.connect(get_items_db_path('dofus3'))
        try:
            rich = {row[0] for row in conn.execute("""
                SELECT s.monster_ankama_id FROM monster_spells s
                WHERE (SELECT COUNT(*) FROM monster_grades g
                       WHERE g.monster_ankama_id = s.monster_ankama_id) >= 2
                GROUP BY s.monster_ankama_id
                HAVING COUNT(DISTINCT s.spell_ankama_id) >= 2""")}
            # A monster with no name in any language gets no page either
            named = set()
            for monster_id, language, name in conn.execute(
                    'SELECT monster_ankama_id, language, name FROM monster_names'):
                if has_display_name({language: name}):
                    named.add(monster_id)
        finally:
            conn.close()
        with_content = [m for m in thin if m in rich and m in named]
        self.assertGreater(len(with_content), 1000)
        missing = [m for m in with_content if m not in submitted]
        self.assertEqual(missing, [], 'thin-but-rich pages left out')

    def test_a_page_with_nothing_on_it_stays_out(self):
        submitted = self._submitted()
        drops = self._counts()
        for monster, count in drops.items():
            if count >= 2:
                continue
            if monster in submitted:
                continue
            break
        else:
            self.fail('nothing was left out at all')

    def test_the_versions_without_spell_data_keep_the_old_rule(self):
        # Retro and Touch pages are drops and stats only
        for version in ('retro', 'touch'):
            with self.subTest(version=version):
                submitted = self._submitted(version)
                drops = self._counts(version)
                for monster in submitted:
                    self.assertGreaterEqual(drops.get(monster, 0), 2, monster)


class MonsterSpellTests(TestCase):
    """Monster spells on the encyclopedia page, from the datacenter dump."""

    VERSIONS = ('dofus3', 'beta')
    # Strawberry Jelly, casts four spells
    JELLY = 57

    def _rows(self, version, sql, args=()):
        import sqlite3
        from fashionistapulp.fashionista_config import get_items_db_path
        conn = sqlite3.connect(get_items_db_path(version))
        try:
            return conn.execute(sql, args).fetchall()
        finally:
            conn.close()

    def test_a_monster_carries_the_spells_the_dump_gives_it(self):
        for version in self.VERSIONS:
            rows = self._rows(version, """
                SELECT ms.position, ms.spell_ankama_id, n.name
                FROM monster_spells ms
                JOIN monster_spell_names n
                  ON n.spell_ankama_id = ms.spell_ankama_id AND n.language = 'en'
                WHERE ms.monster_ankama_id = ?
                ORDER BY ms.position""", (self.JELLY,))
            with self.subTest(version=version):
                self.assertEqual(
                    [(row[1], row[2]) for row in rows],
                    [(321, 'Gelpikes'), (29839, 'Tasty Spread'),
                     (29844, 'Jellifier'), (267, 'Strawberry Bone')])

    def test_every_stored_spell_has_a_name_to_show(self):
        for version in self.VERSIONS:
            nameless = self._rows(version, """
                SELECT COUNT(*) FROM monster_spells ms
                LEFT JOIN monster_spell_names n
                  ON n.spell_ankama_id = ms.spell_ankama_id AND n.language = 'en'
                WHERE n.name IS NULL""")[0][0]
            with self.subTest(version=version):
                self.assertEqual(nameless, 0)

    def test_a_spell_knows_what_it_costs_and_how_far_it_reaches(self):
        rows = self._rows('dofus3', """
            SELECT grade, ap_cost, range_min, range_max
            FROM monster_spell_levels WHERE spell_ankama_id = 29844""")
        self.assertIn((1, 3, 0, 4), rows)

    def test_the_grade_mapping_keeps_the_spell_grade_not_the_level_id(self):
        # Dump format: "<spell grade>,<level id>" per monster grade
        from chardata.encyclopedia_view import _monster_spells
        _store_monster_spells = itemscraper_module('store_monster_spells')
        parse_grade_mapping = _store_monster_spells.parse_grade_mapping
        self.assertEqual(parse_grade_mapping('1,54;1,56;1,58;1,60;1,62'),
                         [1, 1, 1, 1, 1])
        self.assertEqual(parse_grade_mapping('3,54;4,56'), [3, 4])
        self.assertEqual(parse_grade_mapping(''), [])
        self.assertEqual(parse_grade_mapping(None), [])
        self.assertTrue(callable(_monster_spells))

    def test_the_description_only_promises_spells_where_there_are_some(self):
        import re
        import sqlite3
        from fashionistapulp.fashionista_config import get_items_db_path
        conn = sqlite3.connect(get_items_db_path('retro'))
        try:
            retro_id = conn.execute(
                "SELECT monster_ankama_id FROM monster_names "
                "WHERE language = 'en' LIMIT 1").fetchone()[0]
        finally:
            conn.close()

        # Django reorders the attributes: content comes before name
        described = re.compile(
            r'<meta content="([^"]*)" name="description"\s*/?>')

        with_spells = self.client.get(
            '/encyclopedia/monster/%d-x/' % self.JELLY,
            follow=True).content.decode('utf-8')
        self.assertIn('id="monster-spells"', with_spells)
        self.assertIn('spells it casts', described.search(with_spells).group(1))

        without = self.client.get(
            '/retro/encyclopedia/monster/%d-x/' % retro_id,
            follow=True).content.decode('utf-8')
        self.assertNotIn('id="monster-spells"', without)
        self.assertNotIn('spell', described.search(without).group(1))

    def test_the_page_lists_them(self):
        import sqlite3
        from fashionistapulp.fashionista_config import get_items_db_path
        conn = sqlite3.connect(get_items_db_path('dofus3'))
        try:
            name = conn.execute(
                "SELECT name FROM monster_names WHERE monster_ankama_id = ? "
                "AND language = 'en'", (self.JELLY,)).fetchone()[0]
        finally:
            conn.close()
        from chardata.official_site import get_monster_link
        resp = self.client.get(get_monster_link(self.JELLY, name))
        self.assertEqual(resp.status_code, 200)
        page = resp.content.decode('utf-8')
        self.assertIn(name, page)
        self.assertIn('id="monster-spells"', page)
        for spell in ('Gelpikes', 'Tasty Spread', 'Jellifier', 'Strawberry Bone'):
            self.assertIn(spell, page)


class CombatApTests(SimpleTestCase):
    """The solution total already includes the base AP."""

    def test_the_turn_uses_the_ap_the_character_actually_has(self):
        # Level 200: 7 base AP + 4 from gear
        from chardata.spell_combo import combat_ap
        self.assertEqual(11, combat_ap(11, 'dofus3'))
        self.assertEqual(8, combat_ap(8, 'dofus3'))

    def test_a_build_saved_without_base_stats_still_has_a_turn(self):
        from chardata.spell_combo import BASE_AP, combat_ap
        self.assertEqual(BASE_AP, combat_ap(0, 'dofus3'))
        self.assertEqual(BASE_AP, combat_ap(None, 'dofus3'))

    def test_the_modern_versions_stop_at_twelve(self):
        from chardata.spell_combo import combat_ap
        for version in ('dofus3', 'beta', 'dofus2', 'touch'):
            with self.subTest(version=version):
                self.assertEqual(12, combat_ap(12, version))
                self.assertEqual(12, combat_ap(13, version))
                self.assertEqual(12, combat_ap(20, version))

    def test_retro_never_got_the_limitation(self):
        from chardata.spell_combo import combat_ap
        self.assertEqual(15, combat_ap(15, 'retro'))

    def test_a_state_gated_spell_counts_one_state_not_all(self):
        # Schnaps: sober or drunk, never both. Trickery: one element of four
        from chardata.spell_buffs import (_decide_spell_level,
                                          get_damage_spells_for_version)
        from chardata.spell_combo import Castable
        # Abolition Arrow: *e means the state is absent, one case per row
        wanted = {'Pandawa': ('Schnaps', 1), 'Ecaflip': ('Trickery', 2),
                  'Cra': ('Abolition Arrow', 2)}
        for char_class, (name, keep) in wanted.items():
            spells = get_damage_spells_for_version('dofus3').get(char_class, [])
            spell = next((s for s in spells if s.name == name), None)
            self.assertIsNotNone(spell, name)
            level = _decide_spell_level(spell.level_req, 200)
            castable = Castable(spell, level, False)
            with self.subTest(spell=name):
                self.assertTrue(spell.get_effects_digest().aggregates, name)
                self.assertEqual(keep, len(castable.hits), name)

    def test_the_same_damage_written_once_per_case_counts_once(self):
        # One row per case, same damage in each (Bramble, Epidemic)
        from chardata.spell_buffs import (_decide_spell_level,
                                          get_damage_spells_for_version)
        from chardata.spell_combo import Castable
        wanted = {'Sadida': (13516, 24, 27), 'Sram': (12943, 36, 40),
                  'Osamodas': (31132, 23, 26), 'Xelor': (13286, 16, 18),
                  'Eliotrope': (14593, 26, 29)}
        for char_class, (spell_id, low, high) in wanted.items():
            spells = get_damage_spells_for_version('dofus3').get(char_class, [])
            spell = next((s for s in spells if s.spell_id == spell_id), None)
            self.assertIsNotNone(spell, spell_id)
            castable = Castable(spell, _decide_spell_level(spell.level_req, 200),
                                False)
            with self.subTest(spell=spell.name):
                self.assertEqual(1, len(castable.hits), spell.name)
                self.assertEqual((low, high), (castable.hits[0].min_dam,
                                               castable.hits[0].max_dam))

    def test_a_fixed_damage_is_not_a_range_ending_at_zero(self):
        # A fixed hit is a min with no max; max 0 means no row at that level
        from chardata.spell_buffs import get_damage_spells_for_version
        for version in ('dofus3', 'beta', 'dofus2', 'retro', 'touch'):
            for char_class, spells in get_damage_spells_for_version(version).items():
                for spell in spells:
                    for level in (spell.get_effects_digest().non_crit_dams or []):
                        for row in level:
                            if row.element.startswith('buff'):
                                continue
                            with self.subTest(version=version, spell=spell.name):
                                self.assertFalse(row.max_dam == 0 and row.min_dam > 0,
                                                 spell.name)

    def test_groups_that_print_the_same_line_are_one_line(self):
        from chardata.spell_buffs import get_damage_spells_for_version
        for version in ('dofus3', 'beta', 'dofus2', 'retro', 'touch'):
            for char_class, spells in get_damage_spells_for_version(version).items():
                for spell in spells:
                    digest = spell.get_effects_digest()
                    groups = digest.aggregates
                    if not groups or len(groups) < 2 or groups[0][0] or groups[1][0]:
                        continue
                    rows = digest.non_crit_dams[-1] if digest.non_crit_dams else []

                    def shape(group):
                        return tuple((rows[i].element, rows[i].min_dam, rows[i].max_dam)
                                     for i in group[1] if i < len(rows))

                    with self.subTest(version=version, spell=spell.name):
                        self.assertTrue(not shape(groups[0])
                                        or shape(groups[0]) != shape(groups[1]),
                                        spell.name)

    def test_a_row_a_patch_copied_is_not_a_second_hit(self):
        # The four Huppermage elemental basics carry each damage row twice
        from chardata.spell_buffs import (_decide_spell_level,
                                          get_damage_spells_for_version)
        from chardata.spell_combo import Castable
        wanted = {13712: (13, 15), 13711: (14, 16), 13709: (11, 13),
                  13708: (12, 14)}
        spells = get_damage_spells_for_version('dofus3').get('Huppermage', [])
        for spell_id, (low, high) in wanted.items():
            spell = next((s for s in spells if s.spell_id == spell_id), None)
            self.assertIsNotNone(spell, spell_id)
            castable = Castable(spell, _decide_spell_level(spell.level_req, 200),
                                False)
            with self.subTest(spell=spell.name):
                self.assertEqual(1, len(castable.hits), spell.name)
                self.assertEqual((low, high), (castable.hits[0].min_dam,
                                               castable.hits[0].max_dam))

    def test_dofus2_counts_the_same_damage_once_too(self):
        # Both carry one damage row at their top grade in 2.73
        from chardata.spell_buffs import (_decide_spell_level,
                                          get_damage_spells_for_version)
        from chardata.spell_combo import Castable
        wanted = {'Cra': (13047, 23, 27), 'Eliotrope': (14575, 26, 28)}
        for char_class, (spell_id, low, high) in wanted.items():
            spells = get_damage_spells_for_version('dofus2').get(char_class, [])
            spell = next((s for s in spells if s.spell_id == spell_id), None)
            self.assertIsNotNone(spell, spell_id)
            castable = Castable(spell, _decide_spell_level(spell.level_req, 200),
                                False)
            with self.subTest(spell=spell.name):
                self.assertEqual(1, len(castable.hits), spell.name)
                self.assertEqual((low, high), (castable.hits[0].min_dam,
                                               castable.hits[0].max_dam))

    def test_every_class_gets_a_turn_it_can_play(self):
        from fashionistapulp.structure import get_structure
        from chardata.spell_combo import best_turn, castable_spells, combat_ap
        from chardata.translation_util import LOCALIZED_CHARACTER_CLASSES
        stats = {stat.key: 0 for stat in get_structure('dofus3').get_stats_list()}
        stats.update({'str': 300, 'int': 300, 'cha': 300, 'agi': 300, 'dam': 40})
        ap = combat_ap(0, 'dofus3')
        for char_class in sorted(LOCALIZED_CHARACTER_CLASSES):
            with self.subTest(char_class=char_class):
                spells = castable_spells(char_class, 200, 'dofus3')
                self.assertGreater(len(spells), 5, char_class)
                total, order = best_turn(stats, spells, ap)
                self.assertGreater(len(order), 0, char_class)
                self.assertGreater(total, 0, char_class)
                self.assertLessEqual(
                    sum(spell.cost for spell in spells
                        if spell.name in {name for name, _ in order[:1]}), ap)

    def test_the_panel_now_has_something_to_spend(self):
        from chardata.spell_combo import best_turn, castable_spells, combat_ap
        spells = castable_spells('Iop', 200, 'dofus3')
        self.assertGreater(len(spells), 10)
        from fashionistapulp.structure import get_structure
        stats = {stat.key: 0 for stat in get_structure('dofus3').get_stats_list()}
        stats.update({'str': 500, 'dam': 50, 'pow': 100})
        total, order = best_turn(stats, spells, combat_ap(0, 'dofus3'))
        self.assertGreater(total, 0, 'no cast fits in a bare turn')
        self.assertGreater(len(order), 0)


class _ComboChar(object):

    def __init__(self, char_class, level=200):
        self.char_class = char_class
        self.level = level


class _ComboSolution(object):

    def __init__(self, stats):
        self._stats = stats

    def get_stats_total(self):
        return dict(self._stats)


def _combo_stats(version='dofus3', **overrides):
    from fashionistapulp.structure import get_structure
    stats = {stat.key: 0 for stat in get_structure(version).get_stats_list()}
    stats.update({'ap': 6, 'str': 300, 'int': 300, 'cha': 300, 'agi': 300})
    stats.update(overrides)
    return stats


class FinalDamageReachesTheTurnTests(SimpleTestCase):
    """A buff granting only final damage still lifts the turn."""

    def _spells_granting_final(self, version):
        from chardata.spell_buffs import get_damage_spells_for_version
        found = []
        for char_class, spells in get_damage_spells_for_version(version).items():
            if char_class == 'default':
                continue
            for spell in spells:
                rows = spell.get_effects_digest().non_crit_dams or []
                if any(effect.element == 'buff_final'
                       for row in rows for effect in row):
                    found.append((char_class, spell))
        return found

    def test_final_damage_is_not_a_gear_stat_anywhere(self):
        # Only spells grant final damage
        from fashionistapulp.structure import get_structure
        for version in ('dofus3', 'beta', 'dofus2', 'retro', 'touch'):
            keys = {stat.key for stat in get_structure(version).get_stats_list()}
            with self.subTest(version=version):
                self.assertNotIn('final', keys)

    def test_the_final_percentage_multiplies_the_turn(self):
        from chardata.spell_combo import best_turn, castable_spells
        spells = [spell for spell in castable_spells('Iop', 200, 'dofus3')
                  if spell.name == 'Pressure']
        self.assertEqual(1, len(spells))
        plain, _order = best_turn(_combo_stats(), spells, 6)
        self.assertGreater(plain, 0)
        for percent in (2, 10, 25):
            with self.subTest(percent=percent):
                lifted, _order = best_turn(_combo_stats(final=percent), spells, 6)
                self.assertAlmostEqual(plain * (100 + percent) / 100.0, lifted,
                                       places=6)

    def test_a_ticked_portal_lifts_the_eliotrope_turn(self):
        from chardata.spells_view import _best_combo
        char = _ComboChar('Eliotrope')
        solution = _ComboSolution(_combo_stats())
        off = _best_combo(char, solution, 'dofus3', {'Portal': 'n0'})
        on = _best_combo(char, solution, 'dofus3', {'Portal': 'n1'})
        self.assertTrue(off and on)
        self.assertGreater(on['total'], off['total'])

    def test_every_spell_that_grants_it_moves_its_own_turn(self):
        from chardata.spells_view import _best_combo
        for version in ('dofus3', 'beta'):
            granting = self._spells_granting_final(version)
            self.assertTrue(granting, version)
            for char_class, spell in granting:
                with self.subTest(version=version, spell=spell.name):
                    char = _ComboChar(char_class)
                    solution = _ComboSolution(_combo_stats(version))
                    off = _best_combo(char, solution, version,
                                      {spell.name: 'n0'})
                    on = _best_combo(char, solution, version,
                                     {spell.name: 'n%d' % spell.stacks})
                    self.assertTrue(off and on)
                    self.assertGreater(on['total'], off['total'])

    def test_dofus2_has_a_turn_to_lift_like_the_others(self):
        from chardata.spell_buffs import get_damage_spells_for_version
        from chardata.spell_combo import castable_spells
        spells = [spell
                  for char_class, bucket
                  in get_damage_spells_for_version('dofus2').items()
                  if char_class != 'default'
                  for spell in bucket]
        self.assertTrue(spells)
        self.assertEqual([], [spell.name for spell in spells
                              if not spell.casting])
        self.assertTrue(castable_spells('Eliotrope', 200, 'dofus2'))

    def test_retro_and_touch_have_no_such_buff_to_lose(self):
        for version in ('retro', 'touch'):
            with self.subTest(version=version):
                self.assertEqual([], self._spells_granting_final(version))


class ATickedBuffIsAlreadyStandingTests(SimpleTestCase):
    """A ticked buff is already standing: a recast only adds what is left."""

    def _with_buff(self, char_class, buff_state, ap=12):
        from chardata.spell_combo import buffs_in_force
        stats = _combo_stats(ap=ap, pow=100, dam=30, perspedam=20)
        for stat, delta in buffs_in_force(char_class, 200, 'dofus3',
                                          buff_state).items():
            stats[stat] = stats.get(stat, 0) + delta
        return stats

    def test_a_buff_at_its_cap_is_worth_nothing_to_recast(self):
        from chardata.spell_combo import best_turn, castable_spells
        spells = castable_spells('Cra', 200, 'dofus3')
        powerful = next(s for s in spells if s.name == 'Powerful Shots')
        self.assertEqual(1, powerful.stacks)
        stats = self._with_buff('Cra', {'Powerful Shots': 'n1'})
        standing = {'Powerful Shots': 1}
        once, _order = best_turn(stats, spells, 12, standing=standing)
        without = [s for s in spells if s.name != 'Powerful Shots']
        absent, _order = best_turn(stats, without, 12)
        self.assertAlmostEqual(absent, once, places=6)
        twice, _order = best_turn(stats, spells, 12)
        self.assertGreater(twice, once)

    def test_the_more_is_already_up_the_less_a_recast_can_add(self):
        from chardata.spell_combo import best_turn, castable_spells
        for char_class, name in (('Eliotrope', 'Portal'),
                                 ('Cra', 'Powerful Shots')):
            spells = castable_spells(char_class, 200, 'dofus3')
            stats = self._with_buff(char_class, {name: 'n1'})
            totals = [best_turn(stats, spells, 12, standing={name: held})[0]
                      for held in (0, 1, 2, 5, 10)]
            with self.subTest(char_class=char_class):
                self.assertEqual(sorted(totals, reverse=True), totals)

    def test_a_stacking_buff_at_its_cap_is_not_worth_an_ap(self):
        from chardata.spell_combo import best_turn, castable_spells
        spells = castable_spells('Eliotrope', 200, 'dofus3')
        stats = self._with_buff('Eliotrope', {'Portal': 'n10'})
        capped, _order = best_turn(stats, spells, 12, standing={'Portal': 10})
        without = [spell for spell in spells if spell.name != 'Portal']
        absent, _order = best_turn(stats, without, 12)
        self.assertAlmostEqual(absent, capped, places=6)

    def test_a_buff_from_the_shared_bucket_reaches_the_turn(self):
        # Both sit in the bucket every class shares
        from chardata.spell_combo import buffs_in_force, stacks_in_force
        for char_class in ('Cra', 'Iop', 'Eliotrope'):
            with self.subTest(char_class=char_class):
                deltas = buffs_in_force(char_class, 200, 'dofus3',
                                        {'Perfidious Boomerang': 'n1'})
                self.assertEqual({'str': 160, 'int': 160, 'cha': 160,
                                  'agi': 160}, deltas)
                self.assertEqual({'Perfidious Boomerang': 1},
                                 stacks_in_force(char_class, 200, 'dofus3',
                                                 {'Perfidious Boomerang': 'n1'}))

    def test_a_weapon_only_buff_lifts_the_weapon_and_no_spell(self):
        # Weapon Skill: +300 Power, weapons only
        from fashionistapulp.structure import get_structure
        from chardata.spell_combo import (best_turn, buffs_in_force,
                                          castable_spells)
        deltas = buffs_in_force('Cra', 200, 'dofus3', {'Weapon Skill': 'n1'})
        self.assertEqual({'powweap': 300}, deltas)

        stats = {stat.key: 0 for stat in get_structure('dofus3').get_stats_list()}
        stats.update({'str': 300, 'agi': 300, 'int': 300, 'cha': 300})
        spell = next(spell for spell in castable_spells('Cra', 200, 'dofus3')
                     if spell.alternatives)
        _item, weapon = WeaponInTheTurnTests()._weapon_with_damage()
        plain_spell, _o1 = best_turn(stats, [spell], spell.cost)
        plain_weapon, _o2 = best_turn(stats, [weapon], weapon.cost)
        buffed = dict(stats, **deltas)
        self.assertEqual(best_turn(buffed, [spell], spell.cost)[0], plain_spell)
        self.assertGreater(best_turn(buffed, [weapon], weapon.cost)[0],
                           plain_weapon)


class PortalsStackTenTimesTests(SimpleTestCase):
    """Portal and Wandering say max_stack -1: the cap of ten is in the text."""

    def _portal_spells(self, version):
        from chardata.spell_combo import castable_spells
        spells = {spell.name: spell
                  for spell in castable_spells('Eliotrope', 200, version)}
        return spells['Portal'], spells['Wandering']

    def test_a_portal_stacks_ten_times_at_two_percent(self):
        for version in ('dofus3', 'beta'):
            for spell in self._portal_spells(version):
                with self.subTest(version=version, spell=spell.name):
                    self.assertEqual(10, spell.stacks)
                    self.assertEqual({'final': 2, 'finalheals': 2},
                                     spell.buff_deltas(1))
                    self.assertEqual({'final': 20, 'finalheals': 20},
                                     spell.buff_deltas(10))
                    self.assertEqual(spell.buff_deltas(10),
                                     spell.buff_deltas(11))

    def test_ten_portals_are_worth_a_fifth_more_damage(self):
        from chardata.spells_view import _best_combo
        char = _ComboChar('Eliotrope')
        solution = _ComboSolution(_combo_stats())
        plain = _best_combo(char, solution, 'dofus3', {'Portal': 'n0'})
        full = _best_combo(char, solution, 'dofus3', {'Portal': 'n10'})
        self.assertAlmostEqual(plain['total'] * 1.2, full['total'], delta=1)

    def test_dofus2_has_no_portal_to_stack(self):
        # Portal deals no damage in 2.73: only the reference names it
        import json
        import os
        from chardata.spell_buffs import get_damage_spells_for_version
        spells = {spell.name: spell for spell
                  in get_damage_spells_for_version('dofus2')['Eliotrope']}
        self.assertNotIn('Portal', spells)
        path = os.path.join(os.path.dirname(__file__), 'spell_reference',
                            'dofus2.json')
        with open(path, encoding='utf-8') as handle:
            reference = json.load(handle)
        self.assertIn('Portal', [(entry.get('name') or {}).get('en')
                                 for entry in reference['Eliotrope']])

    def test_the_text_only_speaks_where_the_levels_are_silent(self):
        # A declared max_stack beats the text; 1 means no stacking
        module = itemscraper_module('generate_damage_spells')
        text = {'description_fr': 'cumulable 4 fois',
                'description_en': 'stackable 4 times'}
        silent = dict(text, levels=[{'max_stack': -1}, {'max_stack': -1}])
        declared = dict(text, levels=[{'max_stack': 1}, {'max_stack': 1}])
        counted = dict(text, levels=[{'max_stack': 6}, {'max_stack': -1}])
        disagreeing = {'description_fr': 'cumulable 4 fois',
                       'description_en': 'stackable 7 times',
                       'levels': [{'max_stack': -1}]}
        self.assertEqual(4, module._extract_stack_limit(silent))
        self.assertIsNone(module._extract_stack_limit(declared))
        self.assertEqual(6, module._extract_stack_limit(counted))
        self.assertIsNone(module._extract_stack_limit(disagreeing))
        self.assertIsNone(module._extract_stack_limit({'levels': []}))


class StateGatedBlocksTests(SimpleTestCase):
    """A state-gated spell writes one block per case, labelled by state."""

    def test_a_block_carries_the_state_its_mask_names(self):
        module = itemscraper_module('generate_damage_spells')
        spell = {'ankama_id': 1, 'name_en': 'Probe',
                 'level_requirements': [1],
                 'damage_templates': {'normal': [
                     {'element': 'FIRE', 'ranges': ['10-12'],
                      'state_group': 'E183'},
                     {'element': 'FIRE', 'ranges': ['5-6'],
                      'state_group': '*e183,E92'}]}}
        entry = module.convert_spell(spell)
        self.assertEqual([('State 183', [0]), ('State !183,92', [1])],
                         entry.aggregates)

    def test_two_states_printing_the_same_numbers_stay_one_block(self):
        module = itemscraper_module('generate_damage_spells')
        row = {'element': 'FIRE', 'ranges': ['10-12']}
        spell = {'ankama_id': 1, 'name_en': 'Probe',
                 'level_requirements': [1],
                 'damage_templates': {'normal': [
                     dict(row, state_group='E183'),
                     dict(row, state_group='e183')]}}
        entry = module.convert_spell(spell)
        self.assertEqual([('', [0])], entry.aggregates)


class ComboReadsWhatThePageSendsTests(SimpleTestCase):
    """The combo matches on the data's spell name, not the translated one."""

    def test_a_spell_digest_carries_the_name_the_data_uses(self):
        from django.utils import translation
        from chardata.spells_view import _create_spell_web_digest
        from chardata.spell_buffs import get_damage_spells_for_version
        spells = get_damage_spells_for_version('dofus3').get('Iop', [])
        power = next(spell for spell in spells if spell.name == 'Power')
        with translation.override('fr'):
            digest = _create_spell_web_digest(power, 'dofus3')
        self.assertEqual('Power', digest['canonical'])
        self.assertNotEqual(digest['canonical'], digest['name'],
                            'pick a spell whose French name differs')

    def test_every_digest_carries_one(self):
        from chardata.spells_view import _create_spell_web_digest
        from chardata.spell_buffs import get_damage_spells_for_version
        for version in ('dofus3', 'retro', 'touch'):
            spells = get_damage_spells_for_version(version)
            bucket = next((v for v in spells.values() if v), [])
            for spell in bucket[:20]:
                with self.subTest(version=version, spell=spell.name):
                    digest = _create_spell_web_digest(spell, version)
                    self.assertEqual(spell.name, digest['canonical'])

    def test_a_buff_only_counts_under_the_name_the_data_uses(self):
        from chardata.spell_combo import buffs_in_force
        canonical = buffs_in_force('Iop', 200, 'dofus3', {'Power': 'c1'})
        translated = buffs_in_force('Iop', 200, 'dofus3', {'Puissance': 'c1'})
        self.assertTrue(canonical, 'the canonical name found no buff')
        self.assertEqual({}, translated,
                         'a translated key must not silently half-work')

    def test_the_rank_the_reader_picks_reaches_the_search(self):
        from chardata.spell_combo import buffs_in_force, castable_spells
        top = buffs_in_force('Iop', 200, 'dofus3', {'Power': 'c1'})
        low = buffs_in_force('Iop', 200, 'dofus3', {'Power': 'c1'},
                             {'Power': 0})
        self.assertTrue(top and low)
        self.assertNotEqual(top, low, 'the rank did not reach the buff')
        for stat, value in low.items():
            self.assertLessEqual(value, top[stat])

        highest = {c.name: c for c in castable_spells('Iop', 200, 'dofus3')}
        lowered = {c.name: c for c in castable_spells(
            'Iop', 200, 'dofus3', levels={'Pressure': 0})}
        self.assertIn('Pressure', highest)
        self.assertNotEqual(highest['Pressure'].effects,
                            lowered['Pressure'].effects)

    def test_a_rank_the_spell_does_not_have_is_ignored(self):
        from chardata.spell_combo import castable_spells
        plain = {c.name: c.effects for c in castable_spells('Iop', 200, 'dofus3')}
        for silly in ({'Pressure': 99}, {'Pressure': -3},
                      {'Pressure': 'top'}, {'Pressure': None}):
            with self.subTest(levels=silly):
                got = {c.name: c.effects for c
                       in castable_spells('Iop', 200, 'dofus3', levels=silly)}
                self.assertEqual(plain['Pressure'], got['Pressure'])


class WakfuStatCatalogueTests(SimpleTestCase):
    """Wakfu gear stats, checked against the decoded build."""

    DUMP = os.path.join(os.path.dirname(os.path.dirname(os.path.dirname(
        os.path.abspath(__file__)))), 'itemscraper', 'transformed_wakfu.json')

    def _stats_in_the_data(self):
        if not os.path.exists(self.DUMP):
            self.skipTest('no Wakfu build decoded; run '
                          'itemscraper/get_items_wakfu.py')
        with io.open(self.DUMP, encoding='utf-8') as handle:
            dump = json.load(handle)
        found = set()
        for item in dump['equipment']:
            for line in item['lines']:
                if line.get('stat'):
                    found.add(line['stat'])
        return found, dump['version']

    def test_every_stat_the_data_carries_is_in_the_catalogue(self):
        from fashionistapulp.wakfu_stats import WAKFU_STATS
        found, version = self._stats_in_the_data()
        self.assertTrue(found, 'the decoded build carries no stats at all')
        self.assertEqual(set(), found - set(WAKFU_STATS),
                         'build %s carries stats the catalogue does not name'
                         % version)

    def test_the_catalogue_claims_nothing_the_game_does_not_sell(self):
        from fashionistapulp.wakfu_stats import (NOT_ON_GEAR_TODAY,
                                                 WAKFU_STATS)
        found, _version = self._stats_in_the_data()
        self.assertEqual(set(NOT_ON_GEAR_TODAY), set(WAKFU_STATS) - found)

    def test_the_spread_assumption_is_declared_not_hidden(self):
        # "232 Mastery with 2 elements" never says which two
        from fashionistapulp.wakfu_stats import (MASTERY, RESISTANCE,
                                                 SPREAD_LANDS_WHERE_THE_BUILD_WANTS,
                                                 SPREAD_MASTERY,
                                                 SPREAD_RESISTANCE,
                                                 WAKFU_STATS)
        self.assertTrue(SPREAD_LANDS_WHERE_THE_BUILD_WANTS)
        self.assertEqual(MASTERY, WAKFU_STATS[SPREAD_MASTERY])
        self.assertEqual(RESISTANCE, WAKFU_STATS[SPREAD_RESISTANCE])

    def test_wakfu_has_none_of_dofus_characteristics(self):
        from fashionistapulp.wakfu_stats import WAKFU_STATS
        for dofus_only in ('str', 'int', 'cha', 'agi', 'pow', 'vit', 'pshdam',
                           'perspedam', 'cridam'):
            with self.subTest(stat=dofus_only):
                self.assertNotIn(dofus_only, WAKFU_STATS)
                self.assertNotIn(dofus_only.upper(), WAKFU_STATS)


class WakfuSlotRuleTests(SimpleTestCase):
    """What Wakfu lets a character wear at once, checked against the build."""

    DUMP = WakfuStatCatalogueTests.DUMP

    def _dump(self):
        if not os.path.exists(self.DUMP):
            self.skipTest('no Wakfu build decoded; run '
                          'itemscraper/get_items_wakfu.py')
        with io.open(self.DUMP, encoding='utf-8') as handle:
            return json.load(handle)

    def test_a_two_handed_weapon_blocks_the_off_hand(self):
        from fashionistapulp.wakfu_slots import BLOCKED_BY_TWO_HANDED
        dump = self._dump()
        blocking = [item for item in dump['equipment'] if item['two_handed']]
        self.assertGreater(len(blocking), 100, 'no two-handed weapon found')
        for item in blocking:
            with self.subTest(item=item['id']):
                self.assertIn(BLOCKED_BY_TWO_HANDED, item['disables'])
                self.assertEqual(['FIRST_WEAPON'], item['positions'])
        # Nothing else blocks a slot
        for item in dump['equipment']:
            if item['disables']:
                self.assertTrue(item['two_handed'], item['id'])

    def test_the_two_exclusive_groups_are_separate(self):
        # Two separate "only one equipped at a time" properties, not a rarity
        from fashionistapulp.wakfu_slots import EXCLUSIVE_PROPERTIES
        dump = self._dump()
        groups = {}
        for item in dump['equipment']:
            if item['exclusive']:
                groups.setdefault(item['exclusive'], []).append(item)
        self.assertEqual(sorted(EXCLUSIVE_PROPERTIES.values()),
                         sorted(groups))
        for group, items in groups.items():
            with self.subTest(group=group):
                self.assertGreater(len(items), 50)
                # Spread across slots: not a "one ring" rule
                self.assertGreater(len({item['positions'][0]
                                        for item in items if item['positions']}),
                                   5)
        exclusive_rarities = {item['rarity'] for item in dump['equipment']
                              if item['exclusive']}
        shared_rarities = {item['rarity'] for item in dump['equipment']
                           if not item['exclusive']}
        self.assertTrue(exclusive_rarities & shared_rarities,
                        'every exclusive item has a rarity nothing else has, '
                        'so the rule could just be read off the rarity')

    def test_no_wakfu_item_can_be_worn_twice(self):
        # No Ankama source says whether Wakfu allows two copies: assume one
        from fashionistapulp.fashionista_config import get_items_db_path
        from fashionistapulp.game_versions import (GAME_VERSIONS,
                                                   get_game_version)
        from fashionistapulp.structure import get_structure
        self.assertFalse(get_game_version('wakfu').rings_can_double)
        self.assertFalse(get_game_version('retro').rings_can_double)
        self.assertTrue(get_game_version('dofus3').rings_can_double)
        # Every version must set it
        for key, version in GAME_VERSIONS.items():
            with self.subTest(version=key):
                self.assertIsInstance(version.rings_can_double, bool)
        if not os.path.exists(get_items_db_path('wakfu')):
            self.skipTest('no Wakfu database built')
        self.assertIn('Ring', set(get_structure('wakfu').types_dict.values()))

    def test_every_gear_slot_the_data_uses_is_declared(self):
        from fashionistapulp.wakfu_slots import NOT_GEAR, SLOTS
        dump = self._dump()
        seen = set()
        for item in dump['equipment']:
            seen.update(item['positions'])
        self.assertEqual(set(), seen - set(SLOTS) - set(NOT_GEAR),
                         'the build uses a slot nothing declares')


class WakfuItemDatabaseTests(SimpleTestCase):
    """Wakfu-only tables on a hand-made db, the real data is not committed."""

    ITEM = 7

    def _schema_of(self, version):
        import sqlite3
        from fashionistapulp.fashionista_config import get_items_db_path
        conn = sqlite3.connect(get_items_db_path(version))
        try:
            return [row[0] for row in conn.execute(
                'SELECT sql FROM sqlite_master'
                " WHERE sql IS NOT NULL AND name NOT LIKE 'sqlite_%'")]
        finally:
            conn.close()

    def _wakfu_db(self, directory, element_lines=((1, 232, 2),)):
        import sqlite3
        from fashionistapulp.wakfu_db import create_tables
        path = os.path.join(directory, 'items_wakfu.db')
        conn = sqlite3.connect(path)
        for statement in self._schema_of('dofus3'):
            conn.execute(statement)
        create_tables(conn)
        conn.execute("INSERT INTO item_types (id, name) VALUES (1, 'HEAD')")
        conn.execute('INSERT INTO stats (id, name, key) VALUES'
                     " (1, 'Mastery', 'DMG_IN_PERCENT'), (2, 'Health', 'HP')")
        conn.execute('INSERT INTO items (id, name, level, type, item_set,'
                     ' ankama_id, ankama_type, removed, dofustouch) VALUES'
                     " (?, 'Test Helmet', 65, 1, NULL, ?, 'equipment', 0, 0)",
                     (self.ITEM, self.ITEM))
        conn.execute('INSERT INTO stats_of_item (item, stat, value)'
                     ' VALUES (?, 1, 232), (?, 2, 300)',
                     (self.ITEM, self.ITEM))
        conn.execute('INSERT INTO item_rarity (item, rarity) VALUES (?, 4)',
                     (self.ITEM,))
        for line, (stat, value, elements) in enumerate(element_lines):
            conn.execute('INSERT INTO stat_element_count'
                         ' (item, line, stat, value, elements)'
                         ' VALUES (?, ?, ?, ?, ?)',
                         (self.ITEM, line, stat, value, elements))
        conn.commit()
        conn.close()
        return path

    def _structure_over(self, path):
        from unittest import mock
        from fashionistapulp import structure as structure_module
        with mock.patch.object(structure_module, 'get_items_db_path',
                               return_value=path):
            return structure_module.Structure('wakfu')

    def test_the_two_tables_are_read_off_a_wakfu_database(self):
        with tempfile.TemporaryDirectory() as directory:
            structure = self._structure_over(self._wakfu_db(directory))
        item = structure.get_item_by_id(self.ITEM)
        self.assertEqual(4, item.rarity)
        self.assertEqual([(1, 232, 2)], item.element_spread)

    def test_more_than_one_spread_line_keeps_them_apart(self):
        # Two mastery lines: same stat, different element counts
        lines = ((1, 232, 2), (1, 90, 1))
        with tempfile.TemporaryDirectory() as directory:
            path = self._wakfu_db(directory, element_lines=lines)
            import sqlite3
            conn = sqlite3.connect(path)
            conn.execute('INSERT INTO stats_of_item (item, stat, value)'
                         ' VALUES (?, 1, 90)', (self.ITEM,))
            conn.commit()
            conn.close()
            structure = self._structure_over(path)
        item = structure.get_item_by_id(self.ITEM)
        self.assertEqual([(1, 232, 2), (1, 90, 1)], item.element_spread)

    def test_an_element_line_the_item_does_not_carry_is_refused(self):
        # The element line names a value no stats_of_item row carries
        with tempfile.TemporaryDirectory() as directory:
            path = self._wakfu_db(directory, element_lines=((1, 999, 2),))
            with self.assertRaises(ValueError) as caught:
                self._structure_over(path)
        self.assertIn('stat_element_count', str(caught.exception))

    def test_a_dofus_database_has_neither_table_and_still_reads(self):
        from fashionistapulp.structure import get_structure
        from fashionistapulp.wakfu_db import (ITEM_RARITY_TABLE,
                                              STAT_ELEMENT_COUNT_TABLE)
        import sqlite3
        from fashionistapulp.fashionista_config import get_items_db_path
        for version in ('dofus3', 'retro'):
            with self.subTest(version=version):
                conn = sqlite3.connect(get_items_db_path(version))
                try:
                    present = {row[0] for row in conn.execute(
                        "SELECT name FROM sqlite_master WHERE type = 'table'")}
                finally:
                    conn.close()
                self.assertNotIn(ITEM_RARITY_TABLE, present)
                self.assertNotIn(STAT_ELEMENT_COUNT_TABLE, present)
                item = get_structure(version).get_available_items_list()[0]
                self.assertIsNone(item.rarity)
                self.assertEqual([], item.element_spread)

    def test_no_dofus_ring_is_invented_for_a_game_that_has_no_rings(self):
        # The synthetic Gelano is Dofus only
        with tempfile.TemporaryDirectory() as directory:
            structure = self._structure_over(self._wakfu_db(directory))
        names = {item.name for item in structure.get_items_list()}
        names.update(item.name for item in structure.get_items_list(True))
        self.assertEqual({'Test Helmet'}, names)
        self.assertEqual([], structure.get_sets_list(True))
        self.assertEqual([], structure.get_sets_list(False))

    def test_both_db_scripts_know_every_version_the_registry_knows(self):
        from fashionistapulp.fashionista_config import get_fashionista_path
        from fashionistapulp.game_versions import version_keys
        root = get_fashionista_path()
        env = dict(os.environ,
                   PYTHONPATH=os.path.join(root, 'fashionistapulp'))
        for script in ('dump_item_db.py', 'load_item_db.py'):
            with self.subTest(script=script):
                done = subprocess.run(
                    [sys.executable, os.path.join(root, script),
                     '--game-version', 'not-a-game'],
                    env=env, capture_output=True, text=True)
                self.assertNotEqual(0, done.returncode)
                said = done.stderr + done.stdout
                for key in version_keys(include_experimental=True):
                    # argparse quotes the choices up to Python 3.12 only
                    self.assertRegex(said, r'\b%s\b' % re.escape(key))

    def test_the_two_tables_survive_a_dump_and_a_reload(self):
        # Reloaded the way load_item_db.py does, from the dump's own SQL
        import importlib
        import sqlite3
        from fashionistapulp.wakfu_db import (ITEM_RARITY_TABLE,
                                              STAT_ELEMENT_COUNT_TABLE)
        dumper = importlib.import_module('dump_item_db')
        loader = importlib.import_module('load_item_db')
        with tempfile.TemporaryDirectory() as directory:
            source = self._wakfu_db(directory)
            dump = os.path.join(directory, 'wakfu.dump')
            dumper._write_dump(source, dump)
            with io.open(dump, encoding='utf-8') as handle:
                sql = loader._sanitize_dump_sql(handle.read())
            for table in (ITEM_RARITY_TABLE, STAT_ELEMENT_COUNT_TABLE):
                self.assertIn(table, sql, '%s is not in the dump' % table)
            rebuilt = os.path.join(directory, 'rebuilt.db')
            connection = sqlite3.connect(rebuilt)
            connection.executescript(sql)
            connection.commit()
            connection.close()
            structure = self._structure_over(rebuilt)
        item = structure.get_item_by_id(self.ITEM)
        self.assertEqual(4, item.rarity)
        self.assertEqual([(1, 232, 2)], item.element_spread)

    def test_the_wakfu_database_and_its_dump_are_never_committed(self):
        # Ankama's licence forbids passing the Wakfu data on
        from fashionistapulp.fashionista_config import get_fashionista_path
        from fashionistapulp.game_versions import GAME_VERSIONS
        root = get_fashionista_path()
        if not os.path.isdir(os.path.join(root, '.git')):
            self.skipTest('not a git checkout')
        wakfu = GAME_VERSIONS['wakfu']
        for name in (wakfu.db_file, wakfu.dump_file):
            path = os.path.join('fashionistapulp', 'fashionistapulp', name)
            with self.subTest(path=path):
                ignored = subprocess.run(
                    ['git', 'check-ignore', '-q', path],
                    cwd=root, capture_output=True)
                self.assertEqual(0, ignored.returncode,
                                 '%s is not ignored' % path)
                tracked = subprocess.run(
                    ['git', 'ls-files', '--error-unmatch', path],
                    cwd=root, capture_output=True)
                self.assertNotEqual(0, tracked.returncode,
                                    '%s is tracked' % path)


class LevelRangeFollowsTheGameTests(SimpleTestCase):
    """Level buckets come from the data: Dofus 1 to 200, Wakfu from 0."""

    def test_no_dofus_version_moved(self):
        from fashionistapulp.structure import get_structure
        for version in ('dofus3', 'beta', 'dofus2', 'touch', 'retro'):
            with self.subTest(version=version):
                structure = get_structure(version)
                self.assertEqual(1, structure._level_floor)
                self.assertEqual(200, structure._level_ceiling)

    def test_every_item_lands_in_a_bucket(self):
        from fashionistapulp.structure import get_structure
        for version in ('dofus3', 'retro'):
            structure = get_structure(version)
            items = list(structure.get_concatenated_items_lists())
            self.assertTrue(items)
            for item in items:
                if item.level not in structure.types:
                    self.fail('%s item %s is level %s, outside %s..%s'
                              % (version, item.name, item.level,
                                 structure._level_floor,
                                 structure._level_ceiling))

    def test_wakfu_brings_its_own_levels_stats_and_slots(self):
        import os
        from fashionistapulp.fashionista_config import get_items_db_path
        if not os.path.exists(get_items_db_path('wakfu')):
            self.skipTest('no Wakfu database built; run '
                          'itemscraper/get_items_wakfu.py then '
                          'itemscraper/build_wakfu_db.py')
        from fashionistapulp.structure import get_structure
        from fashionistapulp.wakfu_stats import WAKFU_STATS
        wakfu = get_structure('wakfu')
        self.assertEqual(0, wakfu._level_floor)
        self.assertGreater(wakfu._level_ceiling, 200)
        items = list(wakfu.get_concatenated_items_lists())
        self.assertGreater(len(items), 5000)
        for item in items:
            self.assertIn(item.level, wakfu.types)
        # No stat key shared with Dofus
        keys = {stat.key for stat in wakfu.get_stats_list()}
        self.assertEqual({key.lower() for key in WAKFU_STATS}, keys)
        for dofus_only in ('str', 'int', 'agi', 'pow', 'vit'):
            self.assertNotIn(dofus_only, keys)

    def test_a_spread_line_keeps_its_element_count_all_the_way(self):
        import os
        from fashionistapulp.fashionista_config import get_items_db_path
        if not os.path.exists(get_items_db_path('wakfu')):
            self.skipTest('no Wakfu database built')
        from fashionistapulp.structure import get_structure
        wakfu = get_structure('wakfu')
        spread = [item for item in wakfu.get_concatenated_items_lists()
                  if getattr(item, 'element_spread', None)]
        self.assertGreater(len(spread), 1000)
        for item in spread:
            for stat_id, value, elements in item.element_spread:
                with self.subTest(item=item.name):
                    self.assertIn(elements, (1, 2, 3))
                    self.assertIn((stat_id, value), item.stats)


class WakfuSetsComeFromTheItemsTests(SimpleTestCase):
    """No Wakfu set file or set bonus; names come from the encyclopedia."""

    def _wakfu(self):
        import os
        from fashionistapulp.fashionista_config import get_items_db_path
        if not os.path.exists(get_items_db_path('wakfu')):
            self.skipTest('no Wakfu database built; run get_items_wakfu.py, '
                          'get_sets_wakfu.py then build_wakfu_db.py')
        from fashionistapulp.structure import get_structure
        return get_structure('wakfu')

    def test_a_set_is_named_in_every_language_the_site_serves(self):
        wakfu = self._wakfu()
        self.assertGreater(len(wakfu.sets_dict), 100)
        for item_set in wakfu.sets_dict.values():
            with self.subTest(item_set=item_set.id):
                names = item_set.localized_names
                for language in ('en', 'fr', 'es', 'pt', 'de'):
                    self.assertTrue(names.get(language), language)
                # Wakfu has no German: English stands in
                self.assertEqual(names['en'], names['de'])

    def test_no_item_points_at_a_set_that_is_not_there(self):
        # Items of a set with no page lose the link, not their stats
        wakfu = self._wakfu()
        known = set(wakfu.sets_dict)
        orphans = sorted({(item.name, item.set)
                          for item in wakfu.get_concatenated_items_lists()
                          if getattr(item, 'set', None)
                          and item.set not in known})
        self.assertEqual([], orphans[:5],
                         '%d items point at a set that is not there'
                         % len(orphans))

    def test_the_gobball_total_is_computed_not_copied(self):
        wakfu = self._wakfu()
        gobball = wakfu.sets_dict.get(41)
        self.assertIsNotNone(gobball, 'set 41 is missing')
        self.assertEqual('Gobball Set', gobball.localized_names['en'])
        hp = [stat.id for stat in wakfu.get_stats_list()
              if stat.key == 'hp'][0]
        members = [item for item in wakfu.get_concatenated_items_lists()
                   if getattr(item, 'set', None) == 41]
        self.assertEqual(8, len(members))
        total = sum(value for member in members
                    for stat_id, value in member.stats if stat_id == hp)
        self.assertEqual(65, total)
        # Ankama's set page says 63: the belt's page and game data disagree
        self.assertNotEqual(63, total)

    def test_no_set_grants_anything_for_wearing_it(self):
        # Wakfu sets have no bonus, the page total only sums the pieces
        wakfu = self._wakfu()
        wearing = sorted(item_set.id for item_set in wakfu.sets_dict.values()
                         if getattr(item_set, 'bonus', None))
        self.assertEqual([], wearing[:5],
                         '%d Wakfu sets claim a bonus for being worn'
                         % len(wearing))


class WakfuTypesAreAnkamasOwnTests(SimpleTestCase):
    """Ankama's Wakfu types; two item_type_position rows mean two slots."""

    def _wakfu(self):
        from fashionistapulp.fashionista_config import get_items_db_path
        from fashionistapulp.structure import get_structure
        if not os.path.exists(get_items_db_path('wakfu')):
            self.skipTest('no Wakfu database built; run '
                          'itemscraper/get_items_wakfu.py then '
                          'itemscraper/build_wakfu_db.py')
        return get_structure('wakfu')

    def _positions(self):
        import sqlite3
        from fashionistapulp.fashionista_config import get_items_db_path
        conn = sqlite3.connect('file:%s?mode=ro' % get_items_db_path('wakfu'),
                               uri=True)
        try:
            rows = conn.execute('SELECT item_type, position'
                                ' FROM item_type_position').fetchall()
        finally:
            conn.close()
        places = {}
        for type_id, position in rows:
            places.setdefault(type_id, set()).add(position)
        return places

    def test_ankamas_plural_template_never_reaches_a_reader(self):
        # Ankama's plural template: the client picks the ending
        from fashionistapulp.wakfu_db import singular
        self.assertEqual('Anneau', singular('Anneau{[~1]?x:}'))
        self.assertEqual('Amulet', singular('Amulet{[~1]?s:}'))
        self.assertEqual('Sword (One-handed)',
                         singular('Sword{[~1]?s:} (One-handed)'))
        # Portuguese changes the whole word
        self.assertEqual('Anel', singular('An{[~1]?éis:el}'))
        self.assertEqual('Bottes', singular('Bottes'))
        # An unknown template is left as is
        exotic = '{[99>3]?:{[0<3]?:{[~3]?([#3]%):}'
        self.assertEqual(exotic, singular(exotic))

    def test_every_type_is_named_and_placed(self):
        wakfu = self._wakfu()
        from fashionistapulp.wakfu_slots import SLOTS
        places = self._positions()
        self.assertGreater(len(wakfu.types_dict), 20)
        for type_id, name in wakfu.types_dict.items():
            with self.subTest(type=name):
                self.assertNotIn('{', name)
                self.assertTrue(name.strip())
                self.assertIn(type_id, places)
                self.assertEqual(set(), places[type_id] - set(SLOTS))

    def test_a_ring_fills_two_slots_and_nothing_else_does(self):
        wakfu = self._wakfu()
        places = self._positions()
        two_slots = {wakfu.types_dict[type_id]
                     for type_id, positions in places.items()
                     if len(positions) > 1}
        self.assertEqual({'Ring'}, two_slots)
        ring = wakfu.get_type_id_by_name('Ring')
        from fashionistapulp.wakfu_slots import BOTH_HANDS
        self.assertEqual(set(BOTH_HANDS), places[ring])

    def test_every_type_is_named_in_the_languages_wakfu_is_played_in(self):
        # Wakfu has no German: de carries the English name
        import sqlite3
        from fashionistapulp.fashionista_config import get_items_db_path
        if not os.path.exists(get_items_db_path('wakfu')):
            self.skipTest('no Wakfu database built')
        conn = sqlite3.connect('file:%s?mode=ro' % get_items_db_path('wakfu'),
                               uri=True)
        try:
            rows = conn.execute('SELECT item_type, language, name'
                                ' FROM item_type_names').fetchall()
            types = [row[0] for row in
                     conn.execute('SELECT id FROM item_types').fetchall()]
        finally:
            conn.close()
        names = {}
        for type_id, language, name in rows:
            names.setdefault(type_id, {})[language] = name
        for type_id in types:
            with self.subTest(type=type_id):
                said = names.get(type_id, {})
                self.assertEqual({'en', 'fr', 'es', 'pt', 'de'}, set(said))
                for language, name in said.items():
                    self.assertNotIn('{', name, language)
                    self.assertTrue(name.strip(), language)
                self.assertEqual(said['en'], said['de'])
        # Real translations, not English copied five times
        translated = sum(1 for said in names.values() if said['fr'] != said['en'])
        self.assertGreater(translated, len(types) * 3 // 4)

    def test_no_item_is_filed_under_a_type_that_is_not_there(self):
        wakfu = self._wakfu()
        known = set(wakfu.types_dict)
        orphans = sorted({(item.name, item.type)
                          for item in wakfu.get_concatenated_items_lists()
                          if item.type not in known})
        self.assertEqual([], orphans[:5],
                         '%d items point at a type that is not there'
                         % len(orphans))


class ArtworkNeverCrossesFromAnotherGameTests(SimpleTestCase):
    """A game that is not Dofus never falls back to a Dofus icon."""

    def test_a_wakfu_item_falls_back_to_the_placeholder(self):
        from chardata.image_store import RETRO_PLACEHOLDER, get_image_url
        found = get_image_url('Hat', 'Adventurer Hat', 'wakfu')
        self.assertEqual(RETRO_PLACEHOLDER, found)
        self.assertNotIn('60x60', found)

    def test_a_wakfu_item_uses_its_own_drawing_when_there_is_one(self):
        from unittest.mock import patch
        from chardata.image_store import get_image_url
        with patch('chardata.image_store._static_exists', return_value=True):
            found = get_image_url('Ring', 'Adventurer Hat', 'wakfu',
                                  picture=1032022)
        self.assertEqual('chardata/items/wakfu/64/1032022.webp', found)

    def test_a_missing_drawing_is_not_a_dofus_one(self):
        from unittest.mock import patch
        from chardata.image_store import RETRO_PLACEHOLDER, get_image_url
        with patch('chardata.image_store._static_exists', return_value=False):
            found = get_image_url('Ring', 'Adventurer Hat', 'wakfu',
                                  picture=999999999)
        self.assertEqual(RETRO_PLACEHOLDER, found)

    def test_the_dofus_versions_are_untouched(self):
        from chardata.image_store import get_image_url
        # Beta and Dofus 2 do use Dofus 3 art
        for version in ('dofus3', 'beta', 'dofus2'):
            with self.subTest(version=version):
                found = get_image_url('Hat', 'Adventurer Hat', version)
                self.assertIn('60x60', found)
        # A picture id changes nothing for Dofus
        self.assertEqual(get_image_url('Hat', 'Adventurer Hat', 'dofus3'),
                         get_image_url('Hat', 'Adventurer Hat', 'dofus3',
                                       picture=1032022))

    def test_the_names_really_do_collide(self):
        import sqlite3
        from fashionistapulp.fashionista_config import get_items_db_path
        if not os.path.exists(get_items_db_path('wakfu')):
            self.skipTest('no Wakfu database built')
        shared = None
        names = {}
        for version in ('dofus3', 'wakfu'):
            conn = sqlite3.connect('file:%s?mode=ro' % get_items_db_path(version),
                                   uri=True)
            try:
                names[version] = {row[0] for row in
                                  conn.execute('SELECT name FROM items')}
            finally:
                conn.close()
        shared = names['dofus3'] & names['wakfu']
        self.assertIn('Adventurer Hat', shared)
        self.assertGreater(len(shared), 100)


class TheWakfuPipelineSaysWhatItOwnsTests(SimpleTestCase):
    """Wakfu orchestrator: documented owners are real, the build runs first."""

    ROOT = os.path.dirname(os.path.dirname(os.path.dirname(
        os.path.abspath(__file__))))
    ORCHESTRATOR = os.path.join(ROOT, 'update_data_wakfu.py')
    BUILDER = os.path.join(ROOT, 'itemscraper', 'build_wakfu_db.py')

    def _orchestrator(self):
        import importlib.util
        spec = importlib.util.spec_from_file_location(
            'update_data_wakfu_under_test', self.ORCHESTRATOR)
        module = importlib.util.module_from_spec(spec)
        spec.loader.exec_module(module)
        return module

    def test_the_documented_owner_list_is_the_real_one(self):
        import re
        doc = io.open(self.ORCHESTRATOR, encoding='utf-8').read()
        blocks = re.findall(
            r'(\w+\.py) owns, and rewrites on every run:\n(.*?)\n\n',
            doc, re.S)
        self.assertTrue(blocks, 'the orchestrator names no owner at all')
        for script, block in blocks:
            with self.subTest(script=script):
                documented = set(re.findall(r'[a-z_]{4,}', block))
                source = io.open(os.path.join(self.ROOT, 'itemscraper', script),
                                 encoding='utf-8').read()
                written = set(re.findall(r'INSERT INTO ([a-z_]+)', source))
                self.assertTrue(written, '%s writes nothing at all?' % script)
                self.assertEqual(
                    written, documented,
                    '%s: the orchestrator names %s but the script writes %s'
                    % (script, sorted(documented - written),
                       sorted(written - documented)))
        # Every writer named is also a step that runs
        for script, _ in blocks:
            self.assertIn(script, doc.split('Steps:')[1][:600], script)

    def test_the_build_step_comes_before_everything_that_writes(self):
        # The build deletes the db: a writer before it loses its rows
        source = io.open(self.ORCHESTRATOR, encoding='utf-8').read()
        build_at = source.index("step('items/build-db'")
        dump_at = source.index("step('items/dump'")
        self.assertLess(build_at, dump_at)
        for earlier in ("step('data/mirror'", "step('data/sets'"):
            self.assertLess(source.index(earlier), build_at, earlier)

    def test_a_zero_count_is_not_a_warning(self):
        said = self._orchestrator()._is_notice
        self.assertFalse(said('stat vocabulary: 71 actions, 0 unresolved'))
        self.assertFalse(said('0 missing'))
        self.assertFalse(said('no error'))
        self.assertTrue(said('stat vocabulary: 71 actions, 3 unresolved'))
        self.assertTrue(said('set with no page   15'))
        self.assertTrue(said('2 errors and 0 missing'))
        # The zero must be a word of its own: "casino" is not "no"
        self.assertTrue(said('casino missing'))


class WakfuCraftingReadsTheWayTheSiteJoinsItTests(SimpleTestCase):
    """Wakfu crafting tables, checked through the joins the pages run."""

    def _conn(self):
        import sqlite3
        from fashionistapulp.fashionista_config import get_items_db_path
        path = get_items_db_path('wakfu')
        if not os.path.exists(path):
            self.skipTest('no Wakfu database built; run update_data_wakfu.py')
        conn = sqlite3.connect('file:%s?mode=ro' % path, uri=True)
        if not conn.execute('SELECT COUNT(*) FROM item_recipes').fetchone()[0]:
            conn.close()
            self.skipTest('no Wakfu recipes imported yet')
        return conn

    def test_every_ingredient_line_resolves_to_a_name(self):
        # Plain equality on both columns: the subtype is never normalised
        conn = self._conn()
        try:
            orphans = conn.execute(
                'SELECT r.item, r.position, r.ingredient_ankama_id,'
                ' r.ingredient_subtype FROM item_recipes r'
                ' WHERE NOT EXISTS (SELECT 1 FROM item_recipe_ingredient_names n'
                ' WHERE n.ingredient_ankama_id = r.ingredient_ankama_id'
                ' AND n.ingredient_subtype = r.ingredient_subtype'
                ' AND n.language = "en") LIMIT 5').fetchall()
        finally:
            conn.close()
        self.assertEqual([], orphans)

    def test_positions_are_dense_and_start_at_zero(self):
        # Renumbered: Ankama's ingredientOrder has gaps and repeats
        conn = self._conn()
        try:
            broken = conn.execute(
                'SELECT item, MIN(position), MAX(position), COUNT(*)'
                ' FROM item_recipes GROUP BY item'
                ' HAVING MIN(position) <> 0 OR MAX(position) <> COUNT(*) - 1'
                ' LIMIT 5').fetchall()
        finally:
            conn.close()
        self.assertEqual([], broken)

    def test_every_craftable_item_names_a_job_the_site_can_show(self):
        conn = self._conn()
        try:
            # Job 1 is Ankama's "Base" placeholder, hidden by the craft line
            self.assertEqual(
                0, conn.execute('SELECT COUNT(*) FROM item_craft_jobs'
                                ' WHERE job_ankama_id = 1').fetchone()[0])
            unnamed = conn.execute(
                'SELECT DISTINCT j.job_ankama_id FROM item_craft_jobs j'
                ' WHERE NOT EXISTS (SELECT 1 FROM job_names n'
                ' WHERE n.job_ankama_id = j.job_ankama_id'
                ' AND n.language = "fr")').fetchall()
            self.assertEqual([], unnamed)
            # Every item with a recipe names its job
            self.assertEqual(
                [], conn.execute(
                    'SELECT DISTINCT r.item FROM item_recipes r WHERE NOT EXISTS'
                    ' (SELECT 1 FROM item_craft_jobs j WHERE j.item = r.item)'
                    ' LIMIT 5').fetchall())
        finally:
            conn.close()

    def test_german_carries_the_english_text_like_every_wakfu_table(self):
        # Wakfu has no German: de carries the English, the page has no fallback
        conn = self._conn()
        try:
            for table, key in (('item_recipe_ingredient_names',
                                'ingredient_ankama_id'),
                               ('job_names', 'job_ankama_id')):
                with self.subTest(table=table):
                    said = conn.execute(
                        'SELECT COUNT(*) FROM %s a JOIN %s b ON a.%s = b.%s'
                        ' AND a.language = "de" AND b.language = "en"'
                        ' WHERE a.name <> b.name'
                        % (table, table, key, key)).fetchone()[0]
                    self.assertEqual(0, said)
                    languages = {row[0] for row in conn.execute(
                        'SELECT DISTINCT language FROM %s' % table)}
                    self.assertEqual({'en', 'fr', 'es', 'pt', 'de'}, languages)
        finally:
            conn.close()

    def test_an_upgrade_consumes_the_rarity_below_and_not_itself(self):
        # An upgrade eats the same-named item one rarity below, never itself
        conn = self._conn()
        try:
            eats_itself = conn.execute(
                'SELECT r.item FROM item_recipes r JOIN items i ON i.id = r.item'
                ' WHERE r.ingredient_ankama_id = i.ankama_id LIMIT 5').fetchall()
            self.assertEqual([], eats_itself)
            product = conn.execute(
                'SELECT id, ankama_id FROM items WHERE name = "Glaivus Shushu"'
                ' AND id IN (SELECT item FROM item_recipes)').fetchone()
            self.assertIsNotNone(product)
            same_name = conn.execute(
                'SELECT n.name, r.ingredient_ankama_id FROM item_recipes r'
                ' JOIN item_recipe_ingredient_names n'
                ' ON n.ingredient_ankama_id = r.ingredient_ankama_id'
                ' AND n.ingredient_subtype = r.ingredient_subtype'
                ' AND n.language = "en"'
                ' WHERE r.item = ? AND n.name = "Glaivus Shushu"',
                (product[0],)).fetchall()
            self.assertEqual(1, len(same_name))
            self.assertNotEqual(product[1], same_name[0][1])
            # One rarity below
            tiers = conn.execute(
                'SELECT (SELECT rarity FROM item_rarity WHERE item = ?),'
                ' (SELECT rarity FROM item_rarity WHERE item = ?)',
                (product[0], same_name[0][1])).fetchone()
            self.assertEqual(tiers[0], tiers[1] + 1)
        finally:
            conn.close()


class WakfuGearReachesFarPastAnyCapTests(SimpleTestCase):
    """Wakfu gear alone passes every AP and MP cap anyone has claimed."""

    def _ceiling(self, key):
        import collections
        import sqlite3
        from fashionistapulp.fashionista_config import get_items_db_path
        path = get_items_db_path('wakfu')
        if not os.path.exists(path):
            self.skipTest('no Wakfu database built; run update_data_wakfu.py')
        conn = sqlite3.connect('file:%s?mode=ro' % path, uri=True)
        try:
            stat = conn.execute('SELECT id FROM stats WHERE key = ?',
                                (key,)).fetchone()
            self.assertIsNotNone(stat, key)
            places = collections.defaultdict(set)
            for type_id, position in conn.execute(
                    'SELECT item_type, position FROM item_type_position'):
                places[type_id].add(position)
            best = collections.defaultdict(int)
            for type_id, value in conn.execute(
                    'SELECT i.type, s.value FROM items i'
                    ' JOIN stats_of_item s ON s.item = i.id'
                    ' WHERE s.stat = ?', (stat[0],)):
                for position in places[type_id]:
                    best[position] = max(best[position], value)
        finally:
            conn.close()
        return sum(best.values()), max(best.values() or [0])

    def test_gear_alone_passes_every_cap_anyone_has_claimed(self):
        # Highest claimed caps: 14 AP, 8 MP
        total, single = self._ceiling('ap')
        self.assertGreater(total, 14, 'AP from gear no longer beats any cap')
        self.assertGreaterEqual(single, 3)
        total, single = self._ceiling('mp')
        self.assertGreater(total, 8, 'MP from gear no longer beats any cap')
        self.assertGreaterEqual(single, 2)
        for key in ('wp', 'range'):
            with self.subTest(stat=key):
                total, _single = self._ceiling(key)
                self.assertGreater(total, 10)

    def test_every_cap_is_below_what_gear_can_buy(self):
        from fashionistapulp.wakfu_stats import (BASE_VALUES,
                                                 OUT_OF_COMBAT_CAPS)
        self.assertEqual({'AP', 'MP', 'WP'}, set(OUT_OF_COMBAT_CAPS))
        self.assertEqual(set(OUT_OF_COMBAT_CAPS), set(BASE_VALUES))
        for name, cap in OUT_OF_COMBAT_CAPS.items():
            with self.subTest(stat=name):
                gear, _single = self._ceiling(name.lower())
                # The cap is on the total, base included
                self.assertGreater(
                    BASE_VALUES[name] + gear, cap,
                    '%s: a character can reach %d and the cap is %d, so the '
                    'cap binds nothing and one of the two numbers is wrong'
                    % (name, BASE_VALUES[name] + gear, cap))

    def test_the_critical_hit_floor_is_a_rule_the_catalogue_needs(self):
        # The floor comes from a fan site: checked against Ankama's data
        import sqlite3
        from fashionistapulp.fashionista_config import get_items_db_path
        from fashionistapulp.wakfu_stats import CRITICAL_HIT_FLOOR_PERCENT
        self.assertLess(CRITICAL_HIT_FLOOR_PERCENT, 0)
        path = get_items_db_path('wakfu')
        if not os.path.exists(path):
            self.skipTest('no Wakfu database built; run update_data_wakfu.py')
        conn = sqlite3.connect('file:%s?mode=ro' % path, uri=True)
        try:
            worst = conn.execute(
                'SELECT MIN(s.value), COUNT(*) FROM stats_of_item s'
                ' JOIN stats t ON t.id = s.stat'
                ' WHERE t.key = "ferocity" AND s.value < 0').fetchone()
        finally:
            conn.close()
        self.assertGreater(worst[1], 50, 'no gear sells negative critical hit')
        self.assertLess(worst[0], CRITICAL_HIT_FLOOR_PERCENT,
                        'no single item passes the floor on its own, so the '
                        'rule could have been about one piece')


def _newest_wakfu_harvest():
    """spells_fr.json of the newest mirrored Wakfu build that holds one."""
    mirror = os.path.join(os.path.dirname(os.path.dirname(os.path.dirname(
        os.path.abspath(__file__)))), 'itemscraper', 'wakfu_raw')
    builds = [build for build in (os.listdir(mirror) if os.path.isdir(mirror) else [])
              if os.path.exists(os.path.join(mirror, build, 'spells_fr.json'))]
    newest = max(builds or ['none'], key=lambda build: [
        int(part) if part.isdigit() else -1 for part in build.split('.')])
    return os.path.join(mirror, newest, 'spells_fr.json')


class WakfuSpellsComeFromTheEncyclopediaTests(SimpleTestCase):
    """Wakfu spells come from the encyclopedia: spells.json answers 403."""

    HARVEST = _newest_wakfu_harvest()
    _cache = {}

    def _spells(self):
        # Read once per process, the harvest is huge
        return self._harvest('fr')

    def test_every_class_is_there_with_a_full_book(self):
        # Ids 1 to 19 without 17; Ankama files the Ouginak under an empty slug
        spells = self._spells()
        by_class = {}
        for spell in spells.values():
            by_class.setdefault(spell['class'], 0)
            by_class[spell['class']] += 1
        self.assertEqual(18, len(by_class))
        self.assertNotIn(17, by_class)
        for class_id, count in sorted(by_class.items()):
            with self.subTest(wakfu_class=class_id):
                self.assertGreater(count, 25)

    def test_a_spell_carries_all_of_its_levels(self):
        # The page embeds every level, 1 to 245
        spells = self._spells()
        for spell in list(spells.values())[:40]:
            with self.subTest(spell=spell['name']):
                levels = spell['levels']
                self.assertEqual(245, len(levels))
                self.assertIn('1', levels)
                self.assertIn('245', levels)

    def test_damage_never_shrinks_with_the_level(self):
        """Damage never goes down with the level; flat passives hold still."""
        spells = self._spells()
        checked = grew = 0
        for spell in spells.values():
            first = spell['levels']['1']['damage']
            last = spell['levels']['245']['damage']
            if not first or not last or len(first) != len(last):
                continue
            checked += 1
            low = sum(v for _e, v in first)
            high = sum(v for _e, v in last)
            if high > low:
                grew += 1
            with self.subTest(spell=spell['name']):
                self.assertGreaterEqual(high, low,
                                        'hits softer at 245 than at 1')
        self.assertGreater(checked, 100, 'almost no spell had damage to check')
        self.assertGreater(grew, checked * 9 // 10,
                           'only %d of %d spells grow with the level, which is '
                           'too few to be the passives' % (grew, checked))

    # Anything smaller is a partial harvest
    A_FULL_BOOK = 700

    def _harvest(self, language):
        path = self.HARVEST.replace('spells_fr.json', 'spells_%s.json' % language)
        if not os.path.exists(path):
            self.skipTest('no Wakfu spells collected in %s; run '
                          'itemscraper/get_spells_wakfu.py --lang %s'
                          % (language, language))
        if language not in self._cache:
            with io.open(path, encoding='utf-8') as handle:
                self._cache[language] = json.load(handle)
        book = self._cache[language]
        if len(book) < self.A_FULL_BOOK:
            self.skipTest('the %s harvest holds %d spells, not a full book'
                          % (language, len(book)))
        return book

    def _stamp(self, language):
        """Parser stamp from the .meta.json beside a harvest."""
        path = self.HARVEST.replace('spells_fr.json',
                                    'spells_%s.meta.json' % language)
        if not os.path.exists(path):
            return None
        with io.open(path, encoding='utf-8') as handle:
            return json.load(handle).get('parser')

    def _same_parser(self, left, right, languages=('fr', 'en')):
        """Skip unless both harvests were read by the same parser."""
        here, there = (self._stamp(language) for language in languages)
        if here is None or there is None:
            self.skipTest('a harvest carries no parser stamp; re-run '
                          'get_spells_wakfu.py for %s and %s' % languages)
        if here != there:
            self.skipTest('%s and %s were read by different parsers, %s '
                          'against %s; re-run both before comparing them'
                          % (languages[0], languages[1], here, there))

    def test_the_numbers_are_the_same_in_both_languages(self):
        # Figures do not translate: both languages must give the same numbers
        french, english = self._harvest('fr'), self._harvest('en')
        self._same_parser(french, english)
        shared = sorted(set(french) & set(english), key=int)
        self.assertGreater(len(shared), 600)
        disagree = []
        for spell_id in shared:
            for level in ('1', '100', '245'):
                left = french[spell_id]['levels'][level]
                right = english[spell_id]['levels'][level]
                if left['damage'] != right['damage']:
                    disagree.append((french[spell_id]['name'], level,
                                     left['damage'], right['damage']))
                    break
                if left['ap'] != right['ap'] or left['range'] != right['range']:
                    disagree.append((french[spell_id]['name'], level,
                                     left['ap'], right['ap']))
                    break
        self.assertEqual([], disagree[:5],
                         '%d spells read differently in the two languages'
                         % len(disagree))

    def test_the_four_languages_agree_on_which_rows_are_conditional(self):
        """Conditional rows start with ": -" in every language."""
        books = {language: self._harvest(language)
                 for language in ('fr', 'en', 'es', 'pt')}
        french = books['fr']
        # All four: a harvest rewrites the files one after another
        for language in ('en', 'es', 'pt'):
            self._same_parser(french, books[language], ('fr', language))
        if not any(len(row) > 4
                   for spell in french.values()
                   for level in spell['levels'].values()
                   for row in level.get('rows') or ()):
            self.skipTest('this harvest predates the conditional mark')

        def flags(book, spell_id):
            rows = book[spell_id]['levels']['245'].get('rows') or ()
            return tuple(bool(row[4]) for row in rows if len(row) > 4)

        disagree, marked = [], 0
        for spell_id in sorted(set(french) & set(books['en']), key=int):
            here = flags(french, spell_id)
            marked += sum(here)
            for language in ('en', 'es', 'pt'):
                if spell_id not in books[language]:
                    continue
                theirs = flags(books[language], spell_id)
                if theirs != here:
                    disagree.append((french[spell_id]['name'], language,
                                     here, theirs))
                    break
        self.assertGreater(marked, 20,
                           'nothing was marked conditional, so nothing was '
                           'tested')
        self.assertEqual([], disagree[:5],
                         '%d spells read differently in two languages'
                         % len(disagree))

    def test_only_the_sram_has_a_different_book_per_language(self):
        # Ankama's French and English Sram books differ, no other class does
        french, english = self._harvest('fr'), self._harvest('en')
        classes = set()
        for spell_id in set(french) ^ set(english):
            book = french if spell_id in french else english
            classes.add(book[spell_id]['class'])
        self.assertEqual({4}, classes)

    def test_a_branch_disagrees_with_its_damage_only_over_light(self):
        # Light: no gear sells it, yet elemental branches deal it
        from fashionistapulp.wakfu_stats import DAMAGE_ELEMENTS_NO_GEAR_SELLS
        spells = self._spells()
        odd = []
        lit = set()
        for spell in spells.values():
            elements = {element for element, _value
                        in spell['levels']['245']['damage']}
            if 'LIGHT' in elements:
                lit.add(spell['class'])
            if not spell['element'] or not elements:
                continue
            if spell['element'] not in elements:
                if elements <= set(DAMAGE_ELEMENTS_NO_GEAR_SELLS):
                    continue
                odd.append((spell['name'], spell['element'], sorted(elements)))
        self.assertEqual([], odd[:5])
        self.assertGreater(len(lit), 5,
                           'light turned out to be one class only, so it is '
                           'not the general mechanic this assumes')


class ARejectedLinkCannotCarryMarkupBackTests(TestCase):
    """The echo of a refused link on the compare page cannot carry markup."""

    ATTACK = '<script>alert(1)</script>'

    def _refuse(self, links):
        return self.client.post('/choose_compare_sets_post/',
                                {'links': json.dumps(links)})

    def test_the_echo_cannot_open_a_tag(self):
        answer = self._refuse(['https://example.com/%s' % self.ATTACK,
                               'https://example.com/also-bad'])
        body = answer.content.decode('utf-8')
        self.assertNotIn('<', body)
        self.assertNotIn('>', body)
        # The text stays, it just cannot open a tag
        self.assertIn('scriptalert(1)', body)

    def test_the_browser_is_told_not_to_guess(self):
        # The header comes from SecurityMiddleware, not from the response
        from django.conf import settings
        self.assertTrue(settings.SECURE_CONTENT_TYPE_NOSNIFF)
        answer = self._refuse(['nonsense one', 'nonsense two'])
        self.assertEqual('nosniff', answer['X-Content-Type-Options'])
        self.assertTrue(answer['Content-Type'].startswith('text/plain'))

    def test_a_real_link_still_reads_back(self):
        answer = self._refuse(['https://dofusfashionista.gg/s/abc123',
                               'https://dofusfashionista.gg/s/def456'])
        body = answer.content.decode('utf-8')
        self.assertIn('dofusfashionista.gg/s/abc123', body)


def _without_scripts(markup):
    """The page with every script element removed, tags and attributes kept."""
    from html.parser import HTMLParser

    class _Strip(HTMLParser):
        def __init__(self):
            HTMLParser.__init__(self, convert_charrefs=False)
            self.parts = []
            self.quiet = 0

        def _keep(self, text):
            if not self.quiet:
                self.parts.append(text)

        def handle_starttag(self, tag, attrs):
            if tag == 'script':
                self.quiet += 1
            else:
                self._keep(self.get_starttag_text())

        def handle_startendtag(self, tag, attrs):
            if tag != 'script':
                self._keep(self.get_starttag_text())

        def handle_endtag(self, tag):
            if tag == 'script':
                self.quiet = max(0, self.quiet - 1)
            else:
                self._keep('</%s>' % tag)

        def handle_data(self, data):
            self._keep(data)

        def handle_entityref(self, name):
            self._keep('&%s;' % name)

        def handle_charref(self, name):
            self._keep('&#%s;' % name)

        def handle_comment(self, data):
            self._keep('<!--%s-->' % data)

    reader = _Strip()
    reader.feed(markup)
    reader.close()
    return ''.join(reader.parts)


def _local_links(markup):
    """Every in-site href on a page, without fragment or query."""
    from html.parser import HTMLParser

    class _Links(HTMLParser):
        def __init__(self):
            HTMLParser.__init__(self, convert_charrefs=True)
            self.found = set()

        def handle_starttag(self, tag, attrs):
            if tag != 'a':
                return
            href = dict(attrs).get('href') or ''
            if href.startswith('/'):
                self.found.add(href.split('#')[0].split('?')[0])

    reader = _Links()
    reader.feed(markup)
    reader.close()
    return reader.found


class WakfuSpellTablesHoldOnlyWhatVariesTests(SimpleTestCase):
    """Wakfu spell costs never vary with the level: stored once per spell."""

    def _conn(self):
        import sqlite3
        from fashionistapulp.fashionista_config import get_items_db_path
        path = get_items_db_path('wakfu')
        if not os.path.exists(path):
            self.skipTest('no Wakfu database built; run update_data_wakfu.py')
        conn = sqlite3.connect('file:%s?mode=ro' % path, uri=True)
        if not conn.execute('SELECT COUNT(*) FROM spells').fetchone()[0]:
            conn.close()
            self.skipTest('no Wakfu spells imported yet')
        return conn

    def test_the_cost_is_stored_once_and_not_per_level(self):
        conn = self._conn()
        try:
            spells = conn.execute('SELECT COUNT(*) FROM spells').fetchone()[0]
            levels = conn.execute(
                'SELECT COUNT(DISTINCT level) FROM spell_effects').fetchone()[0]
            self.assertGreater(spells, 700)
            self.assertEqual(245, levels)
            # One row per spell, not one per spell and level
            self.assertEqual(spells, conn.execute(
                'SELECT COUNT(*) FROM spells').fetchone()[0])
            costs = conn.execute(
                'SELECT COUNT(*) FROM spells WHERE ap IS NOT NULL').fetchone()[0]
            self.assertGreater(costs, 300, 'no spell costs any AP at all?')
        finally:
            conn.close()

    def test_every_effect_belongs_to_a_spell_that_is_there(self):
        conn = self._conn()
        try:
            for table in ('spell_effects', 'spell_names', 'spell_text'):
                with self.subTest(table=table):
                    orphans = conn.execute(
                        'SELECT COUNT(*) FROM %s x WHERE NOT EXISTS'
                        ' (SELECT 1 FROM spells s WHERE s.id = x.spell)'
                        % table).fetchone()[0]
                    self.assertEqual(0, orphans)
        finally:
            conn.close()

    def test_a_per_cent_is_not_stored_as_a_quantity(self):
        # "Dommage : 10 %" of the caster's health is not a flat 10
        conn = self._conn()
        try:
            marked = conn.execute(
                'SELECT COUNT(DISTINCT spell) FROM spell_effects'
                ' WHERE is_percent = 1').fetchone()[0]
            self.assertGreater(marked, 0)
            self.assertLess(marked, 40, 'far too many to be percentages')
            # No row is both percent and flat
            both = conn.execute(
                'SELECT COUNT(*) FROM spell_effects a JOIN spell_effects b'
                ' ON a.spell = b.spell AND a.level = b.level'
                ' AND a.position = b.position AND a.is_percent <> b.is_percent'
                ).fetchone()[0]
            self.assertEqual(0, both)
        finally:
            conn.close()

    def test_a_conditional_row_is_marked_and_most_are_not(self):
        conn = self._conn()
        try:
            # Older databases have no conditional column
            columns = {row[1] for row in
                       conn.execute('PRAGMA table_info(spell_effects)')}
            if 'conditional' not in columns:
                self.skipTest('this database predates the conditional mark')
            counted = dict(conn.execute(
                'SELECT conditional, COUNT(*) FROM spell_effects'
                ' GROUP BY conditional').fetchall())
        finally:
            conn.close()
        self.assertEqual({0, 1}, set(counted),
                         'the conditional mark never varies: %s' % counted)
        # Most rows land on a plain cast; the margin is loose on purpose
        self.assertGreater(counted[0], counted[1] * 2)

    def test_the_classes_are_balanced_against_each_other(self):
        """The best spell per AP of each class stays near the median."""
        conn = self._conn()
        try:
            best = {}
            for wakfu_class, ap, base in conn.execute(
                    'SELECT s.class, s.ap,'
                    ' (SELECT e.value FROM spell_effects e'
                    '   WHERE e.spell = s.id AND e.level = 245'
                    '   AND e.kind = "damage" AND e.conditional = 0'
                    '   AND e.is_percent = 0 ORDER BY e.position LIMIT 1)'
                    ' FROM spells s WHERE s.ap > 0'):
                if not base:
                    continue
                best[wakfu_class] = max(best.get(wakfu_class, 0), base / ap)
        finally:
            conn.close()
        self.assertGreater(len(best), 15, 'most classes have no damage spell')
        ranked = sorted(best.values())
        median = ranked[len(ranked) // 2]
        spread = ranked[-1] / median
        self.assertLess(spread, 2.0,
                        'one class hits %.1fx the median per AP, which is a '
                        'reading that adds up rows the game does not: %s'
                        % (spread, sorted(best.items(),
                                          key=lambda kv: -kv[1])[:3]))

    def test_german_reads_english_like_every_other_wakfu_table(self):
        conn = self._conn()
        try:
            languages = {row[0] for row in conn.execute(
                'SELECT DISTINCT language FROM spell_names')}
            self.assertEqual({'en', 'fr', 'es', 'pt', 'de'}, languages)
            said = conn.execute(
                'SELECT COUNT(*) FROM spell_names a JOIN spell_names b'
                ' ON a.spell = b.spell AND a.language = "de"'
                ' AND b.language = "en" WHERE a.name <> b.name').fetchone()[0]
            self.assertEqual(0, said)
            # French decides which spells exist
            self.assertEqual(0, conn.execute(
                'SELECT COUNT(*) FROM spells s WHERE NOT EXISTS'
                ' (SELECT 1 FROM spell_names n WHERE n.spell = s.id'
                ' AND n.language = "fr")').fetchone()[0])
        finally:
            conn.close()


class TheWakfuSolverObeysTheGameTests(SimpleTestCase):
    """Wakfu builds obey slot, hand, exclusivity, cap and crit floor rules."""

    # Lowest level where gear can reach a cap
    BINDS = 100

    def _structure(self):
        from fashionistapulp.fashionista_config import get_items_db_path
        from fashionistapulp.structure import get_structure
        if not os.path.exists(get_items_db_path('wakfu')):
            self.skipTest('no Wakfu database built; run update_data_wakfu.py')
        return get_structure('wakfu')

    def _build(self, level, weights, forbidden=()):
        from fashionistapulp.wakfu_model import WakfuBuild
        build = WakfuBuild(self._structure(), level, weights, forbidden)
        return build, build.build().solve()

    def test_a_build_wears_one_item_per_slot_and_no_item_twice(self):
        from fashionistapulp.wakfu_slots import SLOTS
        build, worn = self._build(50, {'hp': 1, 'ap': 200, 'mp': 150})
        self.assertIsNotNone(worn, 'no legal set at all at level 50')
        self.assertEqual(set(), set(worn) - set(SLOTS))
        # Keyed by slot: check no item sits in two slots
        ids = [item.id for item in worn.values()]
        self.assertEqual(len(ids), len(set(ids)), 'an item is worn twice')
        for item in worn.values():
            self.assertLessEqual(item.level, 50)

    def test_no_build_passes_a_cap_and_pushing_reaches_it(self):
        from fashionistapulp.wakfu_stats import OUT_OF_COMBAT_CAPS
        reached = 0
        for name, cap in OUT_OF_COMBAT_CAPS.items():
            with self.subTest(stat=name):
                build, worn = self._build(self.BINDS, {name.lower(): 10000})
                self.assertIsNotNone(worn)
                total = build.totals(worn)[name.lower()]
                self.assertLessEqual(total, cap,
                                     '%s reached %d, past its cap of %d'
                                     % (name, total, cap))
                reached += total == cap
        self.assertGreater(reached, 0,
                           'no cap was reachable, so none of them was tested')

    def test_the_critical_hit_floor_holds(self):
        # Negative crit buys other stats; the game floors the total
        from fashionistapulp.wakfu_stats import CRITICAL_HIT_FLOOR_PERCENT
        build, worn = self._build(self.BINDS, {'hp': 1, 'ferocity': -1000})
        self.assertIsNotNone(worn)
        total = build.totals(worn)['ferocity']
        self.assertGreaterEqual(total, CRITICAL_HIT_FLOOR_PERCENT)
        self.assertEqual(CRITICAL_HIT_FLOOR_PERCENT, total,
                         'the floor was never reached, so it was not tested')

    def test_a_two_handed_weapon_leaves_the_off_hand_empty(self):
        # One-handed weapons forbidden: two-handed or nothing
        structure = self._structure()
        places = {}
        for type_id, position in structure.get_type_positions():
            places.setdefault(type_id, []).append(position)
        one_handed = {item.id for item in structure.get_items_list()
                      if 'FIRST_WEAPON' in places.get(item.type, ())
                      and 'two_handed' not in (item.flags or ())}
        self.assertGreater(len(one_handed), 100)
        build, worn = self._build(self.BINDS, {'hp': 1, 'ap': 200},
                                  forbidden=one_handed)
        self.assertIsNotNone(worn)
        weapon = worn.get('FIRST_WEAPON')
        self.assertIsNotNone(weapon, 'no weapon was taken, so nothing is shown')
        self.assertIn('two_handed', weapon.flags)
        self.assertNotIn('SECOND_WEAPON', worn,
                         'a two-handed weapon left the off hand filled')

    def test_every_slot_is_filled_even_when_it_adds_nothing(self):
        """Every slot but the off hand is filled, even when it adds nothing."""
        from fashionistapulp.wakfu_slots import SLOTS
        build, worn = self._build(self.BINDS, {'ap': 10000})
        self.assertIsNotNone(worn)
        self.assertTrue(build.full_set, 'fell back to the loose form')
        missing = set(SLOTS) - set(worn) - {'SECOND_WEAPON'}
        self.assertEqual(set(), missing)

    def test_a_level_one_character_still_gets_an_answer(self):
        # Few slots have anything at level 1
        build, worn = self._build(1, {'hp': 1})
        self.assertIsNotNone(worn, 'no set at all at level 1')
        self.assertGreater(len(worn), 3)
        for item in worn.values():
            self.assertLessEqual(item.level, 1)

    def test_the_spread_lines_are_what_a_fire_build_buys(self):
        """Most mastery lines name no element; a fire build must use them."""
        import sqlite3
        from fashionistapulp.fashionista_config import get_items_db_path
        structure = self._structure()
        conn = sqlite3.connect('file:%s?mode=ro' % get_items_db_path('wakfu'),
                               uri=True)
        try:
            named, spread = (conn.execute(
                'SELECT COUNT(DISTINCT s.item) FROM stats_of_item s'
                ' JOIN stats t ON t.id = s.stat WHERE t.key = ?',
                (key,)).fetchone()[0]
                for key in ('dmg_fire_percent', 'dmg_in_percent'))
        finally:
            conn.close()
        self.assertGreater(spread, named * 50,
                           'the spread lines stopped being the whole game')

        build, worn = self._build(self.BINDS, {'dmg_fire_percent': 1})
        self.assertIsNotNone(worn)
        carrying = [item for item in worn.values() if item.element_spread]
        self.assertGreater(len(carrying), len(worn) * 2 // 3,
                           'a fire build took gear that names no element')
        landing = build.where_the_spread_lands(worn)
        self.assertGreater(landing['dmg_fire_percent'], 0)

    def test_wanting_one_element_beats_wanting_three(self):
        # A three-element line feeds three: wanting one element gets more of it
        one, worn_one = self._build(self.BINDS, {'dmg_fire_percent': 1})
        three, worn_three = self._build(
            self.BINDS, {'dmg_fire_percent': 1, 'dmg_water_percent': 1,
                         'dmg_earth_percent': 1})
        self.assertIsNotNone(worn_one)
        self.assertIsNotNone(worn_three)
        fire_alone = one.where_the_spread_lands(worn_one)['dmg_fire_percent']
        fire_shared = three.where_the_spread_lands(worn_three)['dmg_fire_percent']
        self.assertGreater(fire_alone, 0)
        self.assertGreaterEqual(fire_alone, fire_shared)
        # Spreading buys the other elements
        self.assertGreater(
            three.where_the_spread_lands(worn_three)['dmg_earth_percent'],
            one.where_the_spread_lands(worn_one)['dmg_earth_percent'])

    def test_at_most_one_relic_and_one_epic(self):
        build, worn = self._build(self.BINDS, {'hp': 1, 'ap': 200, 'mp': 150})
        self.assertIsNotNone(worn)
        for flag in ('relic', 'epic'):
            with self.subTest(flag=flag):
                wearing = [item.name for item in worn.values()
                           if flag in (item.flags or ())]
                self.assertLessEqual(len(wearing), 1, wearing)


class NothingWritesOutTheVersionsByHandTests(SimpleTestCase):
    """Tools that walk every Dofus version ask the registry."""

    ROOT = os.path.dirname(os.path.dirname(os.path.dirname(
        os.path.abspath(__file__))))
    WALKERS = (
        ('itemscraper', 'check_rebuild.py'),
        ('itemscraper', 'sanitize_untranslated_tags.py'),
    )

    def _module(self, parts):
        import importlib.util
        import sys
        path = os.path.join(self.ROOT, *parts)
        folder = os.path.dirname(path)
        added = folder not in sys.path
        if added:
            sys.path.insert(0, folder)
        try:
            spec = importlib.util.spec_from_file_location(parts[-1][:-3], path)
            module = importlib.util.module_from_spec(spec)
            spec.loader.exec_module(module)
            return module
        finally:
            if added:
                sys.path.remove(folder)

    def test_the_scrapers_ask_the_registry(self):
        from fashionistapulp.game_versions import dofus_versions
        expected = tuple(dofus_versions())
        self.assertEqual(5, len(expected))
        self.assertNotIn('wakfu', expected)
        for parts in self.WALKERS:
            with self.subTest(script=parts[-1]):
                self.assertEqual(expected, self._module(parts).VERSIONS)

    def test_the_management_commands_ask_the_registry(self):
        from chardata.management.commands import check_actions, check_pages
        from fashionistapulp.game_versions import dofus_versions
        expected = tuple(dofus_versions())
        for command in (check_actions, check_pages):
            with self.subTest(command=command.__name__):
                self.assertEqual(expected, command.VERSIONS)

    #: Hand-written per-version maps: their keys must cover every version
    PER_VERSION_MAPS = (
        ('chardata.admin_tools_view', 'VERSION_COLOURS'),
        ('chardata.context_processors', '_GAME_VERSION_SEO_WORDS'),
        ('chardata.encyclopedia_view', '_INGREDIENT_ICON_DIRS'),
        ('chardata.forgemagie_data', '_RULESET_BY_VERSION'),
        ('chardata.smart_build', 'VERSION_WEIGHT_TUNING'),
        ('fashionistapulp.structure', 'GELANO_DEPLOYED_IDS'),
    )

    def test_every_map_keyed_by_version_names_the_ones_served(self):
        import importlib
        from fashionistapulp.game_versions import version_keys
        served = set(version_keys())
        for module_name, attribute in self.PER_VERSION_MAPS:
            with self.subTest(mapping='%s.%s' % (module_name, attribute)):
                mapping = getattr(importlib.import_module(module_name),
                                  attribute)
                self.assertEqual(
                    [], sorted(served - set(mapping)),
                    '%s does not name every version the site serves'
                    % attribute)

    def test_the_footer_names_a_data_version_for_each(self):
        from django.conf import settings
        from fashionistapulp.game_versions import version_keys
        self.assertEqual(
            [], sorted(set(version_keys()) - set(settings.SITE_VERSIONS)),
            'the footer would show no data version for these')

    def test_the_rebuild_tools_name_every_version(self):
        from fashionistapulp.game_versions import dofus_versions
        expected = set(dofus_versions())
        for parts, attribute in (
                (('itemscraper', 'check_rebuild.py'), 'COMMITTED'),
                (('itemscraper', 'store_weapon_uses_per_turn.py'), 'WORK_DIR')):
            with self.subTest(script=parts[-1]):
                mapping = getattr(self._module(parts), attribute)
                self.assertEqual([], sorted(expected - set(mapping)),
                                 '%s in %s misses a version' % (attribute,
                                                                parts[-1]))


class GameVersionRegistryTests(SimpleTestCase):
    """The game registry: an unknown version raises, never falls back."""

    def test_an_unknown_version_is_named_not_swallowed(self):
        from fashionistapulp.fashionista_config import (get_items_db_path,
                                                        get_items_dump_path)
        for asking in ('dofus4', 'wakfoo', '', None):
            for reader in (get_items_db_path, get_items_dump_path):
                with self.subTest(asking=asking, reader=reader.__name__):
                    with self.assertRaises(KeyError) as caught:
                        reader(asking)
                    self.assertIn('unknown game version', str(caught.exception))

    def test_every_version_still_reads_the_file_it_always_read(self):
        import os
        from fashionistapulp.fashionista_config import (get_items_db_path,
                                                        get_items_dump_path)
        expected = {
            'dofus3': ('items.db', 'item_db_dumped.dump'),
            'beta': ('items_beta.db', 'item_db_dumped_beta.dump'),
            'dofus2': ('items_dofus2.db', 'item_db_dumped_dofus2.dump'),
            'touch': ('items_touch.db', 'item_db_dumped_touch.dump'),
            'retro': ('items_retro.db', 'item_db_dumped_retro.dump'),
        }
        for version, (db_file, dump_file) in expected.items():
            with self.subTest(version=version):
                self.assertEqual(db_file,
                                 os.path.basename(get_items_db_path(version)))
                self.assertEqual(dump_file,
                                 os.path.basename(get_items_dump_path(version)))

    def test_the_registry_holds_every_version_the_site_serves(self):
        # settings.SITE_VERSIONS still lists them for the footer
        from django.conf import settings
        from fashionistapulp.game_versions import version_keys
        self.assertEqual(sorted(settings.SITE_VERSIONS),
                         sorted(version_keys()))

    def test_wakfu_is_declared_and_reaches_no_reader(self):
        # Experimental: declared for the pipeline, hidden from readers
        from fashionistapulp.game_versions import (GAME_VERSIONS,
                                                   dofus_versions,
                                                   version_keys)
        wakfu = GAME_VERSIONS['wakfu']
        self.assertTrue(wakfu.experimental)
        self.assertFalse(wakfu.dofus)
        self.assertNotIn('wakfu', version_keys())
        self.assertIn('wakfu', version_keys(include_experimental=True))
        self.assertNotIn('wakfu', dofus_versions())
        for key in dofus_versions():
            with self.subTest(version=key):
                self.assertTrue(GAME_VERSIONS[key].dofus)
                self.assertFalse(GAME_VERSIONS[key].experimental)


