    def test_every_spell_icon_the_pages_ask_for_is_on_disk(self):
        # The url comes from the spell name, a rename serves a 404
        from urllib.parse import unquote
        from chardata.spell_buffs import get_damage_spells_for_version
        from chardata.spells_view import _spell_icon_name, _spell_image_url
        from fashionistapulp.fashionista_config import get_fashionista_path
        static = os.path.join(get_fashionista_path(), 'fashionsite', 'chardata',
                              'static')
        for version in ('dofus3', 'beta', 'dofus2', 'retro', 'touch'):
            names = set()
            for spells in get_damage_spells_for_version(version).values():
                for spell in spells:
                    if isinstance(spell, dict):
                        name, spell_id = spell.get('name'), spell.get('spell_id')
                    else:
                        name = getattr(spell, 'name', None)
                        spell_id = getattr(spell, 'spell_id', None)
                    if name:
                        names.add(_spell_icon_name(name, spell_id, version))
            missing = sorted(
                name for name in names
                if not os.path.exists(os.path.join(
                    static,
                    unquote(_spell_image_url(name, version))
                    .split('/static/', 1)[-1].replace('/', os.sep))))
            with self.subTest(version=version):
                self.assertEqual([], missing)

    def test_no_spell_icon_is_on_the_disk_without_being_committed(self):
        """Committed, not only on disk: git cannot index Con.png on Windows."""
        import subprocess
        from urllib.parse import unquote
        from chardata.spell_buffs import get_damage_spells_for_version
        from chardata.spells_view import _spell_icon_name, _spell_image_url
        from fashionistapulp.fashionista_config import get_fashionista_path

        root = get_fashionista_path()
        listing = subprocess.run(
            ['git', 'ls-files', '-z', '--',
             'fashionsite/chardata/static/chardata/spells'],
            cwd=root, capture_output=True)
        if listing.returncode != 0:
            self.skipTest('git is not available to say what is committed')
        committed = {path for path in
                     listing.stdout.decode('utf-8').split('\0') if path}
        self.assertGreater(len(committed), 500,
                           'git listed almost nothing: the query is wrong, '
                           'not the repository')

        static = os.path.join(root, 'fashionsite', 'chardata', 'static')
        uncommitted = set()
        for version in ('dofus3', 'beta', 'dofus2', 'retro', 'touch'):
            for spells in get_damage_spells_for_version(version).values():
                for spell in spells:
                    if isinstance(spell, dict):
                        name, spell_id = spell.get('name'), spell.get('spell_id')
                    else:
                        name = getattr(spell, 'name', None)
                        spell_id = getattr(spell, 'spell_id', None)
                    if not name:
                        continue
                    relative = (unquote(_spell_image_url(
                        _spell_icon_name(name, spell_id, version), version))
                                .split('/static/', 1)[-1])
                    on_disk = os.path.join(static,
                                           relative.replace('/', os.sep))
                    if not os.path.exists(on_disk):
                        continue          # the guard above owns that case
                    if 'fashionsite/chardata/static/' + relative not in committed:
                        uncommitted.add(relative)
        self.assertEqual(sorted(uncommitted), [])

