class PickerCacheKeyTests(TestCase):
    """Switching an item drops the picker's cached list."""

    def setUp(self):
        from django.core.cache import cache
        cache.clear()

    def test_switching_an_item_moves_the_key(self):
        from chardata.util import get_picker_cache_key, remove_cache_for_char
        before = get_picker_cache_key(7, 1, '', 'true', '[]')
        remove_cache_for_char(7)
        after = get_picker_cache_key(7, 1, '', 'true', '[]')
        self.assertNotEqual(before, after)
        # and again, so a second switch is not a no-op
        remove_cache_for_char(7)
        self.assertNotIn(get_picker_cache_key(7, 1, '', 'true', '[]'),
                         (before, after))

    def test_what_was_cached_is_no_longer_read(self):
        from django.core.cache import cache
        from chardata.util import get_picker_cache_key, remove_cache_for_char
        key = get_picker_cache_key(11, 2, '', 'true', '[]')
        cache.set(key, ['stale list'], 300)
        remove_cache_for_char(11)
        self.assertIsNone(cache.get(get_picker_cache_key(11, 2, '', 'true',
                                                        '[]')))

    def test_one_project_does_not_drop_another(self):
        from chardata.util import get_picker_cache_key, remove_cache_for_char
        other = get_picker_cache_key(12, 1, '', 'true', '[]')
        remove_cache_for_char(11)
        self.assertEqual(other, get_picker_cache_key(12, 1, '', 'true', '[]'))

    def test_saving_the_project_moves_the_key_on_its_own(self):
        # The counter is per worker; modified_time is shared in the database
        from django.contrib.auth.models import User
        from chardata.models import Char
        from chardata.util import get_picker_cache_key
        owner = User.objects.create_user('keymover', 'km@test.local', 'pw-42-sol')
        char = Char.objects.create(
            name='Key', char_name='key', char_class='Iop', char_build='build',
            level=200, minimum_stats=b'', minimum_crits=b'', stats_weight=b'',
            options=b'', inclusions=b'', exclusions=b'', owner=owner,
            link_shared=False, game_version='dofus3')
        before = get_picker_cache_key(char, 1, '', 'true', '[]')
        char.save()
        char.refresh_from_db()
        self.assertNotEqual(before,
                            get_picker_cache_key(char, 1, '', 'true', '[]'))

    def test_a_long_search_term_still_makes_a_usable_key(self):
        from chardata.util import get_picker_cache_key
        key = get_picker_cache_key(7, 1, 'x' * 300, 'true', '[]')
        self.assertLess(len(key), 250)
        self.assertNotIn(' ', key)
        self.assertNotEqual(key, get_picker_cache_key(7, 1, 'y' * 300, 'true',
                                                      '[]'))


class PinnedDependenciesAgreeTests(SimpleTestCase):
    """boto3 requires the botocore of its own version, so a bump that lifts one
    and not the other stops the Docker build before the image is even built.
    It happened on the 14/08 deploy: boto3 1.43.61 with botocore 1.43.51."""

    FILES = ('requirements.txt', 'requirements-docker.txt',
             'requirements_aws.txt', 'requirements_win.txt')
    PIN = re.compile(r'^([A-Za-z0-9._-]+)==([^\s#]+)', re.M)

    def test_boto3_and_botocore_are_pinned_together(self):
        repo_root = os.path.dirname(
            os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
        checked = 0
        for name in self.FILES:
            path = os.path.join(repo_root, name)
            if not os.path.exists(path):
                continue
            with open(path, encoding='utf-8') as fh:
                pins = dict(self.PIN.findall(fh.read()))
            if 'boto3' not in pins or 'botocore' not in pins:
                continue
            checked += 1
            with self.subTest(requirements=name):
                self.assertEqual(pins['boto3'], pins['botocore'],
                                 '%s pins boto3 %s with botocore %s'
                                 % (name, pins['boto3'], pins['botocore']))
        self.assertTrue(checked, 'no requirements file pins both packages')


class NoEmDashInCodeTests(SimpleTestCase):
    """No em or en dash in first-party sources, copy and comments alike."""

    DASH_RE = re.compile('[—–]')
    EXTENSIONS = ('.py', '.html', '.css', '.js')
    SKIP_DIRS = {'locale', 'staticfiles', 'migrations', '__pycache__', 'admin'}
    SKIP_FILES = {'tests.py', 'mousetrap.min.js', 'sha256.js',
                  'jquery-ui-touch-punch-min.js'}
    LINE_ALLOWLIST = ('og:title', 'block title')

    def test_no_em_dash_in_first_party_sources(self):
        chardata_dir = os.path.dirname(os.path.abspath(__file__))
        fashionsite_root = os.path.dirname(chardata_dir)
        offenders = []
        for dirpath, dirnames, filenames in os.walk(fashionsite_root):
            dirnames[:] = [d for d in dirnames if d not in self.SKIP_DIRS]
            for filename in filenames:
                if not filename.endswith(self.EXTENSIONS):
                    continue
                if filename in self.SKIP_FILES or '.min.' in filename:
                    continue
                path = os.path.join(dirpath, filename)
                with open(path, encoding='utf-8', errors='replace') as fh:
                    for lineno, line in enumerate(fh, 1):
                        if not self.DASH_RE.search(line):
                            continue
                        if any(allow in line for allow in self.LINE_ALLOWLIST):
                            continue
                        rel = os.path.relpath(path, fashionsite_root)
                        offenders.append('%s:%d: %s'
                                         % (rel, lineno, line.strip()[:60]))
        self.assertEqual(
            offenders, [],
            'em/en dash found in first-party sources (use ., :, , or '
            'parentheses): %s' % offenders)


class AnAmbiguousAnkamaIdNeverCollapsesAPageTests(SimpleTestCase):
    """One ankama id can cover several pages, so it cannot answer for them.

    Pets and mounts ship one row per stat variant under a single ankama id --
    'Bow Meow', 'Bow Meow (+80 Strength)', ... -- each a page of its own. The
    signature map is keyed on (type, id), so one variant chosen by read order
    used to answer for all of its siblings. Declaring a page a copy costs its
    indexing; missing a copy costs a little crawl budget. So an ambiguous id
    must resolve to 'not a copy', which is what dropping it achieves.
    """

    VERSIONS = ('dofus3', 'beta', 'dofus2', 'retro', 'touch')

    def _rows_per_key(self, version):
        import sqlite3
        from fashionistapulp.fashionista_config import get_items_db_path
        conn = sqlite3.connect(get_items_db_path(version))
        try:
            return dict(((at, aid), n) for at, aid, n in conn.execute(
                'SELECT ankama_type, ankama_id, COUNT(*) FROM items '
                'WHERE ankama_id IS NOT NULL AND COALESCE(removed, 0) = 0 '
                'GROUP BY ankama_type, ankama_id'))
        finally:
            conn.close()

    def test_no_id_with_several_rows_survives_in_the_signatures(self):
        from chardata.version_content import _cached_signatures
        for version in self.VERSIONS:
            signatures = _cached_signatures(version)
            if not signatures:
                continue
            partages = [key for key, n in self._rows_per_key(version).items()
                        if n > 1]
            restants = [key for key in partages if key in signatures]
            self.assertEqual(
                restants, [],
                '%s keeps %d ambiguous ids, e.g. %s'
                % (version, len(restants), restants[:3]))

    def test_a_shared_id_is_never_called_a_copy(self):
        from chardata.version_content import repeats_the_live_version
        for version in ('retro', 'touch'):
            partages = [key for key, n in self._rows_per_key(version).items()
                        if n > 1]
            if not partages:
                continue
            for ankama_type, ankama_id in partages[:20]:
                self.assertFalse(
                    repeats_the_live_version(version, ankama_type, ankama_id),
                    '%s %s/%s covers several pages and cannot be judged as one'
                    % (version, ankama_type, ankama_id))

    def test_an_unshared_id_is_still_judged_normally(self):
        """The guard must not switch the whole mechanism off."""
        from chardata.version_content import _cached_signatures
        for version in ('beta', 'dofus2'):
            uniques = [key for key, n in self._rows_per_key(version).items()
                       if n == 1]
            signatures = _cached_signatures(version)
            if not signatures or not uniques:
                continue
            gardes = [key for key in uniques if key in signatures]
            self.assertTrue(
                len(gardes) > len(uniques) * 0.9,
                '%s kept only %d of its %d unshared ids'
                % (version, len(gardes), len(uniques)))


class ActionEndpointsRefuseGetTests(TestCase):
    """An action endpoint must say no to GET rather than answer emptily.

    Search Console reported 683 Soft 404s. Crawlers reach these urls -- they
    are Disallow'd on the apex, but www served a permissive robots.txt -- ask
    for them with GET, and got 200 with a two-byte body. Google reads a 200
    carrying nothing as a Soft 404, keeps the url in its index of things to
    re-check, and comes back. A 405 is an answer it accepts and stops asking.

    Every one of these is called with $.post by the site's own JavaScript, so
    closing GET costs no reader anything. The list is explicit rather than
    derived from robots.txt: some disallowed paths legitimately answer GET,
    and a test that guesses would fail for the wrong reason.
    """

    #: Measured on production: each answered GET with 200 and a body of 2 to
    #: 339 bytes.
    POST_ONLY = ('/local_login/', '/check_username/', '/change_password/',
                 '/get_item_stats_compare/', '/getitemdetails/',
                 '/saveprojecttouser/', '/understandbuild/')

    #: Registered only when DEBUG, so production answers 404 and no crawler
    #: ever sees them. They are listed to keep that true: moving one out of the
    #: DEBUG block would publish an editor for the item catalogue.
    DEBUG_ONLY = ('/choose_item/', '/choose_set/', '/delete_item/',
                  '/delete_set/', '/update_item/', '/update_set/',
                  '/edit_item/', '/edit_set/', '/edit_item_search_item/',
                  '/edit_item_search_sets/')

    def test_get_is_refused(self):
        for path in self.POST_ONLY:
            self.assertEqual(self.client.get(path).status_code, 405, path)

    def test_the_catalogue_editors_stay_out_of_production(self):
        for path in self.DEBUG_ONLY:
            self.assertEqual(self.client.get(path).status_code, 404, path)

    def test_no_action_endpoint_answers_200_with_an_empty_body(self):
        """The exact shape Google files as a Soft 404."""
        for path in self.POST_ONLY:
            page = self.client.get(path)
            if page.status_code == 200:
                self.assertGreater(
                    len(page.content), 3000,
                    '%s answers 200 with %d bytes, which reads as a Soft 404'
                    % (path, len(page.content)))

    def test_the_version_prefixed_copies_refuse_it_too(self):
        """Each endpoint answers under every game version, and crawlers found
        the prefixed copies too (/touch/saveprojecttouser/ was reported)."""
        for prefix in ('/beta', '/dofus2', '/retro', '/touch'):
            for path in ('/saveprojecttouser/', '/getitemdetails/'):
                url = prefix + path
                self.assertEqual(self.client.get(url).status_code, 405, url)

    def test_post_still_reaches_the_view(self):
        """405 must come from the method check, not from the url dying: a POST
        has to get past it and be handled -- whatever the view then answers."""
        for path in self.POST_ONLY:
            self.assertNotEqual(self.client.post(path).status_code, 405, path)


class TheCatalogueEditorSurvivesAReferenceItCannotReadTests(TestCase):
    """A request without a usable reference used to be a 500 and an admin mail.

    Both endpoints read a "<id> <name>" string out of the POST and split it
    without looking. No field at all raised AttributeError, and a name with no
    space raised IndexError. The routes live behind DEBUG so production never
    served them, but every local run gets crawled and those 500s land in the
    error mailbox that is read every day.

    Called directly rather than through the client, because the urls are not
    registered while the tests run -- which is the point of the DEBUG_ONLY
    guard in ActionEndpointsRefuseGetTests.
    """

    def _asked(self, view, **fields):
        from django.test import RequestFactory
        from chardata import manage_items_view
        request = RequestFactory().post('/', fields)
        return json.loads(getattr(manage_items_view, view)(request).content)

    def _got(self, view):
        from django.test import RequestFactory
        from chardata import manage_items_view
        request = RequestFactory().get('/')
        return getattr(manage_items_view, view)(request).status_code

    def test_a_bare_get_is_refused_rather_than_answered(self):
        # choose_item already carried @require_POST and choose_set did not,
        # which is the whole reason a crawler reached the body at all.
        self.assertEqual(405, self._got('choose_set'))
        self.assertEqual(405, self._got('choose_item'))

    def test_a_set_asked_for_with_no_reference_answers_nothing(self):
        self.assertEqual({}, self._asked('choose_set'))

    def test_an_item_asked_for_with_no_reference_answers_nothing(self):
        self.assertEqual({}, self._asked('choose_item'))

    def test_a_one_word_reference_answers_nothing(self):
        # 'Gelano' has no space, so the old code indexed past the split.
        self.assertEqual({}, self._asked('choose_set', name='Gelano'))
        self.assertEqual({}, self._asked('choose_item', name='Gelano'))
        self.assertEqual({}, self._asked('choose_item', name='[DT]'))

    def test_an_id_no_item_carries_answers_nothing(self):
        # The id was looked up and the miss dereferenced straight away.
        self.assertEqual({}, self._asked('choose_item', id='999999999'))

    def test_a_real_set_is_still_found(self):
        from fashionistapulp.structure import get_structure
        wanted = sorted(get_structure().sets_dict.values(),
                        key=lambda item_set: item_set.id)[0]
        answer = self._asked('choose_set',
                             name='%d %s' % (wanted.id, wanted.name))
        self.assertEqual(wanted.name, answer['set']['name'])
        self.assertEqual(wanted.id, answer['set']['id'])

    def test_a_real_set_is_still_found_by_its_id_alone(self):
        from fashionistapulp.structure import get_structure
        wanted = sorted(get_structure().sets_dict.values(),
                        key=lambda item_set: item_set.id)[0]
        answer = self._asked('choose_set', id=str(wanted.id))
        self.assertEqual(wanted.name, answer['set']['name'])


class ArrivalSourceTests(SimpleTestCase):
    """Telling a visit from outside apart from a click inside the site.

    The whole point of the measurement: 77 % of this site's search clicks are
    people typing its own name, so the open question is who ever hears of it.
    Counting internal clicks as provenances would bury that answer under the
    site's own navigation.
    """

    def _request(self, path='/', referrer=None, host='dofusfashionista.gg', **params):
        from django.test import RequestFactory
        extra = {'HTTP_HOST': host}
        if referrer is not None:
            extra['HTTP_REFERER'] = referrer
        return RequestFactory().get(path, data=params, **extra)

    def _source(self, **kwargs):
        from chardata.middleware import arrival_source
        return arrival_source(self._request(**kwargs))

    def test_a_click_inside_the_site_is_not_a_provenance(self):
        """Django's default referrer policy is same-origin, so an internal
        click DOES carry a referrer -- which is what makes this separable."""
        for referrer in ('https://dofusfashionista.gg/encyclopedia/',
                         'https://www.dofusfashionista.gg/guides/',
                         'https://dofusfashionista.gg/'):
            self.assertIsNone(self._source(referrer=referrer), referrer)

    def test_no_referrer_at_all_is_a_direct_arrival(self):
        self.assertEqual(self._source(), ('direct', 'none', ''))

    def test_a_search_engine_is_recognised_as_such(self):
        for referrer, attendu in (
                ('https://www.google.com/', 'google'),
                ('https://google.fr/search?q=dofus', 'google'),
                ('https://www.bing.com/search?q=x', 'bing'),
                ('https://duckduckgo.com/', 'duckduckgo'),
                ('https://search.brave.com/', 'search')):
            source, medium, _ = self._source(referrer=referrer)
            self.assertEqual(medium, 'organic', referrer)
            self.assertEqual(source, attendu, referrer)

    def test_an_ai_assistant_gets_its_own_line(self):
        """They already send more visitors here than every social network
        together, so losing them among referrals would hide the one channel
        that grew on its own."""
        for referrer in ('https://chatgpt.com/', 'https://perplexity.ai/'):
            source, medium, _ = self._source(referrer=referrer)
            self.assertEqual(medium, 'assistant', referrer)
            self.assertIn(source, ('chatgpt.com', 'perplexity.ai'))

    def test_anything_else_is_a_referral(self):
        source, medium, _ = self._source(referrer='https://www.youtube.com/watch?v=x')
        self.assertEqual((source, medium), ('youtube.com', 'referral'))

    def test_utm_wins_over_the_referrer(self):
        """A link handed to a creator is the only way to tell apart two visits
        a browser reports identically."""
        got = self._source(referrer='https://www.youtube.com/', utm_source='torrente',
                           utm_medium='video', utm_campaign='sets-es')
        self.assertEqual(got, ('torrente', 'video', 'sets-es'))

    def test_utm_alone_still_names_a_medium(self):
        source, medium, campaign = self._source(utm_source='discord')
        self.assertEqual((source, medium, campaign), ('discord', 'utm', ''))

    def test_nothing_longer_than_its_column(self):
        """A referrer is sender-controlled: it must not be able to make the
        insert fail, which would lose the count for everyone that day."""
        got = self._source(utm_source='s' * 400, utm_medium='m' * 400,
                           utm_campaign='c' * 400)
        self.assertEqual([len(x) for x in got], [100, 40, 60])
        source, _medium, _campaign = self._source(
            referrer='https://%s.com/' % ('h' * 300))
        self.assertLessEqual(len(source), 100)

    def test_a_broken_referrer_never_raises(self):
        for referrer in ('', 'not a url', 'https://', '//', 'javascript:x',
                         'https://:@/', 'http://user@host:99/x'):
            try:
                self._source(referrer=referrer)
            except Exception as erreur:
                self.fail('referrer %r raised %r' % (referrer, erreur))


class ArrivalCountingTests(TestCase):
    """The counter itself: aggregated by day, and holding nothing personal."""

    #: The test client sends no user agent, and a caller without one is
    #: counted as a robot -- correctly, since every browser sends one. These
    #: tests are about readers, so they have to look like readers.
    NAVIGATEUR = ('Mozilla/5.0 (Windows NT 10.0; Win64; x64) '
                  'AppleWebKit/537.36 (KHTML, like Gecko) Chrome/126.0 Safari/537.36')

    def client_get(self, chemin, **extra):
        extra.setdefault('HTTP_USER_AGENT', self.NAVIGATEUR)
        return self.client.get(chemin, **extra)

    def test_an_arrival_is_counted_once_per_day_and_source(self):
        from chardata.models import VisitSource
        for _ in range(3):
            self.client_get('/', HTTP_REFERER='https://www.google.com/')
        rows = VisitSource.objects.filter(source='google')
        self.assertEqual(rows.count(), 1,
                         'one row per day and source, not one per visit')
        self.assertEqual(rows.first().count, 3)

    HOST = 'dofusfashionista.gg'

    def test_browsing_the_site_does_not_inflate_the_count(self):
        from django.db.models import Sum
        from chardata.models import VisitSource
        self.client_get('/', HTTP_HOST=self.HOST,
                        HTTP_REFERER='https://www.google.com/')
        for path in ('/encyclopedia/', '/guides/', '/'):
            self.client_get(path, HTTP_HOST=self.HOST,
                            HTTP_REFERER='https://dofusfashionista.gg/')
        self.assertEqual(
            VisitSource.objects.aggregate(n=Sum('count'))['n'], 1)

    def test_the_www_form_of_our_own_host_is_still_our_own_host(self):
        """Old links still point at www, which 301s to the apex. If the two
        spellings did not compare equal, every one of those readers would be
        filed as a referral from the site to itself."""
        from django.db.models import Sum
        from chardata.models import VisitSource
        self.client_get('/encyclopedia/', HTTP_HOST=self.HOST,
                        HTTP_REFERER='https://www.dofusfashionista.gg/')
        self.client_get('/encyclopedia/', HTTP_HOST='www.' + self.HOST,
                        HTTP_REFERER='https://dofusfashionista.gg/')
        self.assertIsNone(VisitSource.objects.aggregate(n=Sum('count'))['n'])

    def test_the_country_comes_from_cloudflare_when_it_is_there(self):
        from chardata.models import VisitSource
        self.client_get('/', HTTP_REFERER='https://www.google.com/',
                        HTTP_CF_IPCOUNTRY='co')
        self.assertEqual(VisitSource.objects.first().country, 'CO')

    def test_no_column_can_hold_an_address_or_an_identifier(self):
        """The rule that keeps this out of consent-banner territory: the table
        cannot describe a person even in principle."""
        from chardata.models import VisitSource
        champs = {f.name for f in VisitSource._meta.get_fields()}
        for interdit in ('ip', 'ip_address', 'address', 'user', 'session',
                         'visitor', 'user_agent', 'cookie', 'fingerprint'):
            self.assertNotIn(interdit, champs)

    def test_counting_never_breaks_the_page(self):
        """A statistic is worth less than a page that answers."""
        from unittest import mock
        with mock.patch('chardata.middleware.record_arrival',
                        side_effect=RuntimeError('boom')):
            self.assertEqual(self.client_get('/').status_code, 200)


class ProvenanceViewTests(TestCase):
    """The page that reads the measurement. Admin-only, like the rest."""

    URL = '/admin-tools/provenance/'

    def _admin(self):
        from django.contrib.auth.models import User
        user = User.objects.create_user('boss', 'boss@example.com', 'x')
        user.is_superuser = True
        user.is_staff = True
        user.save()
        return user

    def test_a_visitor_cannot_read_it(self):
        self.assertEqual(self.client.get(self.URL).status_code, 404)

    def test_a_signed_in_reader_cannot_read_it_either(self):
        from django.contrib.auth.models import User
        User.objects.create_user('reader', 'r@example.com', 'x')
        self.client.login(username='reader', password='x')
        self.assertEqual(self.client.get(self.URL).status_code, 404)

    def test_the_admin_reads_it(self):
        self.client.force_login(self._admin())
        self.assertEqual(self.client.get(self.URL).status_code, 200)

    def test_it_answers_before_any_data_exists(self):
        """The first person to open it will do so on an empty table."""
        self.client.force_login(self._admin())
        page = self.client.get(self.URL)
        self.assertEqual(page.status_code, 200)
        self.assertIn('Aucune', page.content.decode('utf-8'))

    def test_it_reports_what_was_counted(self):
        from chardata.models import VisitSource
        VisitSource.objects.create(day=timezone.localdate(), source='youtube.com',
                                   medium='referral', language='es',
                                   country='CO', count=7)
        self.client.force_login(self._admin())
        html = self.client.get(self.URL).content.decode('utf-8')
        self.assertIn('youtube.com', html)
        self.assertIn('7', html)

    def test_the_support_rate_is_the_number_it_exists_for(self):
        """Visits are already known; the share of readers willing to pay is
        not, and it is what decides whether courting creators is worth it."""
        from chardata.models import SupportClick, VisitSource
        today = timezone.localdate()
        VisitSource.objects.create(day=today, source='google', medium='organic',
                                   count=1000)
        SupportClick.objects.create(day=today, language='fr', count=5)
        self.client.force_login(self._admin())
        html = self.client.get(self.URL).content.decode('utf-8')
        self.assertIn('0.5', html)


class DonateRedirectTests(TestCase):
    """The donation link, counted on its way out.

    The Ko-fi button existed for a long time and taught the site nothing: a
    third-party widget drew it, so nobody could tell whether a single reader
    ever reached for it. Against a measured 16 page views a day and one donation
    received, that share is the number that decides whether any of this is worth
    more work.
    """

    URL = '/out/donate/'

    def _kofi(self):
        links = getattr(settings, 'SUPPORT_LINKS', []) or []
        return links[0]['url'] if links else None

    def test_it_sends_the_reader_to_the_donation_page(self):
        page = self.client.get(self.URL)
        self.assertEqual(page.status_code, 302)
        self.assertEqual(page['Location'], self._kofi())

    def test_it_counts_the_click(self):
        from chardata.models import SupportClick
        for _ in range(3):
            self.client.get(self.URL)
        self.assertEqual(SupportClick.objects.count(), 1, 'one row per day')
        self.assertEqual(SupportClick.objects.first().count, 3)

    def test_it_counts_the_language_the_reader_was_served(self):
        from chardata.models import SupportClick
        self.client.get('/es/encyclopedia/')
        self.client.get(self.URL, HTTP_ACCEPT_LANGUAGE='es')
        self.assertTrue(SupportClick.objects.exists())

    def test_a_visitor_cannot_choose_the_destination(self):
        """An open redirect is a link that looks like this site and lands
        anywhere. It is what phishing wants, and search engines punish it."""
        for tentative in ('?url=https://evil.example/',
                          '?to=https://evil.example/',
                          '?next=https://evil.example/',
                          '?redirect=//evil.example/'):
            page = self.client.get(self.URL + tentative)
            self.assertEqual(page.status_code, 302, tentative)
            self.assertEqual(page['Location'], self._kofi(),
                             'the query string moved the destination: %s' % tentative)

    def test_an_unknown_link_is_not_found(self):
        for index in ('7', '99', '0000000'):
            self.assertEqual(
                self.client.get('/out/donate/%s/' % index).status_code,
                404 if int(index) >= len(getattr(settings, 'SUPPORT_LINKS', []))
                else 302, index)

    def test_a_broken_counter_never_costs_a_donation(self):
        """A statistic is worth far less than the donation it would block."""
        from unittest import mock
        with mock.patch('chardata.models.SupportClick.objects') as faux:
            faux.filter.side_effect = RuntimeError('boom')
            page = self.client.get(self.URL)
        self.assertEqual(page.status_code, 302)
        self.assertEqual(page['Location'], self._kofi())

    def test_crawlers_are_told_to_stay_out(self):
        """A crawler following the link would count as a reader reaching for
        the button, which is the one thing the number must not include."""
        import urllib.robotparser as rp
        body = self.client.get('/robots.txt').content.decode('utf-8')
        parser = rp.RobotFileParser()
        parser.parse(body.splitlines())
        self.assertFalse(parser.can_fetch('Googlebot', self.URL))


class DonationButtonTests(TestCase):
    """What the page actually shows, and what it no longer loads."""

    def test_no_page_loads_the_third_party_widget_anymore(self):
        """It was fetched on every one of 68 000 monthly page views, and drew a
        button whose clicks nobody could see."""
        for path in ('/', '/encyclopedia/', '/guides/', '/support/'):
            html = self.client.get(path).content.decode('utf-8')
            self.assertNotIn('ko-fi.com/cdn', html, path)
            self.assertNotIn('kofiwidget', html, path)

    def test_the_button_is_still_there_and_goes_through_the_counter(self):
        html = self.client.get('/').content.decode('utf-8')
        self.assertIn('/out/donate/', html)

    def test_the_support_page_routes_its_links_too(self):
        html = self.client.get('/support/').content.decode('utf-8')
        self.assertIn('/out/donate/0/', html)
        for link in (getattr(settings, 'SUPPORT_LINKS', []) or []):
            self.assertNotIn('href="%s"' % link['url'], html,
                             'a raw donation link escapes the counter')


class PagesSayInSearchWhatTheyAreForTests(TestCase):
    """What a page calls itself in a result list decides whether it is opened.

    Measured in Search Console over 28 days: /setup/ ranks sixth on "dofus set
    builder", takes 2 143 impressions and gets 16 clicks. /loadprojects/ takes
    1 690 impressions and gets 3. Both announced themselves as "The Dofus
    Fashionista: Project Details" and "...: Load a Project", and both fell back
    to the same site-wide description, so neither said anything to somebody
    reading ten results.

    The site name goes last because Google truncates, and the half that gets
    cut has to be the half that is the same on every page.
    """

    GENERIQUE = 'Get Dofus sets created automatically'

    def _head(self, chemin, langue='en'):
        import re
        html = self.client.get(chemin, HTTP_ACCEPT_LANGUAGE=langue).content.decode('utf-8')
        titre = re.search(r'<title>([^<]*)</title>', html)
        # Le minifieur reordonne les attributs, donc on cherche les deux sens.
        descr = (re.search(r'name="description" content="([^"]*)"', html)
                 or re.search(r'content="([^"]*)" name="description"', html))
        return (titre.group(1) if titre else ''), (descr.group(1) if descr else '')

    def test_the_set_builder_names_itself_before_the_site(self):
        titre, _ = self._head('/setup/')
        self.assertTrue(titre.startswith('Dofus Set Builder'), titre)
        self.assertNotIn('Project Details', titre)

    def test_the_set_builder_has_a_description_of_its_own(self):
        _, descr = self._head('/setup/')
        self.assertNotIn(self.GENERIQUE, descr)
        self.assertIn('class', descr)

    def test_the_saved_sets_page_says_what_it_holds(self):
        titre, descr = self._head('/loadprojects/')
        self.assertTrue(titre.startswith('Your Saved Dofus Sets'), titre)
        self.assertNotIn('Load a Project', titre)
        self.assertNotIn(self.GENERIQUE, descr)

    def test_a_french_reader_reads_it_in_french(self):
        titre, descr = self._head('/setup/', 'fr')
        self.assertIn('stuff', titre.lower())
        self.assertIn('optimiseur', descr)

    def test_every_page_that_gets_impressions_leads_with_its_keyword(self):
        """Measured in Search Console: /sharedbuilds/ takes 716 impressions a
        month for five clicks, /smartbuild/ 185 for five. All three announced
        themselves as "The Dofus Fashionista: X", so the half Google truncates
        was the half that said what the page is.
        """
        for chemin, debut in (('/sharedbuilds/', 'Community Dofus Builds'),
                              ('/quickstart/', 'Build a Dofus Set in 3 Clicks'),
                              ('/smartbuild/', 'Dofus Build from a Sentence'),
                              ('/encyclopedia/', 'Dofus Item Encyclopedia')):
            titre, _ = self._head(chemin)
            self.assertTrue(titre.startswith(debut), '%s -> %r' % (chemin, titre))
            self.assertIn('Dofus Fashionista', titre, chemin)

    def test_the_encyclopedia_heading_stayed_short(self):
        """The keyword belongs in the title tag alone. The same string is the
        h1 and the breadcrumb on a dozen pages, and lengthening it there would
        have turned every crumb into "Dofus Item Encyclopedia > ...".
        """
        import re
        html = self.client.get('/encyclopedia/').content.decode('utf-8')
        h1 = re.search(r'<h1[^>]*>([^<]*)</h1>', html)
        self.assertIsNotNone(h1)
        self.assertEqual(h1.group(1).strip(), 'Encyclopedia')

    def test_the_site_name_is_still_there_and_still_last(self):
        """Dropping it entirely would cost the brand searches, which are 77 per
        cent of the clicks this site gets."""
        for chemin in ('/setup/', '/loadprojects/'):
            titre, _ = self._head(chemin)
            self.assertIn('Dofus Fashionista', titre, chemin)
            self.assertGreater(titre.index('Dofus Fashionista'), 5, chemin)


class SetAndResourcePagesAnswerTooTests(TestCase):
    """The same rule, on the rest of the encyclopedia.

    A set page said "all the items in this Dofus set and the panoply bonuses
    per number of pieces", a resource page said "find every item that uses this
    ingredient": both described the page and neither said anything about the
    thing. Together they are around 8 600 URLs.
    """

    SET = '/encyclopedia/set/256-henual-set/'
    RESOURCE = '/encyclopedia/resource/resources/32079-dream-reflection/'
    ANCIENNE_SET = 'all the items in this Dofus set'
    ANCIENNE_RES = 'Find every item that uses this ingredient'

    def _description(self, chemin):
        import re
        html = self.client.get(chemin).content.decode('utf-8')
        m = (re.search(r'name="description" content="([^"]*)"', html)
             or re.search(r'content="([^"]*)" name="description"', html))
        return m.group(1) if m else ''

    def test_a_set_says_how_many_pieces_and_at_what_level(self):
        descr = self._description(self.SET)
        self.assertNotIn(self.ANCIENNE_SET, descr)
        self.assertIn('items', descr)
        self.assertIn('level', descr)

    def test_a_set_says_what_wearing_it_all_gives(self):
        """The reason somebody searches a set name."""
        self.assertIn('pieces:', self._description(self.SET))

    def test_a_resource_says_how_many_recipes_use_it(self):
        descr = self._description(self.RESOURCE)
        self.assertNotIn(self.ANCIENNE_RES, descr)
        self.assertIn('recipes', descr)

    def test_none_of_them_outgrows_what_a_result_shows(self):
        from chardata.encyclopedia_view import DESCRIPTION_BUDGET
        for chemin in (self.SET, self.RESOURCE):
            self.assertLessEqual(len(self._description(chemin)),
                                 DESCRIPTION_BUDGET + 20, chemin)

    def test_a_set_with_nothing_to_say_falls_back(self):
        """An empty set would otherwise get an empty description, which is
        worse than the old promise."""
        from chardata.encyclopedia_view import _set_seo_description
        self.assertEqual(_set_seo_description('X', [], []), '')

    def test_a_resource_used_nowhere_falls_back(self):
        from chardata.encyclopedia_view import _resource_seo_description
        self.assertEqual(_resource_seo_description('X', 'Resource', []), '')


class ItemPagesAnswerInTheSearchResultTests(TestCase):
    """The snippet has to answer, not announce.

    Measured over 28 days: item pages rank fifth to eighth on their own item
    name and take zero clicks. "belteen" 278 impressions position 6.8, zero
    clicks; "putchup" 67, zero; "strichhat" 37, zero. Above them the Fandom
    wiki answers in its own snippet, "Belteen is a Belt and part of the Whale
    Set. Crafted by a Shoemaker...", while this site said "Belteen: Dofus
    stats, effects, equip conditions and craft recipe", which describes the
    kind of page and not the item.

    The last sentence is the one no wiki and no official encyclopedia can
    write, because none of them knows what people actually wear.
    """

    BELTEEN = '/encyclopedia/item/equipment/15699-belteen/'
    ANCIENNE = 'Dofus stats, effects, equip conditions and craft recipe'

    def _description(self, chemin, langue='en'):
        import re
        html = self.client.get(chemin, HTTP_ACCEPT_LANGUAGE=langue).content.decode('utf-8')
        m = (re.search(r'name="description" content="([^"]*)"', html)
             or re.search(r'content="([^"]*)" name="description"', html))
        return m.group(1) if m else ''

    def test_it_says_what_the_item_is(self):
        descr = self._description(self.BELTEEN)
        self.assertIn('Belteen', descr)
        self.assertIn('Belt', descr)
        self.assertIn('200', descr)
        self.assertNotIn(self.ANCIENNE, descr)

    def test_it_names_the_set_the_item_belongs_to(self):
        """The wiki's snippet leads with it, and it is what a reader searching
        an item name is usually after."""
        self.assertIn('Whale Set', self._description(self.BELTEEN))

    def test_it_carries_the_stats_that_make_someone_pick_an_item(self):
        descr = self._description(self.BELTEEN)
        self.assertIn('Vitality', descr)

    def test_it_says_the_one_thing_no_wiki_can_say(self):
        from chardata.models import ItemPopularity
        ItemPopularity.objects.create(ankama_id=15699, game_version='dofus3',
                                      builds=1400, eligible=10000)
        self.assertIn('14.0 %', self._description(self.BELTEEN))

    def test_without_the_count_it_still_answers(self):
        """The popularity index is rebuilt periodically and may be empty. The
        description must not depend on it."""
        descr = self._description(self.BELTEEN)
        self.assertNotIn('Worn in', descr)
        self.assertIn('Belt', descr)

    def test_it_falls_back_rather_than_going_blank(self):
        """An item with no type or level would otherwise get an empty
        description, which is worse than the old promise."""
        from chardata.encyclopedia_view import _item_seo_description
        vide = _item_seo_description({'name': 'X'}, None, [], None)
        self.assertEqual(vide, '')

    def test_a_french_reader_reads_it_in_french(self):
        """L'encyclopedie prend sa langue de l'URL et non de l'en-tete, chaque
        langue ayant son propre slug traduit. La fonction est donc eprouvee
        sous bascule, ce qui teste la traduction sans dependre du slug."""
        from django.utils import translation
        from chardata.encyclopedia_view import _item_seo_description
        objet = {'name': 'Belteen', 'type_name': 'Ceinture', 'level': 200}
        with translation.override('fr'):
            descr = _item_seo_description(
                objet, 'Panoplie de la Baleine',
                [{'name': 'Vitalité', 'value': 350}],
                {'builds': 1400, 'share': '14.0 %'})
        self.assertIn('niveau 200', descr)
        self.assertIn('Panoplie de la Baleine', descr)
        self.assertIn("qui peuvent l'équiper", descr)


class TheMostWornGearPageTests(TestCase):
    """The one page no wiki and no official encyclopedia can write.

    They publish the same numbers from the same game files; none of them sees
    what people put on. This site has 161 476 calculated builds and showed
    nothing of what they say. Its real external links number about 227, of
    which 216 come from Reddit: a page worth citing is the only lever that
    moves a ranking, and this is the only thing the site has that nobody else
    can copy.
    """

    CHEMIN = '/encyclopedia/most-used/'
    NAVIGATEUR = 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) Chrome/126.0'

    def _rangs(self, ankama_id=26066, builds=1400, eligible=10000):
        from chardata.models import ItemPopularity
        return ItemPopularity.objects.create(
            ankama_id=ankama_id, game_version='dofus3',
            builds=builds, eligible=eligible)

    def _page(self):
        reponse = self.client.get(self.CHEMIN, HTTP_USER_AGENT=self.NAVIGATEUR)
        self.assertEqual(reponse.status_code, 200)
        return reponse.content.decode('utf-8')

    def test_it_names_the_gear_and_its_share(self):
        self._rangs()
        page = self._page()
        self.assertIn('14.0 %', page)
        self.assertIn('/encyclopedia/item/', page)

    def test_it_prints_the_method_rather_than_the_number_alone(self):
        """A percentage whose denominator is hidden is one nobody can argue
        with, which is the opposite of what this page is for."""
        self._rangs()
        page = self._page()
        self.assertIn('could equip it', page)
        # Le denominateur, avec son separateur : c'est le meme controle qu'a
        # l'origine, sur la forme lisible que la page affiche depuis.
        self.assertIn('10 000', page)

    def test_it_says_nothing_about_who_built_them(self):
        self._rangs()
        self.assertIn('Nothing about who built them', self._page())

    def test_an_item_with_no_publishable_share_is_left_out(self):
        """Under thirty wearers the share is noise, and a leaderboard of noise
        is worse than a short one."""
        self._rangs(builds=3, eligible=10000)
        page = self._page()
        self.assertNotIn('most-used-item', page)

    def test_an_empty_index_says_so_rather_than_showing_a_blank_board(self):
        page = self._page()
        self.assertIn('have not been built yet', page)
        self.assertNotIn('most-used-item', page)

    def test_the_page_is_in_the_sitemap(self):
        """A page nobody links to and nobody submits is a page nobody reads."""
        # Le plan ne l'annonce que si l'index existe : sans cette ligne le test
        # affirmerait le contraire de tests_sitemap_most_used.
        self._rangs()
        plan = self.client.get('/sitemap-pages.xml').content.decode('utf-8')
        self.assertIn('/encyclopedia/most-used/', plan)

    def test_it_invites_the_reader_to_the_tool(self):
        self._rangs()
        page = self._page()
        self.assertIn('Build a set of your own', page)
        self.assertIn('/setup/', page)

    def test_it_leads_with_the_figure_worth_quoting(self):
        """A statistics page nobody remembers is a page nobody links to.

        The strongest share sits above the method, and it is computed rather
        than written down: the day another item overtakes it, the sentence
        follows on its own.
        """
        self._rangs(ankama_id=26066, builds=1400, eligible=10000)
        self._rangs(ankama_id=694, builds=9000, eligible=10000)
        page = self._page()
        # Assertion d'abord, index ensuite : str.index leve une exception, et un
        # test qui casse par erreur plutot que par echec cache ce qu'il voulait
        # dire. Vu en le cassant expres : il tombait bien, mais en ERROR.
        self.assertIn('most-used-headline', page,
                      'the page leads with the method and no figure')
        self.assertLess(page.index('most-used-headline'),
                        page.index('most-used-method'),
                        'the figure must come before the method')
        # 9000 sur 10000, la part la plus forte des deux posees ci-dessus.
        entete = page[page.index('most-used-headline'):]
        self.assertIn('90.0 %', entete[:400])

    def test_the_build_count_is_readable(self):
        """141990 is a dump; 141 990 is a number.

        On a page whose whole worth is that its figures can be checked, an
        unseparated six-digit count reads as raw output.
        """
        self._rangs(builds=1400, eligible=141990)
        page = self._page()
        self.assertNotIn('141990', page)
        self.assertIn('141 990', page)

    def test_it_says_when_the_counts_were_rebuilt(self):
        from chardata.models import SiteSetting
        SiteSetting.objects.create(key='item_popularity_computed_at',
                                   value='2026-08-25')
        self._rangs()
        self.assertIn('2026-08-25', self._page())

    def test_with_no_counts_it_stops_claiming_to_have_counted(self):
        """The state production sits in between a deploy and the first index.

        The page used to say "counted over 0 builds calculated on this site"
        and then, two sentences later, that the counts had not been built yet.
        Both were printed together, and the first is the kind of sentence a
        reader remembers about a page whose whole worth is trustworthy
        figures.
        """
        page = self._page()
        self.assertIn('have not been built yet', page)
        self.assertNotIn('Counted over', page)
        self.assertNotIn('builds calculated on this site', page)
        # Et la balise que Google montrerait : elle annoncait "counted over 0
        # calculated builds", trouve en cassant ce test expres.
        self.assertNotIn('counted over 0', page)
        self.assertNotIn('over {{ n }}', page)

    def test_it_invents_no_date_when_nothing_recorded_one(self):
        """The guard that matters more than the date itself.

        Dating the table with the moment a reader opens the page would be a
        made-up number on the one page that exists because its numbers can be
        checked. Absent is the honest answer.
        """
        self._rangs()
        page = self._page()
        self.assertNotIn('last rebuilt', page)
        self.assertNotIn('2026-', page)

    def test_each_language_says_where_the_others_are(self):
        """Five urls serve this page and Google must be told they are one page.

        The hub link resolves to /fr/encyclopedia/most-used/ for a French
        reader, so the prefixed urls get crawled whether or not they were
        submitted. Without hreflang between them, five near-identical pages
        compete with each other instead of pooling.
        """
        self._rangs()
        for prefixe in ('', '/fr', '/es', '/pt', '/de'):
            page = self.client.get(prefixe + self.CHEMIN,
                                   HTTP_USER_AGENT=self.NAVIGATEUR)
            self.assertEqual(page.status_code, 200, prefixe)
            texte = page.content.decode('utf-8')
            for langue in ('en', 'fr', 'es', 'pt', 'de'):
                attendu = 'hreflang="%s"' % langue
                self.assertIn(attendu, texte, '%s: %s' % (prefixe, attendu))
            # Chaque url est canonique d'elle-meme, sinon quatre des cinq
            # renvoient leur classement vers une page qui n'est pas la leur.
            # Le minifieur trie les attributs, donc on ne suppose pas l'ordre.
            import re as _re
            attendue = 'https://dofusfashionista.gg%s%s' % (prefixe,
                                                            self.CHEMIN)
            balise = _re.search(
                r'<link[^>]*rel="canonical"[^>]*>', texte)
            self.assertIsNotNone(balise, prefixe)
            self.assertIn('href="%s"' % attendue, balise.group(0), prefixe)

    def test_the_encyclopedia_hub_leads_to_it(self):
        """A page nothing links to is a page a crawler barely visits.

        It shipped in the sitemap with zero inbound links, which submits an
        address without giving any reason to walk to it. The hub is where a
        reader already browsing items would look for it.
        """
        carrefour = self.client.get(
            '/encyclopedia/', HTTP_USER_AGENT=self.NAVIGATEUR)
        self.assertEqual(carrefour.status_code, 200)
        self.assertIn(self.CHEMIN, carrefour.content.decode('utf-8'))

    def test_the_other_game_versions_do_not_get_an_empty_copy(self):
        """Beta, Retro, Touch and Dofus 2 have 25, 17, 10 and 1 build indexed.

        Not one share passes the wearer threshold, so a route per version
        would publish four near-identical pages saying they have nothing to
        show. The hub link is guarded for the same reason, so nothing on the
        site points at an address that answers 404.
        """
        for prefixe in ('/beta', '/dofus2', '/retro', '/touch'):
            reponse = self.client.get(prefixe + self.CHEMIN,
                                      HTTP_USER_AGENT=self.NAVIGATEUR)
            self.assertEqual(reponse.status_code, 404, prefixe)
            carrefour = self.client.get(prefixe + '/encyclopedia/',
                                        HTTP_USER_AGENT=self.NAVIGATEUR)
            self.assertNotIn(self.CHEMIN,
                             carrefour.content.decode('utf-8'), prefixe)


class ItemPopularityNeverPrintsSomethingFalseTests(TestCase):
    """A percentage published on 3 436 pages has to be defensible.

    The first version guarded the denominator and let the numerator through:
    1 219 of them read "worn in 70 builds, 0.0 % of those that could equip it",
    a sentence whose two halves contradict each other. The count is always
    true, so it is what remains when the share is dropped.
    """

    def _pop(self, builds, eligible):
        from chardata.models import ItemPopularity
        return ItemPopularity(ankama_id=1, game_version='dofus3',
                              builds=builds, eligible=eligible)

    def test_a_share_that_rounds_to_zero_is_not_printed(self):
        self.assertIsNone(self._pop(70, 141969).share)

    def test_too_few_wearers_is_not_a_share(self):
        self.assertIsNone(self._pop(5, 10000).share)

    def test_an_empty_denominator_is_not_a_share(self):
        self.assertIsNone(self._pop(40, 0).share)

    def test_a_real_share_is_printed(self):
        part = self._pop(1400, 10000).share
        self.assertIsNotNone(part)
        self.assertAlmostEqual(part, 14.0, places=6)

    def test_the_page_falls_back_to_the_count_alone(self):
        """Dropping the share must not drop the sentence: the count is the
        part that was never in doubt."""
        from chardata.encyclopedia_view import _get_popularity
        from chardata.models import ItemPopularity
        ItemPopularity.objects.create(ankama_id=26066, game_version='dofus3',
                                      builds=70, eligible=141969)
        vu = _get_popularity(26066, 'dofus3')
        self.assertEqual(vu['builds'], 70)
        self.assertIsNone(vu['share'])

    def test_one_build_is_not_written_as_several(self):
        """365 items are worn in exactly one build, 169 of them on dofus3.

        The sentence was a single string with the number substituted in, so
        every one of those pages read "Worn in 1 builds". Translated, so the
        same fault stood in the five languages -- about 1 825 pages of a page
        family whose whole worth is that its numbers can be checked.
        """
        from django.utils import translation
        from django.utils.translation import ngettext

        singulier = 'Worn in %(n)s build.'
        pluriel = 'Worn in %(n)s builds.'
        for langue in ('en', 'fr', 'es', 'pt', 'de'):
            with self.subTest(langue=langue), translation.override(langue):
                un = ngettext(singulier, pluriel, 1) % {'n': 1}
                deux = ngettext(singulier, pluriel, 2) % {'n': 2}
                self.assertNotEqual(
                    un, deux,
                    '%s renders one and two the same way: %r' % (langue, un))
                # Un catalogue sans regle de pluriel rendrait la forme plurielle
                # pour n=1, ce qui est exactement la faute d'origine.
                self.assertNotIn(
                    'builds', un.split('%s' % 1)[-1],
                    '%s still says "builds" for a single one: %r'
                    % (langue, un))
                # Et sans les deux formes au catalogue, ngettext retombe sur la
                # source anglaise : les assertions ci-dessus passeraient toutes
                # les deux sur une page francaise affichant de l'anglais.
                if langue != 'en':
                    self.assertNotIn(
                        'Worn in', un,
                        '%s fell back to the English source, so the catalogue '
                        'lost its plural forms: %r' % (langue, un))

    def test_the_page_says_one_build_in_the_singular(self):
        """The template has to ask for the plural form, not just the catalogue
        have one: a blocktrans without a count block never calls ngettext."""
        import re

        from chardata.models import ItemPopularity
        ItemPopularity.objects.create(ankama_id=26066, game_version='dofus3',
                                      builds=1, eligible=141969)
        rendu = self.client.get(
            '/encyclopedia/item/equipment/26066-nightmare-dofus/',
            HTTP_ACCEPT_LANGUAGE='en')
        self.assertEqual(rendu.status_code, 200)
        html = rendu.content.decode('utf-8', 'replace')
        bloc = re.search(r'class="encyclopedia-popularity">(.*?)</p>',
                         html, re.S)
        self.assertIsNotNone(bloc, 'the page prints no popularity at all')
        texte = re.sub(r'\s+', ' ', re.sub(r'<[^>]+>', '', bloc.group(1)))
        self.assertIn('1 build', texte)
        self.assertNotIn('1 builds', texte)

    def test_a_partial_pass_leaves_the_counts_alone(self):
        """On the shared builds only, a level 200 item compares against 625
        builds instead of 48 522. That share is still above the threshold, so
        it would print a credible number computed on one percent of the data.
        """
        from io import StringIO
        from django.core.management import call_command
        from chardata.models import ItemPopularity
        ItemPopularity.objects.create(ankama_id=26066, game_version='dofus3',
                                      builds=1400, eligible=10000)
        sortie = StringIO()
        call_command('reindex_builds_by_item', shared_only=True, stdout=sortie)
        garde = ItemPopularity.objects.filter(ankama_id=26066).first()
        self.assertIsNotNone(garde, 'the partial pass wiped the counts')
        self.assertEqual(garde.builds, 1400)
        self.assertIn('the usage counts were left untouched', sortie.getvalue())
        self.assertNotIn('counted items', sortie.getvalue())

    def test_a_full_pass_does_rebuild_them(self):
        from io import StringIO
        from django.core.management import call_command
        from chardata.models import ItemPopularity
        ItemPopularity.objects.create(ankama_id=26066, game_version='dofus3',
                                      builds=1400, eligible=10000)
        call_command('reindex_builds_by_item', stdout=StringIO())
        self.assertIsNone(ItemPopularity.objects.filter(ankama_id=26066).first())


class SimilarItemsAnswerTheQuestionAskedTests(TestCase):
    """What else could go in this slot, for this build.

    Sorting by level alone answered the wrong question. The Gelano is a level
    60 ring whose whole point is the AP it carries, and the page offered
    twenty-five rings of the same level, not one of which carried any: six
    rings in the entire game give AP, and the nearest sits twenty levels away.

    So a rare stat filters rather than scores, and the level window is dropped
    for it. Everything else stays within ten levels, with similarity falling
    off across them rather than stopping at the edge.
    """

    @classmethod
    def setUpClass(cls):
        super().setUpClass()
        from fashionistapulp.structure import get_structure
        cls.structure = get_structure('dofus3')

    GELANO = 2469          # anneau, 1 PA, niveau 60
    DOFUS_CAUCHEMAR = 26066  # niveau 180, aucune stat rare

    def _similar(self, ankama_id):
        from chardata.encyclopedia_view import _get_similar_items
        item = self.structure.get_item_by_ankama_id(ankama_id)
        self.assertIsNotNone(item)
        return item, _get_similar_items(self.structure, 'en', 'dofus3', item)

    def _rare(self, ankama_id):
        from chardata.encyclopedia_view import RARE_STATS, _stat_ids
        return _stat_ids(self.structure.get_item_by_ankama_id(ankama_id)) & set(RARE_STATS)

    def test_a_ring_with_ap_is_only_compared_to_rings_with_ap(self):
        from chardata.encyclopedia_view import _stat_ids
        rare = self._rare(self.GELANO)
        self.assertTrue(rare, 'this test needs an item carrying a rare stat')
        _item, voisins = self._similar(self.GELANO)
        self.assertTrue(voisins, 'the six AP rings should not all be hidden')
        for v in voisins:
            autre = next(i for i in self.structure.items_dict_ankama.values()
                         if i.name == v['name'])
            self.assertTrue(rare <= _stat_ids(autre),
                            '%s carries no %s' % (v['name'], rare))

    def test_a_rare_stat_outranks_the_level_window(self):
        """The nearest AP ring is twenty levels away. A window would have
        hidden every one of them."""
        item, voisins = self._similar(self.GELANO)
        ecarts = [abs((v['level'] or 0) - (item.level or 0)) for v in voisins]
        self.assertTrue(any(e > 10 for e in ecarts),
                        'the window was applied to a rare stat: %s' % ecarts)

    def test_an_ordinary_item_stays_within_ten_levels(self):
        item, voisins = self._similar(self.DOFUS_CAUCHEMAR)
        self.assertFalse(self._rare(self.DOFUS_CAUCHEMAR))
        self.assertTrue(voisins)
        for v in voisins:
            self.assertLessEqual(abs((v['level'] or 0) - (item.level or 0)), 10,
                                 v['name'])

    def test_the_item_never_suggests_itself(self):
        item, voisins = self._similar(self.GELANO)
        self.assertNotIn(item.name, [v['name'] for v in voisins])

    def test_showing_nothing_is_allowed(self):
        """Fewer results, or none, is the honest answer when nothing is alike.
        The old rule always filled the list, which is how it filled it wrong."""
        from chardata.encyclopedia_view import _get_similar_items
        for item in list(self.structure.items_dict_ankama.values())[:60]:
            voisins = _get_similar_items(self.structure, 'en', 'dofus3', item)
            self.assertIsInstance(voisins, list)


class BuildingASetAroundAnItemTests(TestCase):
    """The button said "Create a project" and opened an empty one.

    A reader on the page of an item wants a set with that item in it, and the
    two clicks between the two were the whole distance between an encyclopedia
    visit and a use of the tool.
    """

    GELANO = 2469

    def setUp(self):
        # Un anonyme ne peut pas creer de projet, donc un test anonyme ne
        # teste que la porte fermee.
        from django.contrib.auth.models import User
        self.client.force_login(
            User.objects.create_user('batisseur', 'b@example.com', 'x'))

    def test_the_encyclopedia_button_carries_the_item(self):
        from unittest import mock
        SANS_PUB = {'enabled': False, 'client': '', 'slots': {}, 'auto': False}
        with mock.patch('chardata.context_processors.ad_config',
                        return_value=dict(SANS_PUB)):
            page = self.client.get(
                '/encyclopedia/item/equipment/26066-nightmare-dofus/',
                HTTP_USER_AGENT='Mozilla/5.0').content.decode('utf-8')
        self.assertIn('/setup/?item=26066', page)

    def test_an_invented_item_is_refused_rather_than_carried(self):
        """It arrives in a query string and decides what gets locked onto a
        character."""
        for invente in ('999999', 'abc', '../etc', ''):
            page = self.client.get('/setup/?item=%s' % invente).content.decode('utf-8')
            self.assertNotIn('name="lock_item"', page, invente)

    def test_a_real_item_reaches_the_form(self):
        page = self.client.get('/setup/?item=%d' % self.GELANO).content.decode('utf-8')
        # Le minifieur reordonne les attributs, donc on ne suppose pas l'ordre.
        self.assertIn('name="lock_item"', page)
        self.assertIn('value="%d"' % self.GELANO, page)

    def test_creating_the_project_locks_the_item_on_the_character(self):
        from chardata.lock_forbid import get_inclusions_dict
        from chardata.models import Char
        reponse = self.client.post('/createproject/', {
            'project': 'Autour du Gelano', 'charname': 'star',
            'level': '200', 'class': 'Iop', 'byhand': '1',
            'lock_item': str(self.GELANO)})
        self.assertIn(reponse.status_code, (302, 301), reponse.status_code)
        char = Char.objects.order_by('-id').first()
        self.assertIsNotNone(char)
        portes = [v for v in get_inclusions_dict(char).values() if v != '']
        self.assertTrue(portes, 'the item was not locked onto the character')

    def test_a_forged_item_in_the_form_never_reaches_the_character(self):
        from chardata.lock_forbid import get_inclusions_dict
        from chardata.models import Char
        self.client.post('/createproject/', {
            'project': 'Forge', 'charname': 'star', 'level': '200',
            'class': 'Iop', 'byhand': '1', 'lock_item': '999999'})
        char = Char.objects.order_by('-id').first()
        self.assertIsNotNone(char)
        self.assertEqual([v for v in get_inclusions_dict(char).values() if v != ''], [])


class EncyclopediaNamesTheBuildsThatWearAnItemTests(TestCase):
    """The one thing this encyclopedia knows that no other one does.

    Ankama, DofusDB and the wikis publish the same numbers, taken from the same
    game files. None of them knows what people actually put on. This site does,
    from 3 361 shared builds, and never showed it -- while promising it in the
    meta description of every item page since the encyclopedia existed.

    The index is derived data, rebuilt from the builds, so these tests build it
    the way the command does rather than trusting a table somebody filled.
    """

    NAVIGATEUR = ('Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 '
                  '(KHTML, like Gecko) Chrome/126.0 Safari/537.36')
    SANS_PUB = {'enabled': False, 'client': '', 'slots': {}, 'auto': False}
    OBJET = '/encyclopedia/item/equipment/26066-nightmare-dofus/'
    ANKAMA_OBJET = 26066

    def _build(self, alias, vues=0, partage=True, supprime=False):
        import pickle as _pickle
        from django.contrib.auth.models import User
        from chardata.models import Char
        from fashionistapulp.modelresult import ModelResultMinimal
        entree = {'options': {}, 'origin': 'generated', 'char_level': 200,
                  'base_stats_by_attr': {}, 'locked_equips': {}}
        return Char.objects.create(
            name=alias, char_name=alias, char_class='Iop',
            char_build='build', level=200,
            minimum_stats=b'', minimum_crits=b'', stats_weight=b'',
            options=b'', inclusions=b'', exclusions=b'',
            minimal_solution=_pickle.dumps(ModelResultMinimal({}, entree, {})),
            owner=User.objects.create_user(alias, '%s@example.com' % alias, 'x'),
            link_shared=partage, deleted=supprime, view_count=vues,
            game_version='dofus3')

    def _index(self, build):
        from chardata.models import ItemInSharedBuild
        return ItemInSharedBuild.objects.create(
            ankama_id=self.ANKAMA_OBJET, game_version='dofus3', char=build)

    def _page(self, chemin=None):
        from unittest import mock
        with mock.patch('chardata.context_processors.ad_config',
                        return_value=dict(self.SANS_PUB)):
            reponse = self.client.get(chemin or self.OBJET,
                                      HTTP_USER_AGENT=self.NAVIGATEUR)
        self.assertEqual(reponse.status_code, 200)
        return reponse.content.decode('utf-8')

    def test_the_page_names_a_build_that_wears_the_item(self):
        self._index(self._build('porteur'))
        page = self._page()
        self.assertIn('porteur', page)
        self.assertIn('Builds wearing this item', page)

    def test_a_page_with_no_such_build_shows_no_empty_heading(self):
        """An empty section is worse than none: it tells the reader the site
        has nothing, on a page whose whole point is that it has something."""
        page = self._page()
        self.assertNotIn('Builds wearing this item', page)

    def test_a_build_that_stopped_being_shared_is_not_named(self):
        """The index is rebuilt periodically, so it always lags the builds.
        The page has to check, not trust it."""
        self._index(self._build('retire', partage=False))
        self.assertNotIn('retire', self._page())

    def test_a_deleted_build_is_not_named(self):
        self._index(self._build('efface', supprime=True))
        self.assertNotIn('efface', self._page())

    def test_the_most_read_builds_come_first(self):
        for alias, vues in (('discret', 1), ('populaire', 900), ('moyen', 50)):
            self._index(self._build(alias, vues=vues))
        page = self._page()
        self.assertLess(page.index('populaire'), page.index('moyen'))
        self.assertLess(page.index('moyen'), page.index('discret'))

    def test_the_reader_is_told_in_their_own_language(self):
        self._index(self._build('porteur'))
        self.assertIn('Builds qui portent cet objet', self._page(
            '/encyclopedia/item/equipment/26066-dofus-du-cauchemar/'))

    def test_rebuilding_the_index_replaces_it_rather_than_adding_to_it(self):
        """Derived data. A rebuild that appended would keep naming builds that
        stopped wearing the item, and nobody would ever see the drift."""
        from io import StringIO
        from django.core.management import call_command
        from chardata.models import ItemInSharedBuild
        self._index(self._build('perime'))
        self.assertEqual(ItemInSharedBuild.objects.count(), 1)
        sortie = StringIO()
        call_command('reindex_builds_by_item', stdout=sortie)
        self.assertEqual(ItemInSharedBuild.objects.count(), 0,
                         'the stale row survived the rebuild')
        self.assertIn('builds read', sortie.getvalue())

    def test_the_rebuild_says_how_many_builds_it_could_not_read(self):
        """A rebuild that silently indexed half the site would leave item pages
        looking as though nobody wears the item."""
        from io import StringIO
        from django.core.management import call_command
        sortie = StringIO()
        call_command('reindex_builds_by_item', stdout=sortie)
        self.assertIn('unreadable', sortie.getvalue())

    def test_the_block_comes_before_the_invitation_to_the_tool(self):
        """Content first, then the ask. The other way round asks before it has
        given anything."""
        self._index(self._build('porteur'))
        page = self._page()
        self.assertLess(page.index('Builds wearing this item'),
                        page.index('encyclopedia-cta'))


class EncyclopediaPagesInviteTheReaderToTheToolTests(TestCase):
    """The encyclopedia is nearly every URL the site has, and it never said
    what the site is for.

    A reader arriving from a search engine on an item page found the optimizer
    only in the navigation menu. The guides carry two invitations inside their
    own text; the 152 000 encyclopedia pages carried none, so the traffic that
    does arrive learns nothing about the thing the site does best.

    The labels already existed and were already translated, so this adds one
    sentence and no new obligation to the catalogues.
    """

    NAVIGATEUR = ('Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 '
                  '(KHTML, like Gecko) Chrome/126.0 Safari/537.36')
    SANS_PUB = {'enabled': False, 'client': '', 'slots': {}, 'auto': False}
    OBJET = '/encyclopedia/item/equipment/26066-nightmare-dofus/'

    def _page(self, chemin=None):
        from unittest import mock
        with mock.patch('chardata.context_processors.ad_config',
                        return_value=dict(self.SANS_PUB)):
            reponse = self.client.get(chemin or self.OBJET,
                                      HTTP_USER_AGENT=self.NAVIGATEUR)
        self.assertEqual(reponse.status_code, 200, chemin or self.OBJET)
        return reponse.content.decode('utf-8')

    def test_an_item_page_points_at_the_optimizer(self):
        page = self._page()
        self.assertIn('encyclopedia-cta', page)
        self.assertIn('Looking for a set built around', page)
        self.assertIn('/setup/', page)
        self.assertIn('/quickstart/', page)

    def test_the_invitation_sits_after_the_item_it_talks_about(self):
        """Asked before the reader has seen the stats, it is an interruption."""
        page = self._page()
        self.assertGreater(page.index('encyclopedia-cta'),
                           page.index('encyclopedia-section'))

    def test_it_keeps_the_reader_in_the_game_version_they_were_reading(self):
        """A reader on a beta page sent to the live optimizer would silently
        lose the version they came for."""
        page = self._page('/beta' + self.OBJET)
        debut = page.index('encyclopedia-cta')
        bloc = page[debut:debut + 700]
        self.assertIn('/beta/setup/', bloc)
        self.assertIn('/beta/quickstart/', bloc)

    def test_the_reader_is_invited_in_their_own_language(self):
        """The encyclopedia takes its language from the URL, not from a header:
        each language has its own translated slug."""
        for chemin, attendu in (
                ('/encyclopedia/item/equipment/26066-dofus-du-cauchemar/',
                 'Vous cherchez un'),
                ('/encyclopedia/item/equipment/26066-dofus-des-alptraums/',
                 'Suchen Sie ein Set')):
            self.assertIn(attendu, self._page(chemin), chemin)

    def test_the_invitation_is_a_link_and_not_a_form(self):
        """A crawler follows an <a href>. The language selector is a POST form
        and is invisible to one, which is the mistake not to repeat here."""
        page = self._page()
        debut = page.index('encyclopedia-cta')
        bloc = page[debut:debut + 700]
        self.assertIn('<a ', bloc)
        self.assertNotIn('<form', bloc)


class ImportingASetFromAnkamaIdsTests(TestCase):
    """Bringing a set in from somewhere else, without trusting names.

    The item table carries Ankama's own id on every item, so an import joins
    on an integer. Names are translated, repeated across versions and edited
    between patches: matching on them is how an importer quietly puts the
    wrong ring on someone.

    The other half of the contract is that nothing disappears quietly. An
    import that reports success while having thrown away three items is worse
    than one that fails, so every id that does not land comes back with its
    reason.
    """

    @classmethod
    def setUpClass(cls):
        super().setUpClass()
        from fashionistapulp.structure import Structure
        cls.structure = Structure()

    # Un chapeau, deux anneaux distincts, et un identifiant qui n'existe pas.
    CHAPEAU = 8248
    ANNEAU_A = 17998
    ANNEAU_B = 2469
    INEXISTANT = 999999

    def _plan(self, ids):
        from chardata.build_import import plan_ankama_ids
        return plan_ankama_ids(self.structure, ids)

    def test_each_item_lands_on_the_slot_its_type_calls_for(self):
        places, rejetes = self._plan([self.CHAPEAU, self.ANNEAU_A])
        self.assertEqual([slot for slot, _ in places], ['hat', 'ring1'])
        self.assertEqual(rejetes, [])

    def test_two_rings_fill_both_hands_in_order(self):
        places, _ = self._plan([self.ANNEAU_A, self.ANNEAU_B])
        self.assertEqual([slot for slot, _ in places], ['ring1', 'ring2'])

    def test_a_ring_too_many_is_reported_and_not_dropped(self):
        """Only two hands. A third ring is a set the game does not allow, and
        saying so beats keeping an arbitrary two."""
        from chardata.build_import import NO_FREE_SLOT
        troisieme = next(
            i for i in (768, 849, 850, 851, 852)
            if self.structure.get_item_by_ankama_id(i) is not None)
        places, rejetes = self._plan(
            [self.ANNEAU_A, self.ANNEAU_B, troisieme])
        self.assertEqual(len(places), 2)
        self.assertEqual(rejetes, [(troisieme, NO_FREE_SLOT)])

    def test_an_id_the_catalogue_does_not_know_comes_back_named(self):
        from chardata.build_import import UNKNOWN_ITEM
        places, rejetes = self._plan([self.CHAPEAU, self.INEXISTANT])
        self.assertEqual(len(places), 1)
        self.assertEqual(rejetes, [(self.INEXISTANT, UNKNOWN_ITEM)])

    def test_nothing_that_was_handed_in_ever_vanishes(self):
        """The invariant that matters: every id given comes back either placed
        or rejected. Never neither."""
        from chardata.build_import import ALREADY_PLACED
        donnes = [self.CHAPEAU, self.ANNEAU_A, self.INEXISTANT,
                  self.CHAPEAU, 'pas un nombre', None]
        places, rejetes = self._plan(donnes)
        rendus = len(places) + len(rejetes)
        self.assertEqual(rendus, len(donnes),
                         'places=%r rejetes=%r' % (places, rejetes))
        self.assertIn((self.CHAPEAU, ALREADY_PLACED), rejetes)

    def test_the_join_is_on_the_ankama_id_and_not_on_a_name(self):
        """A name would be translated, repeated and edited between patches."""
        item = self.structure.get_item_by_ankama_id(self.ANNEAU_B)
        self.assertIsNotNone(item)
        self.assertEqual(item.ankama_id, self.ANNEAU_B)

    # Un anneau qui n'appartient a aucune panoplie : le seul cas ou le jeu
    # accepte deux exemplaires du meme objet, et seulement dans les versions
    # dont le registre dit que les anneaux se doublent.
    ANNEAU_SANS_PANOPLIE = 103

    def test_the_same_setless_ring_fills_both_hands_where_the_game_allows_it(self):
        """The rule is the solver's own, not one invented here: model.py grants
        a second copy to a ring that belongs to no set."""
        places, rejetes = self._plan(
            [self.ANNEAU_SANS_PANOPLIE, self.ANNEAU_SANS_PANOPLIE])
        self.assertEqual([slot for slot, _ in places], ['ring1', 'ring2'])
        self.assertEqual(rejetes, [])

    def test_retro_refuses_the_double_its_solver_would_answer_infeasible(self):
        """rings_can_double is False for retro, and a doubled ring there is not
        a worse set, it is no set at all."""
        from chardata.build_import import ALREADY_PLACED, plan_ankama_ids
        places, rejetes = plan_ankama_ids(
            self.structure,
            [self.ANNEAU_SANS_PANOPLIE, self.ANNEAU_SANS_PANOPLIE],
            game_version='retro')
        self.assertEqual(len(places), 1)
        self.assertEqual(rejetes,
                         [(self.ANNEAU_SANS_PANOPLIE, ALREADY_PLACED)])

    def test_a_ring_with_a_set_is_never_doubled(self):
        from chardata.build_import import ALREADY_PLACED
        anneau = self.structure.get_item_by_ankama_id(self.ANNEAU_A)
        self.assertIsNotNone(getattr(anneau, 'set', None),
                             'this test needs a ring that belongs to a set')
        places, rejetes = self._plan([self.ANNEAU_A, self.ANNEAU_A])
        self.assertEqual(len(places), 1)
        self.assertEqual(rejetes, [(self.ANNEAU_A, ALREADY_PLACED)])

    def test_an_item_the_character_could_not_wear_is_refused_by_name(self):
        """Left in, the solver answers Infeasible and the reader never learns
        which item caused it."""
        from chardata.build_import import ABOVE_CHAR_LEVEL, plan_ankama_ids
        chapeau = self.structure.get_item_by_ankama_id(self.CHAPEAU)
        places, rejetes = plan_ankama_ids(
            self.structure, [self.CHAPEAU], char_level=chapeau.level - 1)
        self.assertEqual(places, [])
        self.assertEqual(rejetes, [(self.CHAPEAU, ABOVE_CHAR_LEVEL)])

    def test_an_id_that_cannot_even_be_a_number_still_comes_back(self):
        """float('inf') raises OverflowError, not ValueError. It used to leave
        by way of a traceback, which breaks the one promise this module makes.
        """
        from chardata.build_import import UNKNOWN_ITEM
        for tordu in (float('inf'), float('nan'), None, 'x', [], object()):
            places, rejetes = self._plan([tordu])
            self.assertEqual(places, [], repr(tordu))
            self.assertEqual(len(rejetes), 1, repr(tordu))
            self.assertEqual(rejetes[0][1], UNKNOWN_ITEM, repr(tordu))

    def _char(self, alias='proprio'):
        import pickle as _pickle
        from django.contrib.auth.models import User
        from chardata.models import Char
        from fashionistapulp.modelresult import ModelResultMinimal
        entree = {'options': {}, 'origin': 'generated', 'char_level': 200,
                  'base_stats_by_attr': {}, 'locked_equips': {}}
        return Char.objects.create(
            name='Etoile', char_name='star', char_class='Iop',
            char_build='build', level=200,
            minimum_stats=b'', minimum_crits=b'', stats_weight=b'',
            options=b'', inclusions=b'', exclusions=b'',
            minimal_solution=_pickle.dumps(ModelResultMinimal({}, entree, {})),
            owner=User.objects.create_user(alias, '%s@example.com' % alias, 'x'),
            link_shared=False, game_version='dofus3')

    def test_planning_writes_nothing(self):
        """The plan is shown to a reader before anything is imposed, so it
        must not have imposed it already."""
        from chardata.lock_forbid import get_inclusions_dict
        char = self._char()
        avant = dict(get_inclusions_dict(char))
        self._plan([self.CHAPEAU, self.ANNEAU_A])
        self.assertEqual(dict(get_inclusions_dict(char)), avant)

    def test_an_import_replaces_the_set_it_does_not_settle_on_top_of_it(self):
        """The first version of this module merged, and merging was wrong
        twice over: the hat of the previous build stayed locked underneath the
        new one, and a lone imported ring landed in a hand that still held its
        own copy, which retro answers with Infeasible.
        """
        from chardata.build_import import apply_ankama_ids
        from chardata.lock_forbid import get_inclusions_dict
        char = self._char()

        apply_ankama_ids(char, self.structure,
                         [self.CHAPEAU, self.ANNEAU_A, self.ANNEAU_B])
        premier = {s: v for s, v in get_inclusions_dict(char).items() if v != ''}
        self.assertEqual(sorted(premier), ['hat', 'ring1', 'ring2'])

        # Un second import d'un seul anneau : tout le reste doit disparaitre.
        rapport = apply_ankama_ids(char, self.structure, [self.ANNEAU_B])
        second = {s: v for s, v in get_inclusions_dict(char).items() if v != ''}
        self.assertEqual(sorted(second), ['ring1'],
                         'the previous build survived underneath: %r' % second)
        self.assertEqual(len(rapport['placed']), 1)
        self.assertEqual(rapport['rejected'], [])

    def test_an_import_never_leaves_the_same_ring_in_both_hands(self):
        """Merging produced exactly that, and it is the shape the solver
        cannot answer at all in retro."""
        from chardata.build_import import apply_ankama_ids
        from chardata.lock_forbid import get_inclusions_dict
        char = self._char()
        apply_ankama_ids(char, self.structure, [self.ANNEAU_A, self.ANNEAU_B])
        apply_ankama_ids(char, self.structure, [self.ANNEAU_B])
        portes = [v for v in get_inclusions_dict(char).values() if v != '']
        self.assertEqual(len(portes), len(set(portes)), portes)


class AFailedAdSettingReadServesNoAdsTests(TestCase):
    """A database hiccup must not put advertising back on.

    What holds ads off is a stored setting, and a read that failed used to be
    filed as a setting that was absent: the same empty dict, then cached as one
    for the whole TTL. The defaults underneath say ads on, since no adsense key
    in gen_config leaves enabled at True and client at DEFAULT_AD_CLIENT. One
    hiccup while the cache was cold was therefore enough to serve AdSense on
    every page that allows it, for as long as the cache held, with nothing
    written anywhere to say so.
    """

    def setUp(self):
        from django.core.cache import cache
        from chardata.context_processors import AD_SETTING_KEY
        cache.delete(AD_SETTING_KEY)

    def _lecture_qui_echoue(self):
        from unittest import mock
        from django.db import OperationalError
        from chardata.models import SiteSetting
        return mock.patch.object(
            SiteSetting.objects, 'filter',
            side_effect=OperationalError('the database is unreachable'))

    def test_a_read_that_fails_serves_no_ads(self):
        from chardata.context_processors import ad_config
        with self._lecture_qui_echoue():
            config = ad_config()
        self.assertFalse(config.get('enabled', True),
                         'a failed read left advertising switched on')

    def test_a_read_that_fails_is_not_remembered_as_an_answer(self):
        """Caching the failure is what made it last: the next request would
        have taken the empty dict for a real setting."""
        from chardata.context_processors import ad_config
        with self._lecture_qui_echoue() as faux:
            ad_config()
            ad_config()
        self.assertEqual(faux.call_count, 2,
                         'the failure was cached, so the database was never '
                         'asked again')

    def test_no_page_carries_ad_code_while_the_read_fails(self):
        with self._lecture_qui_echoue():
            page = self.client.get('/support/', HTTP_USER_AGENT='Mozilla/5.0')
        self.assertEqual(page.status_code, 200)
        self.assertNotIn(b'pagead2.googlesyndication', page.content)
        self.assertNotIn(b'google-adsense-account', page.content)

    def test_the_failure_is_said_out_loud(self):
        """Failing shut is silent by nature, and json.loads sits inside the
        same try: a row saved with broken JSON would cost the ads and one
        query per request for good. Something has to name it."""
        from chardata.context_processors import ad_config
        with self._lecture_qui_echoue():
            with self.assertLogs('chardata.context_processors', 'WARNING') as journal:
                ad_config()
        self.assertTrue(any('ad setting could not be read' in ligne
                            for ligne in journal.output), journal.output)

    def test_a_setting_that_is_merely_absent_still_reads_normally(self):
        """Only the failure is treated apart. No row at all remains what it
        always was: the defaults."""
        from chardata.context_processors import ad_config
        from chardata.models import SiteSetting
        SiteSetting.objects.filter(key='adsense').delete()
        self.assertIsInstance(ad_config(), dict)


class PrivacyPolicyDescribesWhatActuallyHappensTests(TestCase):
    """A privacy policy may only describe processing that happens.

    This one described an ad network, targeting cookies and an EEA consent
    message while none of it ran: no AdSense loader is served, and two other
    pages of the site said the opposite in five languages. A policy that
    invents a treatment is worse than a vague one, because a reader in the EEA
    reads it to decide something.

    Every advertising claim now hangs on ads_allowed, the same flag that puts
    the AdSense loader on the page. Nothing was deleted: turn ads back on and
    the policy describes them again, without anyone having to remember.
    """

    NAVIGATEUR = ('Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 '
                  '(KHTML, like Gecko) Chrome/126.0 Safari/537.36')
    SANS_PUB = {'enabled': False, 'client': '', 'slots': {}, 'auto': False}
    AVEC_PUB = {'enabled': True, 'client': 'ca-pub-0000000000000000',
                'slots': {}, 'auto': True}

    # Le titre de section et la meta description comptent autant que le corps :
    # la meta part aux moteurs de recherche et aux apercus partages.
    CLAUSES = ('we display ads', 'AdSense', 'Consent (EEA',
               'advertising that funds the service',
               'control advertising cookies')

    def _policy(self, pubs, langue='en'):
        from unittest import mock
        with mock.patch('chardata.context_processors.ad_config',
                        return_value=dict(pubs)):
            reponse = self.client.get('/privacy/',
                                      HTTP_USER_AGENT=self.NAVIGATEUR,
                                      HTTP_ACCEPT_LANGUAGE=langue)
        self.assertEqual(reponse.status_code, 200)
        return reponse.content.decode('utf-8')

    def test_it_claims_no_advertising_while_none_is_served(self):
        page = self._policy(self.SANS_PUB)
        for clause in self.CLAUSES:
            self.assertNotIn(clause, page,
                             'the policy still describes advertising: %s' % clause)

    def test_it_describes_advertising_again_the_moment_it_returns(self):
        page = self._policy(self.AVEC_PUB)
        for clause in self.CLAUSES:
            self.assertIn(clause, page,
                          'ads are served and the policy hides %s' % clause)

    def test_the_translated_policy_is_held_to_the_same_rule(self):
        for langue, publicite in (('fr', 'publicité'), ('es', 'publicidad'),
                                  ('pt', 'publicidade'), ('de', 'Werbung')):
            sans = self._policy(self.SANS_PUB, langue)
            self.assertNotIn(publicite, sans, langue)
            self.assertNotIn('AdSense', sans, langue)
            self.assertIn(publicite, self._policy(self.AVEC_PUB, langue), langue)

    def test_what_is_true_either_way_never_moves(self):
        """Analytics really is loaded, and the account sections do not depend
        on advertising. Guarding must not have taken them along."""
        for pubs in (self.SANS_PUB, self.AVEC_PUB):
            page = self._policy(pubs)
            for garde in ('Google Analytics', 'Google Sign-In',
                          'Hosting and infrastructure',
                          'We do not sell your personal data'):
                self.assertIn(garde, page, garde)


class SupportPageFramingTests(TestCase):
    """The donation ask, in the reader's own language.

    A translated catalogue that never reaches the page is worth nothing, and
    that failure is silent: gettext falls back to English and the page still
    renders. So this asserts on what a Spanish reader actually receives, not on
    the presence of an entry in a .po file.

    The wording says two things, and both are checked in every language: the
    site carries no advertising, and the server has been paid for out of the
    owner's own pocket, and built in their spare time. It names no amount. Donations are never
    said to pay for the server, because they do not: one donation has been
    received, and the sentence that claimed otherwise was removed.

    The no-advertising half is only said while there are no ads, so the page is
    rendered here under an ad configuration the test states rather than under
    whatever the environment happens to carry.
    """

    SANS_PUB = {'enabled': False, 'client': '', 'slots': {}, 'auto': False}

    PHRASES = {
        'fr': ('aucune publicité sur le site', 'de ma poche et je développe'),
        'es': ('ninguna publicidad en la web', 'de mi bolsillo y desarrollo'),
        'pt': ('nenhuma publicidade no site', 'do meu bolso e desenvolvo'),
        'de': ('keine Werbung', 'bezahle ich selbst und entwickle'),
    }

    def _support_page(self, langue, chemin=None):
        from unittest import mock
        with mock.patch('chardata.context_processors.ad_config',
                        return_value=dict(self.SANS_PUB)):
            page = self.client.get(chemin or '/%s/support/' % langue)
            if page.status_code == 404:
                page = self.client.get('/support/', HTTP_ACCEPT_LANGUAGE=langue)
            return page

    def test_each_language_reads_it_in_its_own_words(self):
        for langue, attendues in self.PHRASES.items():
            page = self._support_page(langue)
            self.assertEqual(page.status_code, 200, langue)
            html = page.content.decode('utf-8')
            for attendu in attendues:
                self.assertIn(attendu, html,
                              'the %s reader is missing "%s"' % (langue, attendu))

    def test_english_still_says_it(self):
        html = self._support_page(
            'en', chemin='/support/').content.decode('utf-8')
        self.assertIn('no advertising on the site', html)
        self.assertIn('for the server myself and build this in my spare time', html)

    def test_no_amount_is_ever_shown(self):
        """The owner asked for no figure. A number here would also date badly
        and invite the reader to weigh their gift against it."""
        for langue in list(self.PHRASES) + ['en']:
            html = self._support_page(
                langue, chemin='/support/').content.decode('utf-8')
            debut = html.find('support-intro')
            bloc = html[debut:debut + 1600] if debut != -1 else ''
            for interdit in ('10 €', '10€', '€10', '10 EUR'):
                self.assertNotIn(interdit, bloc, langue)

    def test_the_donation_link_is_still_counted(self):
        html = self._support_page('en', chemin='/support/').content.decode('utf-8')
        self.assertIn('/out/donate/0/', html)


class SignInWithGoogleWorksTests(TestCase):
    """The Google button has to send what the library will accept.

    social_django 6 decorates its begin view with @require_POST. A plain link
    therefore answers 405 with an empty body -- and an empty body is a blank
    page, which is exactly what a reader trying to sign in reported seeing.
    Nothing on this side changed; a dependency upgrade did, and the hardening
    is sound: a GET to that url can be triggered from another site and start
    an authentication nobody asked for.

    The last test is the general one. It walks the pages that carry links and
    fails if any <a href> points at a view that only accepts POST, so the next
    library to tighten a method is caught here rather than by a reader.
    """

    OAUTH = '/login/google-oauth2/'

    def test_the_begin_view_refuses_a_get(self):
        """Pinned deliberately: if a future upgrade relaxes this, the form
        below becomes unnecessary and this test says so."""
        self.assertEqual(self.client.get(self.OAUTH).status_code, 405)

    def test_the_login_page_posts_instead_of_linking(self):
        html = self.client.get('/login_page/').content.decode('utf-8')
        self.assertIn(self.OAUTH, html, 'the Google button vanished')
        self.assertNotIn('<a href="%s' % self.OAUTH, html,
                         'the Google button is a link again, which answers 405')
        bloc = html[max(0, html.find(self.OAUTH) - 400):html.find(self.OAUTH) + 400]
        self.assertIn('method="post"', bloc.lower(),
                      'the Google button is not inside a POST form')
        self.assertIn('csrfmiddlewaretoken', html,
                      'a POST without a CSRF token is refused by Django')

    def test_the_button_survives_in_every_language(self):
        for langue in ('fr', 'es', 'pt', 'de', 'en'):
            html = self.client.get(
                '/login_page/', HTTP_ACCEPT_LANGUAGE=langue).content.decode('utf-8')
            self.assertIn(self.OAUTH, html, langue)
            self.assertIn('csrfmiddlewaretoken', html, langue)

    def test_no_page_links_to_a_view_that_only_takes_post(self):
        """The general rule, so the next one is caught here."""
        from django.urls import resolve

        pages = ('/', '/login_page/', '/support/', '/encyclopedia/', '/guides/',
                 '/sharedbuilds/', '/about/', '/faq/')
        fautifs = []
        for page in pages:
            reponse = self.client.get(page)
            if reponse.status_code != 200:
                continue
            html = reponse.content.decode('utf-8')
            for href in _local_links(html):
                try:
                    vue = resolve(href).func
                except Exception:
                    continue
                autorisees = getattr(vue, 'allowed_methods', None) or \
                    getattr(getattr(vue, 'view_class', None), 'http_method_names', None)
                if autorisees and 'GET' not in {m.upper() for m in autorisees}:
                    fautifs.append('%s links to %s' % (page, href))
                    continue
                # A require_POST view keeps its wrapper; asking it with GET is
                # the only reliable way to know from the outside.
                if self.client.get(href).status_code == 405:
                    fautifs.append('%s links to %s, which answers 405 to a GET'
                                   % (page, href))
        self.assertEqual([], fautifs)


class CrawlersAreNotReadersTests(TestCase):
    """A count that includes crawlers answers a question nobody asked.

    Measured on the first day in production: 62 130 arrivals for a site that
    PageHit puts at about 16 page views a day, 61 539 of them from the United
    States, all filed as "direct". A crawler sends no referrer, so every one of them landed
    in that bucket and buried the six real rows underneath it.
    """

    LECTEURS = (
        'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 '
        '(KHTML, like Gecko) Chrome/126.0 Safari/537.36',
        'Mozilla/5.0 (iPhone; CPU iPhone OS 17_0 like Mac OS X) '
        'AppleWebKit/605.1.15 Version/17.0 Mobile/15E148 Safari/604.1',
        'Mozilla/5.0 (X11; Linux x86_64; rv:128.0) Gecko/20100101 Firefox/128.0',
    )

    ROBOTS = (
        'Mozilla/5.0 (compatible; Googlebot/2.1; +http://www.google.com/bot.html)',
        'Mozilla/5.0 (compatible; bingbot/2.0; +http://www.bing.com/bingbot.htm)',
        'Mozilla/5.0 (compatible; AhrefsBot/7.0; +http://ahrefs.com/robot/)',
        'GPTBot/1.2', 'ClaudeBot/1.0', 'CCBot/2.0', 'Bytespider',
        'curl/8.7.1', 'Wget/1.21', 'python-requests/2.31.0',
        'Go-http-client/2.0', 'okhttp/4.12.0', 'Scrapy/2.11',
        'facebookexternalhit/1.1', 'HeadlessChrome/126.0',
        '',
    )

    def _compte(self):
        from django.db.models import Sum
        from chardata.models import VisitSource
        return VisitSource.objects.aggregate(n=Sum('count'))['n'] or 0

    def test_a_crawler_is_not_counted(self):
        for agent in self.ROBOTS:
            self.client.get('/', HTTP_USER_AGENT=agent)
        self.assertEqual(self._compte(), 0,
                         'crawlers reached the arrival count')

    def test_a_reader_still_is(self):
        for agent in self.LECTEURS:
            self.client.get('/', HTTP_USER_AGENT=agent)
        self.assertEqual(self._compte(), len(self.LECTEURS))

    def test_the_direct_bucket_is_where_they_would_have_landed(self):
        """The specific failure: no referrer means 'direct', and no crawler
        sends one."""
        from chardata.models import VisitSource
        self.client.get('/', HTTP_USER_AGENT=self.ROBOTS[0])
        self.assertFalse(VisitSource.objects.filter(source='direct').exists())
        self.client.get('/', HTTP_USER_AGENT=self.LECTEURS[0])
        self.assertTrue(VisitSource.objects.filter(source='direct').exists())

    def test_a_browser_name_containing_bot_is_not_caught_by_accident(self):
        """The pattern must not swallow a reader. 'Bot' has to appear as a
        word or a path, not inside another one."""
        from chardata.middleware import looks_like_a_robot
        from django.test import RequestFactory
        for agent in ('Mozilla/5.0 Botswana Browser/3.0',
                      'Mozilla/5.0 (Linux) Abbotsford/2.1'):
            faux = RequestFactory().get('/', HTTP_USER_AGENT=agent)
            self.assertFalse(looks_like_a_robot(faux), agent)

    def test_a_name_ending_in_bot_is_caught_without_a_slash(self):
        """The first alternative of the pattern was dead for months.

        It read `bot` followed by a byte that renders as nothing: 0x08, a
        backspace, where a word boundary was meant. No user agent contains a
        backspace, so that branch never matched and only the crawlers naming
        themselves `bot/` or by brand were caught. Most real ones do both, so
        the loss was small -- but a pattern that cannot fire says nothing about
        what it lets through.
        """
        from chardata.middleware import looks_like_a_robot
        from django.test import RequestFactory
        for agent in ('SomeRandomBot', 'Mozilla/5.0 (compatible; NewBot)',
                      'InternalMonitorBot 1.2'):
            faux = RequestFactory().get('/', HTTP_USER_AGENT=agent)
            self.assertTrue(looks_like_a_robot(faux), agent)

    def test_the_purge_command_reports_before_it_deletes(self):
        from io import StringIO
        from django.core.management import call_command
        from django.utils import timezone
        from chardata.models import VisitSource
        VisitSource.objects.create(day=timezone.localdate(), source='direct',
                                   medium='none', count=62102)
        sortie = StringIO()
        call_command('purge_bot_arrivals', '--before', '2999-01-01', stdout=sortie)
        self.assertIn('62102', sortie.getvalue())
        self.assertIn('dry run', sortie.getvalue())
        self.assertEqual(VisitSource.objects.count(), 1, 'a dry run deleted')

        call_command('purge_bot_arrivals', '--before', '2999-01-01', '--apply',
                     stdout=StringIO())
        self.assertEqual(VisitSource.objects.count(), 0)


class AskingAtTheMomentOfValueTests(TestCase):
    """Where the donation is asked for, and whether the placement can be told
    apart afterwards.

    The ask lived on /support/, a page almost nobody opens. It now also sits on
    the result page, right after the tool has done the thing people came for.
    Which of the two works is the number nobody has, and one undifferentiated
    total could never produce it -- hence the source on every click.

    Nothing is locked and nothing is removed: the promise "free and always
    will be" is published and translated, and it still holds.
    """

    NAVIGATEUR = ('Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 '
                  '(KHTML, like Gecko) Chrome/126.0 Safari/537.36')

    def _shared_build(self):
        import pickle as _pickle
        from django.contrib.auth.models import User
        from chardata.models import Char
        from fashionistapulp.modelresult import ModelResultMinimal
        # A fresh owner per call: the language test builds five pages in one
        # test, and a reused username fails the unique constraint.
        rang = User.objects.count()
        owner = User.objects.create_user('owner%d' % rang,
                                         'o%d@example.com' % rang, 'x')
        # Same shape as SharedSolutionPageTests: get_solution() rejects
        # anything else and the view answers 404, which looks like a template
        # problem and is not one.
        input_ = {'options': {'ap_exo': False, 'mp_exo': False},
                  'origin': 'generated', 'char_level': 200,
                  'base_stats_by_attr': {}, 'locked_equips': {}}
        return Char.objects.create(
            name='Etoile', char_name='star', char_class='Iop',
            char_build='build', level=200,
            minimum_stats=b'', minimum_crits=b'', stats_weight=b'',
            options=b'', inclusions=b'', exclusions=b'',
            minimal_solution=_pickle.dumps(ModelResultMinimal({}, input_, {})),
            owner=owner, link_shared=True, game_version='dofus3')

    # La configuration publicitaire est ambiante, et par defaut le depot autorise
    # la publicite sur /s/ : la production n'en est exempte que par un reglage
    # enregistre a l'execution. Les pages sont donc rendues sous une
    # configuration que le test enonce, jamais sous celle qui traine.
    SANS_PUB = {'enabled': False, 'client': '', 'slots': {}, 'auto': False}
    AVEC_PUB = {'enabled': True, 'client': 'ca-pub-0000000000000000',
                'slots': {}, 'auto': True}

    def _result_page(self, langue='en', pubs=None):
        from unittest import mock
        from chardata.encoded_char_id import encode_char_id
        build = self._shared_build()
        with mock.patch('chardata.context_processors.ad_config',
                        return_value=dict(pubs or self.SANS_PUB)):
            return self.client.get(
                '/s/star/%s/' % encode_char_id(build.pk),
                HTTP_USER_AGENT=self.NAVIGATEUR,
                HTTP_ACCEPT_LANGUAGE=langue).content.decode('utf-8')

    def test_the_no_ads_claim_cannot_outlive_the_ads_staying_off(self):
        """Saying "no ads" has to stop being said the moment there are ads.

        The AdSense loader hangs on ads_allowed, which /s/ and /support/ are
        granted by default and which needs no slot id. Unguarded, turning ads
        back on would have left the most read page of the site claiming there
        were none, in five languages.
        """
        avec = self._result_page(pubs=self.AVEC_PUB)
        self.assertIn('pagead2.googlesyndication', avec,
                      'the probe never turned ads on, so it proves nothing')
        self.assertNotIn('No ads', avec)
        # Le reste de la demande survit : seule l'affirmation invalide tombe.
        self.assertIn('for the server myself and build this in my spare time', avec)
        self.assertIn('/out/donate/?from=solution', avec)

        sans = self._result_page()
        self.assertNotIn('pagead2.googlesyndication', sans)
        self.assertIn('No ads, no subscription', sans)

    def test_the_support_page_is_held_to_the_same_claim(self):
        from unittest import mock
        for pubs, sans_pub in ((self.SANS_PUB, True), (self.AVEC_PUB, False)):
            with mock.patch('chardata.context_processors.ad_config',
                            return_value=dict(pubs)):
                html = self.client.get(
                    '/support/',
                    HTTP_USER_AGENT=self.NAVIGATEUR).content.decode('utf-8')
            self.assertEqual('There is no advertising on the site' in html,
                             sans_pub, 'pubs=%s' % (pubs,))
            self.assertIn('for the server myself and build this in my spare time', html)

    def test_the_result_page_carries_the_ask(self):
        html = self._result_page()
        self.assertIn('/out/donate/?from=solution', html)
        self.assertIn('No ads, no subscription', html)

    def test_the_ask_comes_after_the_result_not_before_it(self):
        """The ask sat between the share buttons and the gear, so it was read
        before the reader had been given anything. It belongs below the closing
        of the two-column result: the set on the left, the stats on the right.

        This is the whole point of the placement, so it is the thing to guard.
        """
        # Les scripts de bas de page citent ces memes classes ; seules comptent
        # celles du corps rendu. Retirees en analysant la page et non par
        # motif : une expression reguliere ne sait pas lire du balisage, elle
        # rate un <SCRIPT> en majuscules et se laisse tromper par la meme
        # suite de caracteres a l'interieur d'un attribut.
        corps = _without_scripts(self._result_page())
        demande = corps.index('solution-support-button')
        for colonne in ('solution-item-summary', 'solution-stat-summary'):
            self.assertGreater(
                demande, corps.rindex(colonne),
                'the ask precedes the end of %s, so it is made before the set '
                'has been shown' % colonne)

    def test_the_ask_never_claims_donations_pay_the_server(self):
        """They do not. The server has been paid for out of pocket since 2023,
        against a single donation, so any sentence saying otherwise is false
        and must not come back.
        """
        for langue in ('en', 'fr', 'es', 'pt', 'de'):
            html = self._result_page(langue)
            for faux in ('paid for by donations', 'payé par des dons',
                         'pagado con donaciones', 'pago por doações',
                         'Spenden bezahlen'):
                self.assertNotIn(faux, html, '%s / %s' % (langue, faux))

    def test_it_speaks_the_reader_s_language(self):
        for langue, attendu in (('fr', 'de ma poche et je développe'),
                                ('es', 'de mi bolsillo y desarrollo'),
                                ('pt', 'do meu bolso e desenvolvo'),
                                ('de', 'bezahle ich selbst und entwickle')):
            self.assertIn(attendu, self._result_page(langue), langue)

    def test_nothing_was_locked_away(self):
        """The ask must not have taken anything with it: the build still
        renders in full."""
        from chardata.encoded_char_id import encode_char_id
        build = self._shared_build()
        page = self.client.get('/s/star/%s/' % encode_char_id(build.pk),
                               HTTP_USER_AGENT=self.NAVIGATEUR)
        self.assertEqual(page.status_code, 200)
        self.assertNotIn(b'paywall', page.content.lower())
        self.assertNotIn(b'subscribe', page.content.lower())

    def test_each_placement_is_counted_apart(self):
        from chardata.models import SupportClick
        for source in ('solution', 'support', 'footer'):
            self.client.get('/out/donate/?from=%s' % source,
                            HTTP_USER_AGENT=self.NAVIGATEUR)
        comptes = dict(SupportClick.objects.values_list('source', 'count'))
        self.assertEqual(comptes, {'solution': 1, 'support': 1, 'footer': 1})

    def test_an_invented_placement_is_filed_apart_not_trusted(self):
        """A visitor cannot grow the table by inventing labels, and a click is
        never lost over one."""
        from chardata.models import SupportClick
        for invente in ('../etc', 'x' * 500, 'DROP TABLE', ''):
            reponse = self.client.get('/out/donate/?from=%s' % invente,
                                      HTTP_USER_AGENT=self.NAVIGATEUR)
            self.assertEqual(reponse.status_code, 302, invente)
        sources = set(SupportClick.objects.values_list('source', flat=True))
        self.assertTrue(sources <= {'other', 'support'}, sources)

    def test_the_destination_never_moves(self):
        """from= labels a counter. It must never reach the redirect."""
        from django.conf import settings
        attendu = (getattr(settings, 'SUPPORT_LINKS', []) or [{}])[0].get('url')
        for essai in ('solution', 'https://evil.example/', 'other'):
            reponse = self.client.get('/out/donate/?from=%s' % essai,
                                      HTTP_USER_AGENT=self.NAVIGATEUR)
            self.assertEqual(reponse['Location'], attendu, essai)


class TheLanguageSelectorWorksWithoutAMouseTests(TestCase):
    """Five flags decided the language and none of them could be focused.

    They were <img> elements carrying a jQuery .click(), which is a control
    only a pointing device can reach: no tab stop, no Enter, no Space, nothing
    a screen reader announces as actionable. The whole chain was affected, the
    flag that opens the menu included, so a keyboard visitor could not even
    open it. A <button> gives all of that natively and needs no ARIA to say
    what a real button already is.
    """

    NAVIGATEUR = 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) Chrome/126.0'
    LANGUES = ('en', 'fr', 'es', 'pt', 'de')

    def _accueil(self):
        reponse = self.client.get('/', HTTP_USER_AGENT=self.NAVIGATEUR)
        self.assertEqual(reponse.status_code, 200)
        return reponse.content.decode('utf-8')

    def _balise(self, page, identifiant):
        """Ouvrante de l'element portant cet id, quel que soit l'ordre.

        Le minifieur trie les attributs et met tout sur une ligne, donc une
        assertion qui suppose un ordre passe le jour ou on l'ecrit et casse au
        suivant sans que rien ait change pour le lecteur.
        """
        import re
        return re.search(r'<(\w+)[^>]* id="%s"[^>]*>' % identifiant, page)

    def test_the_flag_that_opens_the_menu_is_a_button(self):
        balise = self._balise(self._accueil(), 'flag')
        self.assertIsNotNone(balise)
        self.assertEqual(balise.group(1), 'button')
        self.assertIn('type="button"', balise.group(0))

    def test_every_flag_that_picks_a_language_can_be_reached(self):
        """Un controle atteignable au clavier, pas une balise en particulier.

        Ce test exigeait <button>, ce qui etait le mecanisme et non la
        propriete. Le drapeau est devenu <a> la ou la page sait ou vit sa
        traduction, parce qu'un bouton n'est pas un lien et qu'aucun robot ne
        suivait les quatre. Une ancre est focalisable et s'active a Entree
        exactement comme un bouton -- a une condition, qu'elle porte un href :
        sans lui elle sort de l'ordre de tabulation, et le defaut d'origine
        reviendrait sous un autre nom.
        """
        page = self._accueil()
        trouves = 0
        for langue in self.LANGUES:
            balise = self._balise(page, 'flag-%s' % langue)
            if balise is None:
                continue    # la langue courante n'a pas de drapeau de choix
            trouves += 1
            self.assertIn(balise.group(1), ('button', 'a'), langue)
            if balise.group(1) == 'a':
                import re
                href = re.search(r' href="([^"]*)"', balise.group(0))
                self.assertTrue(
                    href and href.group(1),
                    '%s : une ancre sans href n\'est ni un lien ni un arret '
                    'de tabulation' % langue)
            # data-next porte la destination, et le script la lit par cet id :
            # la deplacer sur le bouton sans l'emporter casserait le choix.
            self.assertIn('data-next=', balise.group(0), langue)
        self.assertEqual(trouves, 4)

    def test_no_image_is_left_acting_as_a_control(self):
        """The regression this class exists to stop.

        An <img id="flag-fr"> is what the selector used to be, and it is what
        a well-meaning edit would put back: it renders identically and only
        fails for people who are not using a mouse.
        """
        import re
        page = self._accueil()
        self.assertEqual(
            re.findall(r'<img[^>]* id="flag[^"]*"', page), [])

    def test_it_says_whether_the_menu_is_open(self):
        balise = self._balise(self._accueil(), 'flag')
        self.assertIn('aria-haspopup="true"', balise.group(0))
        # Ferme au chargement, et le script le passe a true a l'ouverture.
        self.assertIn('aria-expanded="false"', balise.group(0))


class TheThemeSelectorWorksWithoutAMouseTests(TestCase):
    """The same defect as the flags, in the control right next to them.

    Four <div> carrying a jQuery .click(): the one that opens the menu and the
    three that pick a theme. None could be focused, so a visitor navigating
    with a keyboard could not switch to the dark theme at all. The classes
    carry every bit of the styling, so the elements become <button> without
    the page changing.
    """

    NAVIGATEUR = 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) Chrome/126.0'
    CHOIX = ('theme-light', 'theme-dark', 'theme-auto')

    def _accueil(self):
        reponse = self.client.get('/', HTTP_USER_AGENT=self.NAVIGATEUR)
        self.assertEqual(reponse.status_code, 200)
        return reponse.content.decode('utf-8')

    @staticmethod
    def _porteur(page, attribut, valeur):
        """Balise ouvrante portant cet attribut, quel que soit l'ordre.

        Le minifieur trie les attributs, donc un motif qui suppose l'ordre ne
        trouve rien et fait passer un test negatif sans rien garder.
        """
        import re
        for balise in re.findall(r'<[a-z]+[^>]*>', page):
            if '%s="%s"' % (attribut, valeur) in balise:
                return balise
        return None

    def test_the_control_that_opens_the_menu_is_a_button(self):
        page = self._accueil()
        balise = self._porteur(page, 'aria-haspopup', 'true')
        self.assertIsNotNone(balise)
        # Les drapeaux en ont un aussi : on veut celui du theme.
        balise = None
        import re
        for candidat in re.findall(r'<[a-z]+[^>]*>', page):
            if 'current-theme' in candidat:
                balise = candidat
                break
        self.assertIsNotNone(balise)
        self.assertTrue(balise.startswith('<button'), balise)
        self.assertIn('aria-expanded="false"', balise)

    def test_every_theme_choice_is_a_button(self):
        page = self._accueil()
        for identifiant in self.CHOIX:
            balise = self._porteur(page, 'id', identifiant)
            self.assertIsNotNone(balise, identifiant)
            self.assertTrue(balise.startswith('<button'), balise)
            self.assertIn('type="button"', balise, identifiant)

    def test_no_div_is_left_acting_as_a_theme_control(self):
        """The regression this exists to stop, and it has been seen red.

        Putting the <div> back and watching this fail is the only thing that
        proves the test looks at anything: a pattern that can never match
        makes an assertion of absence pass forever.
        """
        import re
        page = self._accueil()
        # Sur le jeton exact, pas sur la sous-chaine : le conteneur s'appelle
        # base-theme-selector-div et contient "theme-selector" sans etre une
        # commande. Premiere version rouge pour cette seule raison.
        coupables = []
        for balise in re.findall(r'<div[^>]*>', page):
            jetons = set()
            for valeur in re.findall(r'class="([^"]*)"',
                                     balise.replace(chr(39), chr(34))):
                jetons.update(valeur.split())
            if jetons & {'theme-selector', 'current-theme'}:
                coupables.append(balise)
        self.assertEqual(coupables, [])

    def test_the_selector_opens_no_form_it_does_not_close(self):
        """It shipped with a </form> and no <form> above it.

        Harmless in a browser, which drops the stray tag, and exactly the kind
        of leftover that makes the next person doubt the markup around it.
        """
        page = self._accueil()
        self.assertEqual(page.count('<form'), page.count('</form>'))


class NoSourceFileHidesAControlCharacterTests(SimpleTestCase):
    """Three patterns in this repository were silently dead at once.

    Each was written as a word boundary inside a non-raw string, generated
    from a nested script, and each came out as 0x08 -- a backspace, which no
    input contains. A test could not fire, a security check could not fire,
    and the crawler filter lost its first alternative. All three read as
    perfectly ordinary source in a terminal, because a terminal prints nothing
    for a backspace; only repr() and `cat -A` showed them.

    The point is not the byte. It is that a pattern which cannot match makes
    an assertion of absence pass forever, so the failure hides in the one
    place nobody rereads: something already green.
    """

    SUFFIXES = ('.py', '.js', '.html', '.css', '.sh')
    #: Ce que personne n'ecrit volontairement dans du code source.
    INTERDITS = {8: 'backspace', 11: 'vertical tab', 12: 'form feed',
                 7: 'bell', 0: 'null'}

    def test_no_python_or_template_carries_one(self):
        import os
        racine = os.path.dirname(os.path.abspath(__file__))
        coupables = []
        for dossier, sous, fichiers in os.walk(racine):
            sous[:] = [d for d in sous if d not in ('__pycache__', 'node_modules')]
            for nom in fichiers:
                if not nom.endswith(self.SUFFIXES):
                    continue
                chemin = os.path.join(dossier, nom)
                try:
                    with io.open(chemin, encoding='utf-8') as f:
                        texte = f.read()
                except (UnicodeDecodeError, OSError):
                    continue
                for code, appellation in self.INTERDITS.items():
                    if chr(code) in texte:
                        ligne = texte[:texte.index(chr(code))].count(
                            chr(10)) + 1
                        coupables.append('%s:%s carries a %s'
                                         % (nom, ligne, appellation))
        self.assertEqual([], sorted(coupables))


class SupportClicksCanBeReadWithoutAQueryTests(TestCase):
    """The table counted for weeks and nothing could read it.

    A measurement that needs a hand-written query to consult is a measurement
    nobody consults, which is the same as not having taken it. What the block
    was built to answer is whether asking right after the tool did its work
    beats asking on a page almost nobody opens, and only a breakdown by source
    answers that -- a single total cannot.
    """

    def _appel(self, **options):
        from io import StringIO
        from django.core.management import call_command
        sortie = StringIO()
        call_command('report_support_clicks', stdout=sortie, **options)
        return sortie.getvalue()

    def _clic(self, source, count, langue='fr', recul=0):
        from datetime import timedelta
        from django.utils import timezone
        from chardata.models import SupportClick
        SupportClick.objects.create(
            day=timezone.localdate() - timedelta(days=recul),
            language=langue, source=source, count=count)

    def test_it_separates_the_sources(self):
        self._clic('solution', 30)
        self._clic('footer', 10)
        texte = self._appel()
        self.assertIn('solution', texte)
        self.assertIn('footer', texte)
        # 30 sur 40, la part est ce qui rend les deux comparables.
        self.assertIn('75.0 %', texte)
        self.assertIn('25.0 %', texte)

    def test_it_says_so_when_nothing_was_counted(self):
        """An empty table and a table of zeroes read the same on screen.

        Printing empty headings would be read as a result: nobody clicked.
        The other explanation -- the block is not where you think it is --
        has to stay on the table.
        """
        texte = self._appel()
        self.assertIn('no click recorded', texte)
        self.assertNotIn('by source', texte)

    def test_it_only_looks_back_as_far_as_asked(self):
        self._clic('solution', 5, recul=0)
        self._clic('solution', 99, recul=40)
        texte = self._appel(days=7)
        self.assertIn('5 clicks', texte)
        self.assertNotIn('104', texte)

    def test_it_does_not_let_a_click_pass_for_a_donation(self):
        """The distinction the whole measurement rests on.

        One donation has ever been received. Reading this table as revenue
        would turn a click into money it is not, and the page it leads to is
        the only thing that knows.
        """
        self._clic('solution', 3)
        self.assertIn('not donations', self._appel())


class ThePolicySaysWhatTheCodeDoesTests(TestCase):
    """The retention promise and the code that keeps it, tied together.

    The page listed account data and server logs and said nothing about the
    address kept beside a build to count its views. That silence was survivable
    while the rows were deleted after a day; they were not, because the command
    that deletes them was never called by anything.

    Both halves are now true, and both are tested: this class checks the page
    still makes the promise, and
    SharedSolutionPageTests.test_a_view_drops_the_addresses_that_have_passed_the_day
    checks the code still keeps it. Removing either one fails a test.
    """

    NAVIGATEUR = 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) Chrome/126.0'

    def test_the_policy_states_the_view_address_retention(self):
        page = self.client.get('/privacy/', HTTP_USER_AGENT=self.NAVIGATEUR)
        self.assertEqual(page.status_code, 200)
        texte = page.content.decode('utf-8')
        self.assertIn('twenty-four hours', texte)
        # Dire qu'on garde une adresse sans dire ce qu'on en fait ne vaut rien.
        self.assertIn('once per reader', texte)

    def test_the_retention_the_policy_states_is_the_one_in_the_code(self):
        """Twenty-four hours in prose, twenty-four hours in the query.

        A policy quoting one duration over code enforcing another is the way
        this kind of promise rots: both read fine on their own.
        """
        import inspect
        from chardata import solution_view
        source = inspect.getsource(solution_view)
        self.assertIn('timedelta(hours=24)', source)
        from chardata.management.commands import cleanup_old_views
        self.assertIn('timedelta(hours=24)',
                      inspect.getsource(cleanup_old_views))

    def test_the_page_answers_in_every_language_it_offers(self):
        """A legal page that falls back to English is not translated.

        The sentence was added in five languages at once; a missing catalogue
        entry would show the English string inside an otherwise French page.
        """
        attendu = {'fr': 'vingt-quatre heures', 'es': 'veinticuatro horas',
                   'pt': 'vinte e quatro horas',
                   'de': 'vierundzwanzig Stunden'}
        for langue, phrase in attendu.items():
            page = self.client.get('/privacy/', HTTP_ACCEPT_LANGUAGE=langue,
                                   HTTP_USER_AGENT=self.NAVIGATEUR)
            self.assertEqual(page.status_code, 200, langue)
            self.assertIn(phrase, page.content.decode('utf-8'), langue)


class AMissingEntityAnswersLikeOneTests(TestCase):
    """152 235 urls are submitted and Ankama renames things.

    So this path gets walked, and it was sending three contradictory signals
    at once: the status said gone, the robots tag said index me, and the
    canonical named the encyclopedia hub -- which asks Google to fold a dead
    address into a live page rather than drop it.

    The set case was worse than the others: it rendered the whole hub, 206 kB
    and five hundred items, under a 404.
    """

    NAVIGATEUR = 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) Chrome/126.0'
    ABSENTS = (
        ('item', '/encyclopedia/item/equipment/99999999-rien/'),
        ('set', '/encyclopedia/set/99999999-rien/'),
        ('monster', '/encyclopedia/monster/99999999-rien/'),
        ('resource', '/encyclopedia/resource/resources/99999999-rien/'),
    )

    def _page(self, url):
        reponse = self.client.get(url, HTTP_USER_AGENT=self.NAVIGATEUR)
        self.assertEqual(reponse.status_code, 404, url)
        return reponse.content.decode('utf-8')

    @staticmethod
    def _attribut(page, motif, attribut):
        import re
        balise = re.search(motif, page)
        if balise is None:
            return None
        trouve = re.search(r'%s="([^"]*)"' % attribut, balise.group(0))
        return trouve.group(1) if trouve else None

    def test_none_of_them_asks_to_be_indexed(self):
        for genre, url in self.ABSENTS:
            page = self._page(url)
            robots = self._attribut(page, r'<meta[^>]*name="robots"[^>]*>',
                                    'content')
            self.assertEqual('noindex, follow', robots, genre)

    def test_none_of_them_points_its_canonical_elsewhere(self):
        """A canonical is 'this is the same page as that one'.

        On an address that no longer answers, naming the hub asks for the two
        to be merged. The only true statement left is the address itself.
        """
        for genre, url in self.ABSENTS:
            page = self._page(url)
            canonique = self._attribut(
                page, r'<link[^>]*rel="canonical"[^>]*>', 'href')
            self.assertIsNotNone(canonique, genre)
            self.assertTrue(canonique.endswith(url),
                            '%s: %s' % (genre, canonique))

    def test_a_missing_set_no_longer_serves_the_whole_encyclopedia(self):
        """The hub is 206 kB of items; the answer here is one sentence."""
        page = self._page('/encyclopedia/set/99999999-rien/')
        carrefour = self.client.get('/encyclopedia/',
                                    HTTP_USER_AGENT=self.NAVIGATEUR)
        self.assertEqual(carrefour.status_code, 200)
        self.assertLess(len(page),
                        len(carrefour.content.decode('utf-8')) / 2,
                        'the missing set still answers with the hub')

    def test_it_still_tells_the_reader_where_to_go(self):
        """Correct signals for a crawler must not make a dead end for a
        person: the page names what was asked for and links back."""
        page = self._page('/encyclopedia/set/99999999-rien/')
        # Sur la phrase, pas sur l'adresse : le carrefour rendu sous 404
        # contenait deja l'identifiant demande, dans son propre canonique,
        # si bien que le controle passait aussi quand la page etait fausse.
        self.assertIn('unavailable in this version', page)
        self.assertIn('/encyclopedia/', page)


class AnEmptyProfileVariantDoesNotClaimToBeItsOwnPageTests(TestCase):
    """One profile was served at five addresses, each its own canonical.

    The builds are filtered by game version, so /retro/user/x/ is a different
    page from /user/x/ in principle. In practice it is empty: on 32 versioned
    variants measured in production, 32 showed nothing while the unprefixed
    page carried between two and seven builds. Five near-identical pages each
    declaring itself the original is what Google files under 'duplicate, we
    picked a different canonical than you' -- 2 820 pages of it.

    So the empty ones now say what is true, and the ones that carry builds are
    left alone, because those really are distinct pages.
    """

    NAVIGATEUR = 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) Chrome/126.0'

    def setUp(self):
        from django.contrib.auth.models import User
        from chardata.models import UserAlias
        self.proprio = User.objects.create_user(
            'batisseur', 'b@test.local', 'pw-42-solid')
        UserAlias(user=self.proprio, alias='batisseur').save()

    def _build(self, version):
        import pickle as _pickle
        from chardata.models import Char
        from fashionistapulp.modelresult import ModelResultMinimal
        entree = {'options': {'ap_exo': False, 'mp_exo': False},
                  'origin': 'generated', 'char_level': 200,
                  'base_stats_by_attr': {}, 'locked_equips': {}}
        return Char.objects.create(
            name='Stuff %s' % version, char_name='batisseur',
            char_class='Iop', char_build='build', level=200,
            game_version=version, link_shared=True,
            minimum_stats=b'', minimum_crits=b'', stats_weight=b'',
            options=b'', inclusions=b'', exclusions=b'',
            minimal_solution=_pickle.dumps(ModelResultMinimal({}, entree, {})),
            owner=self.proprio)

    def _tete(self, chemin):
        import re
        reponse = self.client.get(chemin, HTTP_USER_AGENT=self.NAVIGATEUR)
        self.assertEqual(reponse.status_code, 200, chemin)
        page = reponse.content.decode('utf-8')
        robots = re.search(r'<meta[^>]*name="robots"[^>]*>', page)
        canonique = re.search(r'<link[^>]*rel="canonical"[^>]*>', page)
        lire = lambda b, a: (re.search(r'%s="([^"]*)"' % a, b.group(0)).group(1)
                             if b else None)
        return lire(robots, 'content'), lire(canonique, 'href')

    def test_an_empty_versioned_variant_points_at_the_real_page(self):
        self._build('dofus3')
        robots, canonique = self._tete('/retro/user/batisseur/')
        self.assertEqual('noindex, follow', robots)
        self.assertTrue(canonique.endswith('/user/batisseur/'), canonique)
        self.assertNotIn('/retro/', canonique)

    def test_the_unprefixed_profile_stays_its_own(self):
        self._build('dofus3')
        robots, canonique = self._tete('/user/batisseur/')
        self.assertEqual('index, follow', robots)
        self.assertTrue(canonique.endswith('/user/batisseur/'), canonique)

    def test_a_versioned_variant_with_builds_is_left_alone(self):
        """The case that makes the fix a fix and not a blanket rule.

        A player who really did share Retro builds has a Retro profile worth
        its own address, and folding it into the Dofus 3 one would hide it.
        """
        self._build('dofus3')
        self._build('retro')
        robots, canonique = self._tete('/retro/user/batisseur/')
        self.assertEqual('index, follow', robots)
        self.assertIn('/retro/', canonique)


class TheResistanceGuideAnswersTheQuestionItRanksForTests(SimpleTestCase):
    """576 impressions in 28 days, position 8, and not one click.

    Search Console gives the queries, and 47 of them ask the same thing in
    slightly different words: does 100% resistance in Dofus mean zero damage.
    The guide held the answer -- percent resist is capped at 50%, so 100% is
    unreachable -- but never wrote the number the reader was searching for.
    A snippet about a 50% ceiling does not look like an answer to someone who
    typed 100.

    The number is in the description and in the body now, in all five
    languages. This test exists because that is the kind of wording a later
    edit tidies away without knowing what it was for.
    """

    LANGUES = ('en', 'fr', 'es', 'pt', 'de')
    GUIDE = 'resistance-explained'

    def _guide(self, langue):
        from chardata import guides_content
        return guides_content.GUIDES[self.GUIDE]['i18n'][langue]

    def test_every_language_names_the_number_that_is_searched_for(self):
        for langue in self.LANGUES:
            page = self._guide(langue)
            self.assertIn('100', page['desc'], langue)
            self.assertIn('100', page['body'], langue)

    def test_every_language_still_states_the_real_cap(self):
        """Naming 100 without the 50 would answer nothing.

        The whole reason 100% is out of reach is the cap, so a description
        that dropped it would be a hook with no payoff.
        """
        for langue in self.LANGUES:
            page = self._guide(langue)
            self.assertIn('50', page['desc'], langue)

    def test_the_descriptions_stay_short_enough_to_be_shown_whole(self):
        """Google truncates around 160 characters.

        The answer sits at the front for that reason; a description that grew
        past the limit would have its point cut off.
        """
        for langue in self.LANGUES:
            longueur = len(self._guide(langue)['desc'])
            self.assertLessEqual(longueur, 160, '%s: %s' % (langue, longueur))
            self.assertGreaterEqual(longueur, 90, langue)


class ADescriptionAnswersRatherThanAnnouncesTests(TestCase):
    """The failure this whole site kept repeating, in one guard.

    Item pages used to say "Dofus stats, effects, equip conditions and craft
    recipe": the shape of the page, not the item. Measured over 28 days, the
    encyclopedia took 122 clicks on 33 300 impressions -- 0.4 % -- while the
    Fandom wiki ranked above with a snippet that answered.

    A sentence that answers carries something specific: the item's own name,
    and a number. A sentence that announces carries neither, and reads the
    same whichever page it sits on. That is the whole test.
    """

    #: Un echantillon fixe : le tirage doit etre le meme d'une execution a
    #: l'autre, sinon un echec ne se reproduit pas.
    OBJETS = (44, 15699, 694, 26066, 7115)

    def _structure(self):
        from fashionistapulp.structure import get_structure
        return get_structure('dofus3')

    NAVIGATEUR = 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) Chrome/126.0'

    def _description(self, ankama_id):
        """Ce que la PAGE sert, pas ce qu'une fonction rend.

        Le constructeur de description prend des lignes de stats que la vue
        assemble ailleurs ; l'appeler a vide testerait une phrase que personne
        ne voit. La page rendue est la seule chose qu'un lecteur et un moteur
        recoivent vraiment.
        """
        import re
        from chardata.encyclopedia_view import get_item_link
        item = self._structure().get_item_by_ankama_id(ankama_id)
        self.assertIsNotNone(item, ankama_id)
        url = get_item_link(item.ankama_type, item.ankama_id, item.name,
                            game_version='dofus3')
        self.assertTrue(url, ankama_id)
        reponse = self.client.get(url, HTTP_ACCEPT_LANGUAGE='en',
                                  HTTP_USER_AGENT=self.NAVIGATEUR)
        self.assertEqual(reponse.status_code, 200, url)
        page = reponse.content.decode('utf-8')
        balise = re.search(r'<meta[^>]*name="description"[^>]*>', page)
        self.assertIsNotNone(balise, url)
        trouve = re.search(r'content="([^"]*)"', balise.group(0))
        self.assertIsNotNone(trouve, url)
        return item, trouve.group(1)

    def test_every_sampled_description_names_its_own_item(self):
        """A sentence that fits any page is a sentence about no page."""
        for ankama_id in self.OBJETS:
            item, desc = self._description(ankama_id)
            self.assertIn(item.name, desc, ankama_id)

    def test_every_sampled_description_carries_a_number(self):
        """The level, a stat, a count -- something a reader can check.

        This is what separates an answer from an announcement, and it is the
        cheapest signal of the difference: the old wording had no digit in it
        at all.
        """
        import re
        for ankama_id in self.OBJETS:
            _item, desc = self._description(ankama_id)
            self.assertTrue(re.search(r'[0-9]', desc),
                            '%s: %r' % (ankama_id, desc))

    def test_none_of_them_describes_the_page_instead_of_the_item(self):
        """The exact wording that cost 33 300 impressions their clicks.

        Kept verbatim rather than paraphrased: this is the sentence to
        recognise if it ever comes back, in this form or a close one.
        """
        interdits = ('stats, effects, equip conditions',
                     'Find every item', 'Discover builds',
                     'all the items in this Dofus set')
        for ankama_id in self.OBJETS:
            _item, desc = self._description(ankama_id)
            for phrase in interdits:
                self.assertNotIn(phrase, desc, '%s: %s' % (ankama_id, phrase))

    def test_they_stay_inside_what_a_result_shows(self):
        for ankama_id in self.OBJETS:
            _item, desc = self._description(ankama_id)
            self.assertLessEqual(len(desc), 165, '%s: %s' % (ankama_id, len(desc)))


class TheViewCleanupDoesNotHoldTheTableTests(TestCase):
    """This command now runs while the server is starting.

    Nothing had ever called it, so its first run in production has 156 914
    rows to remove. One statement of that size holds a lock on the table for
    its whole duration, and that duration lands inside the maintenance window
    of a deploy. Batches give the lock back between passes.
    """

    def _vues(self, combien, age_heures):
        from datetime import timedelta
        from django.utils import timezone
        import pickle as _pickle
        from django.contrib.auth.models import User
        from chardata.models import BuildView, Char
        from fashionistapulp.modelresult import ModelResultMinimal
        entree = {'options': {}, 'origin': 'generated', 'char_level': 200,
                  'base_stats_by_attr': {}, 'locked_equips': {}}
        proprio = User.objects.create_user(
            'menage%s' % age_heures, 'm%s@test.local' % age_heures, 'pw-42-x')
        build = Char.objects.create(
            name='Menage', char_name='m', char_class='Iop', char_build='b',
            level=200, minimum_stats=b'', minimum_crits=b'', stats_weight=b'',
            options=b'', inclusions=b'', exclusions=b'',
            minimal_solution=_pickle.dumps(ModelResultMinimal({}, entree, {})),
            link_shared=False, owner=proprio)
        crees = [BuildView.objects.create(build=build,
                                          ip_address='10.0.%d.%d'
                                          % (age_heures, i % 250))
                 for i in range(combien)]
        BuildView.objects.filter(pk__in=[v.pk for v in crees]).update(
            viewed_at=timezone.now() - timedelta(hours=age_heures))
        return build

    def _menage(self, taille_de_lot=None):
        from io import StringIO
        from django.core.management import call_command
        from chardata.management.commands import cleanup_old_views
        ancienne = cleanup_old_views.Command.TAILLE_DE_LOT
        if taille_de_lot:
            cleanup_old_views.Command.TAILLE_DE_LOT = taille_de_lot
        try:
            sortie = StringIO()
            call_command('cleanup_old_views', stdout=sortie)
            return sortie.getvalue()
        finally:
            cleanup_old_views.Command.TAILLE_DE_LOT = ancienne

    def test_it_clears_more_rows_than_one_batch_holds(self):
        """The case the single statement used to be: far more than a batch."""
        from chardata.models import BuildView
        self._vues(25, age_heures=30)
        sortie = self._menage(taille_de_lot=4)
        self.assertIn('25', sortie)
        self.assertEqual(0, BuildView.objects.count())

    def test_it_really_deletes_in_several_statements(self):
        """The mechanism, not the outcome.

        Written after the first version of this class passed unchanged against
        the single-statement command: both remove the same rows, so a test on
        what is left cannot see the difference. What the change is for is the
        lock, and the lock is held per statement -- so the statements are what
        has to be counted.
        """
        from django.db import connection
        from django.test.utils import CaptureQueriesContext
        self._vues(25, age_heures=30)
        with CaptureQueriesContext(connection) as requetes:
            self._menage(taille_de_lot=4)
        suppressions = [r['sql'] for r in requetes.captured_queries
                        if r['sql'].lstrip().upper().startswith('DELETE')]
        self.assertGreaterEqual(
            len(suppressions), 5,
            'twenty-five rows in batches of four must take more than one '
            'statement, and took %d' % len(suppressions))

    def test_it_leaves_the_rows_that_still_enforce_the_limit(self):
        from chardata.models import BuildView
        self._vues(6, age_heures=30)
        self._vues(4, age_heures=2)
        self._menage(taille_de_lot=2)
        # Les quatre du jour portent la limite une visite par adresse : les
        # perdre ferait recompter les memes lecteurs.
        self.assertEqual(4, BuildView.objects.count())

    def test_it_stops_instead_of_looping_forever(self):
        """The guard on the loop, not on the data.

        This command runs before Gunicorn. A filter that stopped matching what
        it deletes would spin here and the server would never come up, which
        is worse than leaving old rows behind.
        """
        from chardata.management.commands import cleanup_old_views
        self.assertLessEqual(cleanup_old_views.Command.PASSES_MAX, 10000)
        self.assertGreaterEqual(cleanup_old_views.Command.PASSES_MAX, 10)


class PaginationReachesEveryPageTests(TestCase):
    """Page 1 of the 99-page encyclopedia linked 2, 3, 4 and 99 and nothing
    else. The middle of the list was twelve clicks from the first page, and
    twelve hops still reached only 71 of the 99: every hop offered three new
    neighbours and the two ends it already had. Depth is how a crawler spends
    its budget, and those pages hold the items the site exists to show."""

    def _page(self, number, total):
        from types import SimpleNamespace
        return SimpleNamespace(number=number,
                               paginator=SimpleNamespace(num_pages=total))

    def _links(self, number, total):
        from chardata.pagination import pagination_items
        return {n for n in pagination_items(self._page(number, total))
                if n and n != number}

    def _distances(self, total):
        seen = {1: 0}
        edge = [1]
        while edge:
            nxt = []
            for here in edge:
                for there in self._links(here, total):
                    if there not in seen:
                        seen[there] = seen[here] + 1
                        nxt.append(there)
            edge = nxt
        return seen

    def test_every_page_is_three_clicks_from_the_first(self):
        for total in (99, 85, 100, 101, 250):
            distances = self._distances(total)
            missing = [n for n in range(1, total + 1) if n not in distances]
            self.assertFalse(
                missing,
                'over %d pages these are unreachable from page 1: %s'
                % (total, missing[:12]))
            worst = max(distances.values())
            self.assertLessEqual(
                worst, 3,
                'over %d pages the furthest page is %d clicks from the first; '
                'pages at that depth: %s'
                % (total, worst,
                   sorted(n for n, d in distances.items() if d == worst)[:8]))

    def test_short_lists_are_unchanged(self):
        # Nine pages of sets never reach a multiple of ten, so the stride adds
        # nothing there and the bar keeps the shape it had.
        self.assertEqual(self._links(1, 9), {2, 3, 4, 9})

    def test_gaps_mark_where_pages_were_dropped(self):
        # The old template printed the ellipsis at two fixed positions, which
        # stopped meaning anything as soon as the shown pages changed. A gap is
        # a fact about the list, so it is computed from it.
        from chardata.pagination import pagination_items
        rendered = pagination_items(self._page(50, 99))
        self.assertIsNotNone(rendered[0], 'a gap cannot open the bar')
        self.assertIsNotNone(rendered[-1], 'a gap cannot close the bar')
        numbers = [n for n in rendered if n]
        self.assertEqual(numbers, sorted(set(numbers)), 'pages must be unique '
                         'and in order')
        for before, after in zip(rendered, rendered[1:]):
            if before is None or after is None:
                continue
            self.assertEqual(after, before + 1,
                             'pages %d and %d are not consecutive and no gap '
                             'is marked between them' % (before, after))

    def test_the_encyclopedia_page_actually_renders_the_long_jumps(self):
        # The helper being right proves nothing about the page: the template
        # has to use it. This is the half that would have stayed silent.
        import re
        response = self.client.get('/encyclopedia/',
                                   HTTP_ACCEPT_LANGUAGE='en')
        self.assertEqual(response.status_code, 200)
        html = response.content.decode('utf-8', 'replace')
        linked = {int(n) for n in
                  re.findall(r'href="\?[^"]*page=(\d+)"', html)}
        if not linked:
            self.skipTest('this build has a single page of items')
        stride = max(n for n in linked if n % 10 == 0) if any(
            n % 10 == 0 for n in linked) else 0
        self.assertTrue(
            stride, 'page 1 links %s and no multiple of ten, so the long '
            'jumps are not on the page' % sorted(linked)[:8])


class AnUnknownThemeCookieStillGetsRealStylesheetsTests(SimpleTestCase):
    """The two theme cookies come from the visitor and become file names.

    set_theme has always sanitised them on the way in. Nothing sanitised them
    on the way out, so a `theme` cookie holding anything else made all eight
    stylesheet paths point at files that do not exist: the site came back with
    no styling at all, on every page, until the cookie was cleared. Renaming a
    theme would have done that to everyone who had visited before the rename.
    """

    STATIC = os.path.join(
        os.path.dirname(os.path.abspath(__file__)), 'static')

    def _request(self, **cookies):
        from django.test import RequestFactory
        request = RequestFactory().get('/')
        request.COOKIES.update(cookies)
        return request

    def test_an_invented_theme_falls_back_to_the_default(self):
        from chardata.themes import get_theme
        from fashionsite.settings import DEFAULT_THEME
        for value in ('bluetheme', '', '../../etc/passwd', 'LIGHTTHEME'):
            self.assertEqual(
                get_theme(self._request(theme=value)), DEFAULT_THEME,
                'the reader kept %r, which becomes a file name' % value)

    def test_the_three_real_themes_still_come_back_untouched(self):
        from chardata.themes import get_theme, ALLOWED_THEMES
        for value in sorted(ALLOWED_THEMES):
            self.assertEqual(get_theme(self._request(theme=value)), value)

    def test_an_invented_theme_still_names_stylesheets_that_exist(self):
        from chardata.themes import CSS_NAMES, get_css_for_theme, get_theme
        request = self._request(theme='bluetheme')
        sheets = get_css_for_theme(get_theme(request), request)
        missing = [sheets[name] for name in CSS_NAMES
                   if not os.path.isfile(os.path.join(
                       self.STATIC, sheets[name].replace('/', os.sep)))]
        self.assertEqual(
            missing, [], '%d of the %d stylesheets a page loads point at '
            'nothing, so it renders unstyled' % (len(missing), len(CSS_NAMES)))

    def test_an_invented_current_auto_still_names_stylesheets_that_exist(self):
        from chardata.themes import CSS_NAMES, get_css_for_theme
        request = self._request(theme='auto', current_auto='chartreuse')
        sheets = get_css_for_theme('auto', request)
        missing = [sheets[name] for name in CSS_NAMES
                   if not os.path.isfile(os.path.join(
                       self.STATIC, sheets[name].replace('/', os.sep)))]
        self.assertEqual(missing, [], 'the auto theme followed the cookie')

    def test_the_two_real_auto_values_still_come_back_untouched(self):
        from chardata.themes import CSS_NAMES, get_css_for_theme
        for value in ('lighttheme', 'darktheme'):
            request = self._request(theme='auto', current_auto=value)
            sheets = get_css_for_theme('auto', request)
            self.assertTrue(
                sheets[CSS_NAMES[0]].endswith('_%s.css' % value),
                'the reader dropped a value the writer allows: %r' % value)


class RetroBluffIsOneRollNotTwoHitsTests(SimpleTestCase):
    """Ankama on the Ecaflip's Bluff, in 1.29: "Le Bluff inflige aleatoirement
    des degats d'Air ou d'Eau."

    One of the two lands. The table listed both rows loose, so the model added
    them and scored 209 a cast where the game gives 104. Four other Retro
    spells carry several elemental rows that all DO land, and Ankama says so in
    as many words, so the shape alone never settled it: the generator names
    this one and re-reads the sentence before every rebuild.
    """

    def _bluff(self):
        from chardata.spell_combo import castable_spells
        for castable in castable_spells('Ecaflip', 200, 'retro'):
            if castable.spell.name == 'Bluff':
                return castable
        self.fail('the Retro Ecaflip has no spell named Bluff')

    def test_air_and_water_are_the_two_faces_of_one_roll(self):
        castable = self._bluff()
        self.assertEqual(
            2, len(castable.alternatives),
            'Bluff carries %d alternative(s); with one, its two rows are being '
            'added up' % len(castable.alternatives))
        for alternative in castable.alternatives:
            self.assertEqual(1, len(alternative),
                             'Bluff scores both elements at once')
        self.assertEqual(
            {'water', 'air'},
            {alt[0].element for alt in castable.alternatives})

    def test_the_spells_that_really_hit_twice_keep_both_rows(self):
        """The shape is not the rule: these land in every element they name."""
        from chardata.spell_combo import castable_spells
        for char_class, name in (('Cra', 'Fl\u00e8che Pers\u00e9cutrice'),
                                 ('Sadida', 'Feu de Brousse'),
                                 ('Ecaflip', 'Rekop')):
            found = [c for c in castable_spells(char_class, 200, 'retro')
                     if c.spell.name == name]
            self.assertTrue(found, '%s has no %r' % (char_class, name))
            castable = found[0]
            self.assertEqual(
                1, len(castable.alternatives),
                '%s was turned into a choice of element, and Ankama says it '
                'deals every one of them' % name)
            self.assertGreater(len(castable.hits), 1)

    def test_the_label_is_translated_everywhere(self):
        from django.utils import translation
        from chardata.spells_view import _localized_aggregate_label, _RANDOM_ELEMENT
        rendus = {}
        for langue in ('en', 'fr', 'es', 'pt', 'de'):
            with translation.override(langue):
                rendus[langue] = _localized_aggregate_label(_RANDOM_ELEMENT, 'retro')
        for langue, texte in rendus.items():
            self.assertTrue(texte, '%s renders nothing' % langue)
        self.assertEqual(
            len(set(rendus.values())), len(rendus),
            'two languages render the same string, so at least one catalog '
            'fell back to English: %s' % rendus)


class OnlyOneElementalCharacteristicIsGrantedTests(SimpleTestCase):
    """Two spells granted all four elemental characteristics at once.

    Ankama says one. Elemental Drain steals "selon l'etat elementaire sur
    l'ennemi cible", one state, and one cast credited 200 Strength,
    Intelligence, Chance AND Agility: 800 points. Alchemical Word buffs "selon
    le contenu" of a flask that holds one element, and came to 600. Both rows
    are dropped now, the way the Ecaflip's Roulette was, because the table
    cannot say which of the four the player will have.

    The spells that really do grant several are left alone, and this checks
    both halves: a later sweep must not generalise the exclusion.
    """

    def _castable(self, version, char_class, name):
        from chardata.spell_combo import castable_spells
        for castable in castable_spells(char_class, 200, version):
            if castable.spell.name == name:
                return castable
        self.fail('%s/%s has no spell named %r' % (version, char_class, name))

    ELEMENTAL = {'str', 'int', 'cha', 'agi'}

    def test_the_two_exclusive_ones_grant_none(self):
        for version in ('dofus3', 'beta'):
            for char_class, name in (('Huppermage', 'Elemental Drain'),
                                     ('Eniripsa', 'Alchemical Word')):
                deltas = self._castable(version, char_class, name).buff_deltas(1)
                granted = {k: v for k, v in deltas.items() if k in self.ELEMENTAL}
                self.assertEqual(
                    {}, granted,
                    '%s on %s hands the caster %s, and Ankama gives one of the '
                    'four' % (name, version, granted))

    def test_the_spells_that_really_stack_keep_theirs(self):
        """Sublimation says "cumulable 4 fois"; Reinforced Protection follows
        the caster's active armours, and several can be active."""
        for char_class, name in (('Huppermage', 'Sublimation'),
                                 ('Feca', 'Reinforced Protection')):
            deltas = self._castable('dofus3', char_class, name).buff_deltas(1)
            granted = {k: v for k, v in deltas.items() if k in self.ELEMENTAL}
            self.assertTrue(
                granted,
                '%s lost its characteristics; Ankama says it grants several'
                % name)


class ATimedOutSolveIsNotAProvenOptimumTests(SimpleTestCase):
    """`get_status() == 'Optimal'` does not mean the solver proved anything.

    PuLP's CBC reader maps a run stopped by its own time limit back onto
    LpStatusOptimal: in pulp/apis/coin_api.py, when CBC writes "Stopped on
    time - objective value X", get_status turns LpStatusNotSolved into
    LpStatusOptimal and records the truth in sol_status instead. Every solver
    in lpproblem.py runs with timeLimit=90, and fashion_action displays a set
    on that status string alone, so before this the site could not tell a
    closed gap from the best set found before the clock ran out, and said
    nothing either way.
    """

    def _solved(self):
        from fashionistapulp.lpproblem import LpProblem2
        problem = LpProblem2()
        problem.setup_variable('item', 'x', 0, 10)
        problem.init_objective_function()
        problem.add_to_of('item', 'x', 3)
        problem.finish_objective_function()
        problem.restriction_lt_eq(4, [(1, 'item', 'x')])
        problem.run()
        return problem

    def test_a_solve_that_closes_the_gap_is_proven(self):
        problem = self._solved()
        self.assertEqual('Optimal', problem.get_status())
        self.assertTrue(problem.solution_is_proven())
        self.assertEqual('Optimal Solution Found', problem.get_solution_status())

    def test_the_old_status_cannot_tell_a_timeout_apart(self):
        """The reason the second accessor has to exist at all."""
        from pulp import constants
        problem = self._solved()
        problem.pulp_lp.sol_status = constants.LpSolutionIntegerFeasible
        self.assertEqual(
            'Optimal', problem.get_status(),
            'if this ever stops saying Optimal on a stopped run, PuLP changed '
            'and the warning in fashion_action can be simplified')
        self.assertFalse(problem.solution_is_proven())
        self.assertEqual('Solution Found', problem.get_solution_status())

    def test_the_site_says_so_when_it_ran_out_of_time(self):
        from chardata import fashion_action

        class FauxChar(object):
            id = 4242
            game_version = 'dofus3'

        with self.assertLogs('chardata.fashion_action', level='WARNING') as pris:
            fashion_action._warn_if_unproven(FauxChar(), 'Optimal', False)
        self.assertIn('4242', pris.output[0])
        self.assertIn('not a proven optimum', pris.output[0])

    def test_it_stays_quiet_when_the_answer_was_proven(self):
        from chardata import fashion_action

        class FauxChar(object):
            id = 1
            game_version = 'dofus3'

        with self.assertNoLogs('chardata.fashion_action', level='WARNING'):
            fashion_action._warn_if_unproven(FauxChar(), 'Optimal', True)
            fashion_action._warn_if_unproven(FauxChar(), 'Infeasible', False)


class TheCompareTrayCanActuallyBeEmptiedTests(SimpleTestCase):
    """Clearing the tray has to clear it, even for a reader who predates the
    per-version split.

    The tray moved from one shared key to `ffCompareTray:<base>` on 2026-09-07,
    and load() fell back to the old key whenever the new list was EMPTY. Since
    save() only ever writes the versioned key, Clear wrote [] and the next
    render read the old list straight back: for anyone who had used the tray in
    the two and a half months it shipped unversioned, it could never be emptied
    again. The test that came with the split only ever added builds, which is
    why it stayed green.
    """

    def _drive(self, actions):
        """Run the real compare_tray.js under node and return its stored tray."""
        node = shutil.which('node')
        if node is None:
            self.skipTest('node is not installed')
        js_path = os.path.join(os.path.dirname(__file__), 'static', 'chardata',
                               'compare_tray.js')
        with open(js_path, encoding='utf-8') as handle:
            source = handle.read()
        driver = r"""
var vm = require('vm');
var data = {};
global.localStorage = {
  getItem: function (key) { return Object.prototype.hasOwnProperty.call(data, key) ? data[key] : null; },
  setItem: function (key, value) { data[key] = String(value); }
};
global.window = {
  COMPARE_TRAY_CONFIG: {apiBase: '/retro', i18n: {}},
  matchMedia: function () { return {matches: false}; },
  addEventListener: function () {},
  location: {href: ''}
};
var fakeClassList = {add: function () {}, remove: function () {}, toggle: function () {}};
global.document = {
  readyState: 'complete',
  body: {appendChild: function () {}},
  createElement: function () { return {classList: fakeClassList}; },
  getElementById: function () { return null; },
  addEventListener: function () {}
};
global.setTimeout = function () { return 1; };
global.clearTimeout = function () {};
// A reader from before the split: their tray lives under the shared key only.
localStorage.setItem('ffCompareTray', JSON.stringify([
  {id: '2', base: '/retro'},
  {id: '5', base: '/retro'}
]));
vm.runInThisContext(source);
var tray = window.FashionCompareTray;
ACTIONS
// Adding one build afterwards is how we read the tray back: whatever is
// stored now is what the next render would show.
tray.add({id: '7', name: 'Fresh build', base: '/retro'});
console.log(JSON.stringify(JSON.parse(data['ffCompareTray:/retro']).map(function (b) { return b.id; })));
"""
        driver = driver.replace('ACTIONS', actions)
        with tempfile.NamedTemporaryFile('w', suffix='.js', encoding='utf-8',
                                         delete=False) as handle:
            handle.write('var source = %s;\n%s' % (json.dumps(source), driver))
            name = handle.name
        try:
            done = subprocess.run([node, name], capture_output=True, text=True)
        finally:
            os.unlink(name)
        self.assertEqual(done.returncode, 0, done.stderr[-800:])
        return json.loads(done.stdout)

    def test_clear_empties_a_tray_that_predates_the_split(self):
        self.assertEqual(
            ['7'], self._drive('tray.clear();'),
            'Clear left the old builds in the tray, so the reader cannot empty '
            'it at all')

    def test_removing_the_last_build_does_not_bring_them_all_back(self):
        self.assertEqual(
            ['7'], self._drive("tray.remove('2'); tray.remove('5');"),
            'removing the last build resurrected the whole legacy list')

    def test_a_tray_that_was_never_touched_is_still_carried_over(self):
        """The fallback still has to work: this is a migration, not a wipe."""
        self.assertEqual(['2', '5', '7'], self._drive(''))


class TouchStillHasItsGermanNamesTests(SimpleTestCase):
    """Touch dropped German, and asking for it returns English.

    config.json answers serverLanguages ["en", "es", "fr", "pt"] and
    failoverLanguage "en", so the data API hands back English for `de` with no
    error and no marker. A rebuild that trusts it overwrites every German name
    with its English text: on 2026-09-08 that was 16 190 of them, and every
    step of the pipeline still reported ok.

    The scrapers now read serverLanguages before refreshing a language. This
    guards the outcome rather than that plumbing: if the German files ever go
    flat again, whatever the cause, this is what says so.
    """

    RAW = os.path.join(
        os.path.dirname(os.path.dirname(os.path.dirname(os.path.abspath(__file__)))),
        'itemscraper', 'touch_raw')

    #: Measured on the restored files, 2026-09-08. Well under the real counts
    #: (2202 monsters, 13145 items) so Ankama adding or renaming things cannot
    #: trip it, but far above the zero a flattened file would give.
    PLANCHER = {'Monsters': 1500, 'Items': 9000, 'ItemSets': 200}

    def _noms(self, table, langue):
        chemin = os.path.join(self.RAW, '%s_%s.json' % (table, langue))
        if not os.path.isfile(chemin):
            self.skipTest('%s is not in this checkout' % chemin)
        with open(chemin, encoding='utf-8') as handle:
            return {cle: (rec.get('nameId') or '')
                    for cle, rec in json.load(handle).items()}

    def test_the_german_touch_names_are_not_the_english_ones(self):
        for table, plancher in sorted(self.PLANCHER.items()):
            allemand = self._noms(table, 'de')
            anglais = self._noms(table, 'en')
            communs = set(allemand) & set(anglais)
            distincts = sum(1 for cle in communs
                            if allemand[cle] and allemand[cle] != anglais[cle])
            self.assertGreaterEqual(
                distincts, plancher,
                '%s_de.json carries only %d names that differ from English, '
                'out of %d shared ids. Touch answers a language it no longer '
                'serves with English, so this is what a rebuild that ignored '
                'serverLanguages looks like.'
                % (table, distincts, len(communs)))

    def test_a_known_monster_still_reads_in_german(self):
        """Three names anyone can check against the game."""
        allemand = self._noms('Monsters', 'de')
        for monster_id, attendu in (('31', 'Blaue Larve'),
                                    ('36', 'Fresssack'),
                                    ('37', 'Krachler')):
            self.assertEqual(
                attendu, allemand.get(monster_id),
                'monster %s should still read %r in German' % (monster_id, attendu))


class TheRetroAssetWatchSeesAddedFilesTests(SimpleTestCase):
    """The watch it replaces could not, and that was most of what moved.

    Until 2026-09-09 the Retro visual assets were watched through nine
    hand-picked names, looked up one by one. A file that did not exist before
    was never one of the keys, so an addition was invisible by construction.
    Replayed over this repo's four Retro build transitions, the watch set now
    reports 48 movements for 1.48.21 to 1.49.0 (30 artworks added, 10 changed,
    8 items added), 2 for 1.49.0 to 1.49.1, 1 for 1.49.1 to 1.49.2 and nothing
    for 1.49.2 to 1.49.3. The old sample fired on 0 of 9 in the first three.

    These run on synthetic entry sets: the point is the shape of the
    comparison, and a test that downloads a 6.9 MB manifest is a test that
    fails when Ankama is down.
    """

    def _watch(self):
        import importlib.util
        chemin = os.path.join(
            os.path.dirname(os.path.dirname(os.path.dirname(os.path.abspath(__file__)))),
            'itemscraper', 'check_game_versions.py')
        if not os.path.isfile(chemin):
            self.skipTest('check_game_versions.py is not in this checkout')
        spec = importlib.util.spec_from_file_location('check_game_versions', chemin)
        module = importlib.util.module_from_spec(spec)
        spec.loader.exec_module(module)
        return module

    CLIP = 'resources/app/retroclient/clips/%s'

    def test_an_added_clip_is_reported(self):
        watch = self._watch()
        avant = {self.CLIP % 'items/1/1.swf': 'aaa 10'}
        apres = dict(avant)
        apres[self.CLIP % 'artworks/big/1234.swf'] = 'bbb 20'
        report = watch.retro_asset_diff(avant, apres)
        self.assertEqual(['artworks'], sorted(report))
        self.assertEqual([self.CLIP % 'artworks/big/1234.swf'],
                         report['artworks']['added'])

    def test_a_removed_clip_is_reported(self):
        watch = self._watch()
        avant = {self.CLIP % 'items/1/1.swf': 'aaa 10',
                 self.CLIP % 'sprites/31.swf': 'bbb 20'}
        apres = {self.CLIP % 'items/1/1.swf': 'aaa 10'}
        report = watch.retro_asset_diff(avant, apres)
        self.assertEqual([self.CLIP % 'sprites/31.swf'],
                         report['sprites']['removed'])

    def test_a_changed_clip_is_reported(self):
        watch = self._watch()
        name = self.CLIP % 'spells/icons/up/101.swf'
        report = watch.retro_asset_diff({name: 'aaa 10'}, {name: 'ccc 10'})
        self.assertEqual([name], report['spells']['changed'])

    def test_an_untouched_set_reports_nothing(self):
        watch = self._watch()
        entries = {self.CLIP % 'items/1/1.swf': 'aaa 10'}
        self.assertEqual({}, watch.retro_asset_diff(entries, dict(entries)))

    def test_the_digest_does_not_depend_on_insertion_order(self):
        watch = self._watch()
        un = {self.CLIP % 'items/1/1.swf': 'aaa 10',
              self.CLIP % 'sprites/31.swf': 'bbb 20'}
        deux = {self.CLIP % 'sprites/31.swf': 'bbb 20',
                self.CLIP % 'items/1/1.swf': 'aaa 10'}
        self.assertEqual(watch.retro_asset_digest(un),
                         watch.retro_asset_digest(deux))
        trois = dict(un)
        trois[self.CLIP % 'items/1/1.swf'] = 'zzz 10'
        self.assertNotEqual(watch.retro_asset_digest(un),
                            watch.retro_asset_digest(trois))

    def test_the_subtrees_no_renderer_reads_stay_out(self):
        """sprites/accessories and sprites/chevauchor moved in 1.49.0 and
        1.49.1 and nothing here draws them, so they must not raise an alarm."""
        watch = self._watch()
        for name, attendu in (
                ('items/1/1.swf', 'items'),
                ('spells/icons/up/101.swf', 'spells'),
                ('artworks/big/31.swf', 'artworks'),
                ('sprites/31.swf', 'sprites'),
                ('sprites/accessories/12.swf', 'other'),
                ('sprites/chevauchor/7.swf', 'other')):
            self.assertEqual(attendu, watch.retro_asset_family(self.CLIP % name),
                             name)


class EverySpellIconOnDiskIsAskedForByItsRealNameTests(SimpleTestCase):
    """Retro and Touch file their spell icons under the FRENCH name.

    Both scrapers say so in their own docstrings, and this view said the
    opposite: it asked for the English name on every version. Measured
    2026-09-09, that missed 242 of 252 Retro spells and 303 of 330 Touch ones,
    and 251 of those icons were sitting on disk under a name nobody asked for.
    Every Retro and Touch spell page 404ed its icons, in all five languages.

    This guards the outcome, not the rule: if a scraper ever changes the
    language it files under, or a version is added, this goes red rather than
    the pages going quietly blank.
    """

    RACINE = os.path.join(os.path.dirname(os.path.abspath(__file__)),
                          'static', 'chardata', 'spells')

    def _fichiers(self, version):
        dossier = self.RACINE if version == 'dofus3' else os.path.join(
            self.RACINE, version)
        if not os.path.isdir(dossier):
            self.skipTest('no spell icons for %s in this checkout' % version)
        return {nom[:-4] for nom in os.listdir(dossier) if nom.endswith('.png')}

    def _reference(self, version):
        chemin = os.path.join(os.path.dirname(os.path.abspath(__file__)),
                              'spell_reference', '%s.json' % version)
        if not os.path.isfile(chemin):
            self.skipTest('no spell reference for %s' % version)
        with open(chemin, encoding='utf-8') as handle:
            return json.load(handle)

    def test_no_icon_on_disk_is_asked_for_under_a_name_it_does_not_have(self):
        from chardata.spells_view import _reference_icon_name
        from fashionistapulp.reserved_filenames import safe_asset_stem
        from fashionistapulp.game_versions import version_keys
        verifiees = 0
        for version in version_keys():
            fichiers = self._fichiers(version)
            demandes = set()
            for spells in self._reference(version).values():
                for spell in spells:
                    noms = spell.get('name') or {}
                    montre = (noms.get('fr') or noms.get('en')
                              if isinstance(noms, dict) else noms) or ''
                    if not montre:
                        continue
                    demandes.add(safe_asset_stem(
                        _reference_icon_name(spell, montre, version)))
            orphelines = fichiers - demandes
            with self.subTest(version=version):
                # An icon nobody asks for is either a spell that left the game
                # or, as here, a naming convention the view got wrong.
                self.assertLessEqual(
                    len(orphelines), len(fichiers) // 10,
                    '%s: %d of its %d spell icons are never asked for, e.g. %s'
                    % (version, len(orphelines), len(fichiers),
                       sorted(orphelines)[:4]))
            verifiees += 1
        self.assertGreaterEqual(verifiees, 5, 'only %d versions checked' % verifiees)

    def test_the_icon_name_does_not_follow_the_reader(self):
        """Whatever the language, one version asks for one file."""
        from chardata.spells_view import _reference_icon_name
        entree = {'name': {'en': 'Feca Shield', 'fr': 'Bouclier Feca',
                           'es': 'Escudo Feca'}}
        for version, attendu in (('dofus3', 'Feca Shield'),
                                 ('retro', 'Bouclier Feca'),
                                 ('touch', 'Bouclier Feca')):
            self.assertEqual(attendu,
                             _reference_icon_name(entree, 'peu importe', version),
                             version)

    def test_a_name_two_class_spells_share_is_split_by_id_on_every_version(self):
        from chardata.spells_view import _reference_icon_name
        for version, name, keeper, other in (('dofus3', 'Collapse', 13352, 23736),
                                             ('beta', 'Wandering', 13356, 14604),
                                             ('dofus2', 'Compass', 13860, 13877)):
            noms = {'en': name, 'fr': 'peu importe'}
            with self.subTest(version=version):
                self.assertEqual(name, _reference_icon_name(
                    {'id': keeper, 'name': noms}, name, version))
                self.assertEqual('%s (%s)' % (name, other), _reference_icon_name(
                    {'id': other, 'name': noms}, name, version))


class InventoryScriptHarness(SimpleTestCase):
    """The inventory page's JavaScript lives inside a Django template, so the
    only way to test it is to cut it out and run it under node.

    Two things make that honest rather than a hack. The script block carries no
    {% %} tag at all and its seventeen {{ }} all sit inside string literals, so
    the raw block is already valid JavaScript; and no literal in the functions
    extracted below contains a brace, which is what lets the brace counter
    work. Both are asserted, not assumed.
    """

    GABARIT = os.path.join(os.path.dirname(__file__), 'templates', 'chardata',
                           'inventory.html')

    def _source(self):
        return io.open(self.GABARIT, encoding='utf-8').read()

    def _script_block(self):
        source = self._source()
        start = source.rindex('<script>') + len('<script>')
        return source[start:source.index('</script>', start)]

    @staticmethod
    def _extract(source, nom):
        """The named function, by brace matching."""
        debut = source.index('function %s(' % nom)
        ouvrante = source.index('{', debut)
        profondeur = 0
        for position in range(ouvrante, len(source)):
            if source[position] == '{':
                profondeur += 1
            elif source[position] == '}':
                profondeur -= 1
                if profondeur == 0:
                    return source[debut:position + 1]
        raise AssertionError('unbalanced braces in %s' % nom)

    def _node(self, script):
        """Run the script and return its stdout, or skip if node is missing."""
        node = shutil.which('node')
        if node is None:
            self.skipTest('node not installed')
        dossier = tempfile.mkdtemp()
        try:
            chemin = os.path.join(dossier, 'piece.js')
            io.open(chemin, 'w', encoding='utf-8').write(script)
            sortie = subprocess.run([node, chemin], capture_output=True,
                                    text=True, encoding='utf-8', timeout=60)
            self.assertEqual(0, sortie.returncode, sortie.stderr)
            return sortie.stdout
        finally:
            shutil.rmtree(dossier, ignore_errors=True)


class InventoryScriptParsesTests(InventoryScriptHarness):
    """A syntax error in this block silently kills the whole inventory page,
    and the Python suite would stay green: it never runs the JavaScript. This
    was the first test of any kind over the screenshot reader."""

    def test_the_inventory_script_is_valid_javascript(self):
        node = shutil.which('node')
        if node is None:
            self.skipTest('node not installed')
        bloc = self._script_block()
        self.assertNotIn('{%', bloc,
                         'a template tag would stop this block being JS')
        dossier = tempfile.mkdtemp()
        try:
            chemin = os.path.join(dossier, 'inventory.js')
            io.open(chemin, 'w', encoding='utf-8').write(bloc)
            sortie = subprocess.run([node, '--check', chemin],
                                    capture_output=True, text=True,
                                    encoding='utf-8', timeout=60)
            self.assertEqual(0, sortie.returncode, sortie.stderr)
        finally:
            shutil.rmtree(dossier, ignore_errors=True)


class ScreenshotRangeWarningTests(InventoryScriptHarness):
    """A reading the chosen item cannot support is shown, never dropped and
    never silently kept.

    Bounds are not a rejection: forgemagie legitimately pushes a roll over its
    maximum and can sacrifice one under its minimum, so only the player knows.
    What the site can say is that the reader claimed 476 on an item that rolls
    20 to 40. Where the item carries no range there is nothing to check and the
    row is left alone, which is the case for 0.4 % (Wakfu) to 35.8 % (Touch) of
    items.
    """

    GABARIT_MODELE = u"""
%(fonction)s
var ocrOutOfRange = 'range {min} to {max}';
var ocrItemSelect = {value: '7'};
var ocrCandidates = {'7': {stats: [
    {key: 'str', min: 20, value: 40},
    {key: 'vit', min: null, value: 100}
]}};
function fausseLigne() {
    return {classList: {marques: [],
        add: function (c) { if (this.marques.indexOf(c) < 0) this.marques.push(c); },
        remove: function (c) { this.marques = this.marques.filter(function (x) { return x !== c; }); }}};
}
var ocrStatInputs = %(entrees)s;
var ocrStatWarnings = {};
Object.keys(ocrStatInputs).forEach(function (key) {
    ocrStatWarnings[key] = {line: fausseLigne(), text: {style: {}, textContent: ''}};
});
refreshOcrRangeWarnings();
var sortie = {};
Object.keys(ocrStatWarnings).forEach(function (key) {
    sortie[key] = {affiche: ocrStatWarnings[key].text.style.display,
                   texte: ocrStatWarnings[key].text.textContent,
                   marques: ocrStatWarnings[key].line.classList.marques};
});
console.log(JSON.stringify(sortie));
"""

    def _juge(self, entrees):
        fonction = self._extract(self._source(), 'refreshOcrRangeWarnings')
        self.assertNotIn('{min}', fonction.split('replace')[0],
                         'the placeholder must come from the label, not the code')
        script = self.GABARIT_MODELE % {'fonction': fonction,
                                        'entrees': json.dumps(entrees)}
        return json.loads(self._node(script))

    def test_a_roll_the_item_cannot_have_is_flagged_with_its_range(self):
        """476 is what the old parser produced from a misread "57 a 76"."""
        verdict = self._juge({'str': {'value': '476'}})
        self.assertEqual('block', verdict['str']['affiche'])
        self.assertEqual('range 20 to 40', verdict['str']['texte'])
        self.assertIn('inv-ocr-row-suspect', verdict['str']['marques'])

    def test_an_ordinary_roll_says_nothing(self):
        verdict = self._juge({'str': {'value': '30'}})
        self.assertEqual('none', verdict['str']['affiche'])
        self.assertEqual([], verdict['str']['marques'])

    def test_the_bounds_themselves_are_ordinary(self):
        for valeur in ('20', '40'):
            with self.subTest(valeur=valeur):
                verdict = self._juge({'str': {'value': valeur}})
                self.assertEqual('none', verdict['str']['affiche'])

    def test_an_overmage_is_flagged_but_not_refused(self):
        """Over the maximum is legal and only the player knows, so the wording
        asks them to check rather than announcing an error, and the value is
        left in the field."""
        verdict = self._juge({'str': {'value': '45'}})
        self.assertEqual('block', verdict['str']['affiche'])

    def test_a_stat_with_no_known_range_is_left_alone(self):
        """Inventing a bound for the third of items that carry none would be
        worse than checking nothing."""
        verdict = self._juge({'vit': {'value': '99999'}})
        self.assertEqual('none', verdict['vit']['affiche'])

    def test_a_stat_the_item_does_not_have_is_left_alone(self):
        """An exo puts a stat on an item that never lists it."""
        verdict = self._juge({'agi': {'value': '400'}})
        self.assertEqual('none', verdict['agi']['affiche'])


class ScreenshotStatParserNeverInventsANumberTests(InventoryScriptHarness):
    """The screenshot reader used to turn an unreadable line into a number.

    parseStatLine strips a leading junk group on purpose, because the stat icon
    is often read as a digit: "4 50 Force" really is 50. But the same rule used
    to fire on three groups or more and JOIN them, so a range whose separator
    was misread came out as a single large number. The range guard only knows
    the separators a, a-grave, to and bis, so "57 a-grave 76 Force" read as
    "57 4 76 Force" produced 476, and "3 4 5 60 Force" produced 4560. Those
    values do not stop there: parse_custom_stats clamps only to
    [-9999, 99999] and get_inventory_stat_overrides turns them into solver
    stat overrides, so the solver optimised around a roll the item never had.

    The parser lives in a Django template, so it is extracted and run under
    node. That is uglier than importing it, but the alternative is no test at
    all: this file had none for any part of the screenshot reader.
    """

    LEXIQUE = {'force': 'str', 'vitalite': 'vit'}

    def _parse(self, lines):
        source = self._source()
        morceaux = [self._extract(source, 'ocrNormalize'),
                    self._extract(source, 'parseStatLine')]
        for morceau in morceaux:
            self.assertTrue(morceau.endswith('}'), morceau[-40:])
        self.assertIn('return key ?', morceaux[1])
        script = '\n'.join(morceaux) + (
            '\nconst lexicon = %s;\n'
            'console.log(JSON.stringify(%s.map('
            'l => parseStatLine(l, lexicon))));\n'
            % (json.dumps(self.LEXIQUE), json.dumps(lines)))
        return json.loads(self._node(script))

    def test_a_line_nobody_can_read_comes_back_unread(self):
        lignes = [u'57 \u00e0 76 Force', u'57 4 76 Force', u'3 4 5 60 Force']
        self.assertEqual([None, None, None], self._parse(lignes))

    def test_the_stat_icon_read_as_a_digit_is_still_stripped(self):
        """The behaviour the joining rule existed for, which must survive."""
        self.assertEqual([{'key': 'str', 'value': 50},
                          {'key': 'str', 'value': 38},
                          {'key': 'str', 'value': -20}],
                         self._parse([u'4 50 Force', u'38 Force',
                                      u'-20 Force']))

    def test_thousands_groups_are_still_one_number(self):
        self.assertEqual([{'key': 'vit', 'value': 1000},
                          {'key': 'vit', 'value': 1234567}],
                         self._parse([u'1 000 Vitalite',
                                      u'1 234 567 Vitalite']))


class ScreenshotRangeGuardHasSomethingToCheckTests(SimpleTestCase):
    """The screenshot reader flags a roll the chosen item cannot support, and
    it can only do that where the item carries a roll range.

    read_stats_of_item_table says "only the versions built by get_equipments3
    carry the roll range". Measured 2026-09-09 against the six shipped item
    databases, that comment is wrong: all six carry ranges, on 70.1 % (Retro)
    to 100.0 % (Wakfu) of their stats. The guard is therefore live on every
    version, which is worth asserting rather than assuming: a data rebuild that
    dropped the min_value and max_value columns would switch the guard off
    everywhere and no other test would notice, because a guard that never fires
    breaks nothing.

    The floor is set well under each measurement so an ordinary content patch
    does not fail the suite. It is there to catch a collapse, not a drift.
    """

    #: version -> percentage of item stats carrying a range, measured
    #: 2026-09-09. The floor asserted is this minus 10 points.
    MESURE = {'dofus3': 80.5, 'beta': 80.4, 'dofus2': 83.3,
              'retro': 70.1, 'touch': 81.1, 'wakfu': 100.0}

    @staticmethod
    def _couverture(version):
        from fashionistapulp.fashionista_config import get_items_db_path
        from fashionistapulp.structure import get_structure
        if not os.path.exists(get_items_db_path(version)):
            return None
        structure = get_structure(version)
        total = 0
        avec = 0
        for item in structure.items_dict.values():
            total += len(item.stats)
            avec += len(getattr(item, 'stat_ranges', None) or {})
        return (structure, total, avec)

    def test_every_version_still_carries_roll_ranges(self):
        for version, mesure in self.MESURE.items():
            with self.subTest(version=version):
                couverture = self._couverture(version)
                if couverture is None:
                    self.skipTest('no %s database' % version)
                _structure, total, avec = couverture
                self.assertGreater(total, 0, '%s has no item stats' % version)
                pourcent = 100.0 * avec / total
                self.assertGreaterEqual(
                    pourcent, mesure - 10.0,
                    '%s: %.1f %% of stats carry a range, measured %.1f %% on '
                    '2026-09-09. Under this floor the screenshot range guard '
                    'stops firing.' % (version, pourcent, mesure))

    def test_the_payload_hands_the_range_to_the_browser(self):
        """The guard reads stat.min and stat.value out of the search payload,
        so the range has to survive _item_payload, not merely exist in the
        database."""
        from chardata.forgemagie_view import _item_payload
        from fashionistapulp.structure import get_structure
        structure = get_structure('dofus3')
        avec_fourchette = None
        for item in structure.items_dict.values():
            if getattr(item, 'stat_ranges', None) and item.stats:
                avec_fourchette = item
                break
        self.assertIsNotNone(avec_fourchette, 'no dofus3 item carries a range')
        payload = _item_payload(structure, avec_fourchette, 'en')
        bornes = [stat for stat in payload['stats']
                  if stat.get('min') is not None]
        self.assertTrue(bornes, 'payload dropped every range for %s'
                        % avec_fourchette.name)
        for stat in bornes:
            self.assertIsNotNone(stat.get('value'), stat)
            self.assertIsInstance(stat['min'], int, stat)


class InventorySearchReachesEveryItemTypeTests(TestCase):
    """My Inventory reused the workbench's item search, which only offers the
    eight forgeable types, so whole families were unreachable from its search
    box AND from its screenshot reader.

    Measured 2026-09-09, the types the widened pool adds back: 775 items on
    Dofus 3 (455 pets, 320 dofus), 779 on the beta, 746 on Touch, 463 on
    Dofus 2, 307 on Retro. Every one of them has its icon on disk, 100 % on
    all five versions, so they draw rather than showing a question mark.
    """

    PET = 'Air Bwak'
    DOFUS = 'Adamantin'

    def _noms(self, **params):
        resp = self.client.get('/forgemagie/items/', params)
        self.assertEqual(resp.status_code, 200)
        return [entry['name'] for entry in resp.json()['items']]

    def test_the_workbench_still_only_offers_what_it_can_forge(self):
        """A pet cannot be maged, so proposing one there would be a lie."""
        self.assertEqual([], self._noms(q=self.PET))
        self.assertEqual([], self._noms(q=self.DOFUS))

    def test_the_inventory_reaches_a_pet_and_a_dofus(self):
        self.assertIn(self.PET, self._noms(q=self.PET, all_types='1'))
        self.assertIn(self.DOFUS, self._noms(q=self.DOFUS, all_types='1'))

    def test_the_widened_pool_still_finds_a_forgeable_item(self):
        """Widening must add, never replace."""
        self.assertTrue(self._noms(q='Rhineetle Ring', all_types='1'))

    def test_every_dofus_version_reaches_all_ten_types(self):
        from chardata.forgemagie_view import _search_level, _search_types
        from fashionistapulp.fashionista_config import get_items_db_path
        from fashionistapulp.structure import get_structure
        for version in ('dofus3', 'beta', 'dofus2', 'retro', 'touch'):
            with self.subTest(version=version):
                if not os.path.exists(get_items_db_path(version)):
                    self.skipTest('no %s database' % version)
                structure = get_structure(version)
                types = _search_types(structure, True)
                self.assertIn('Pet', types)
                self.assertIn('Dofus', types)
                self.assertEqual(10, len(types), types)

    def test_the_level_comes_from_the_version_not_from_a_constant(self):
        """types is cumulative, so its top level holds everything. Every Dofus
        version stops at 200 and the hardcoded 200 was right for them; Wakfu
        goes to 245, where it hid 1487 of 7617 items."""
        from chardata.forgemagie_view import _search_level
        from fashionistapulp.fashionista_config import get_items_db_path
        from fashionistapulp.structure import get_structure
        self.assertEqual(200, _search_level(get_structure('dofus3')))
        if os.path.exists(get_items_db_path('wakfu')):
            structure = get_structure('wakfu')
            niveau = _search_level(structure)
            self.assertGreater(niveau, 200)
            atteignables = sum(len(structure.types[niveau][type_name])
                               for type_name in structure.types[niveau])
            self.assertEqual(len(structure.items_dict), atteignables)


class ItemNameSurvivesAMisreadCharacterTests(TestCase):
    """The item search matched by exact substring, so one character read wrong
    failed against all 3826 candidates at once and the screenshot reader said
    "item not recognized" for a name it had almost perfectly read.

    It now falls back to the nearest name, but only when that name is clearly
    nearer than every other. Measured 2026-09-09 on the French names of three
    versions: 97.3 to 97.6 % right at one substitution, 93.8 to 94.6 % at one
    deletion, and **0.00 % naming the wrong item** in all eighteen cells. The
    rest is silence, which is what the page did before.
    """

    def _noms(self, requete):
        resp = self.client.get('/forgemagie/items/',
                               {'q': requete, 'all_types': '1'})
        self.assertEqual(resp.status_code, 200)
        return [entry['name'] for entry in resp.json()['items']]

    def test_one_wrong_character_still_finds_the_item(self):
        """"Rhineetle" read as "Rhlneetle": the exact test failed on every
        candidate, so the reader got nothing at all."""
        self.assertEqual([], self._exact('Rhlneetle Ring'))
        self.assertIn('Rhineetle Ring', self._noms('Rhlneetle Ring'))

    def _exact(self, requete):
        """What the old substring-only search would have returned."""
        from chardata.forgemagie_view import _normalized_text
        from fashionistapulp.structure import get_structure
        structure = get_structure('dofus3')
        besoin = _normalized_text(requete)
        trouves = []
        for item in structure.items_dict.values():
            nom = structure.get_item_name_in_language(item, 'en')
            if besoin in _normalized_text('%s %s' % (nom, item.or_name or '')):
                trouves.append(nom)
        return trouves

    def test_a_missing_character_still_finds_the_item(self):
        self.assertIn('Rhineetle Ring', self._noms('Rhineetle Rng'))

    def test_an_exact_name_is_untouched(self):
        self.assertIn('Rhineetle Ring', self._noms('Rhineetle Ring'))

    def test_a_query_too_short_is_never_guessed_at(self):
        """Two or three letters are someone typing, not a name being read, and
        the ceiling would let them reach far too many items."""
        from chardata.forgemagie_view import _NAME_MIN_QUERY
        self.assertEqual(5, _NAME_MIN_QUERY)
        self.assertEqual([], self._noms('zzzz'))

    def test_nonsense_is_refused_rather_than_approximated(self):
        self.assertEqual([], self._noms('qqqqzzzzwwww'))


class ClosestNameRefusesWhenUnsureTests(SimpleTestCase):
    """The guard itself, away from the view: a winner is only returned when it
    is clearly better than its runner-up."""

    POOL = [('air bwak', 1, 'Air Bwak', 'Pet'),
            ('air bwork', 2, 'Air Bwork', 'Pet'),
            ('adamantin', 3, 'Adamantin', 'Dofus')]

    def _plus_proche(self, requete):
        from chardata.forgemagie_view import _closest_pool_entry
        entry = _closest_pool_entry(requete, self.POOL)
        return None if entry is None else entry[2]

    def test_a_lone_near_name_is_returned(self):
        self.assertEqual('Adamantin', self._plus_proche('adamantln'))

    def test_two_names_equally_near_give_silence(self):
        """"air bwak" and "air bwork" are one edit apart from each other, so a
        misread that lands between them names neither. A nearest neighbour
        alone would have picked one with total confidence."""
        self.assertIsNone(self._plus_proche('air bwok'))

    def test_an_exact_name_wins_even_with_a_close_sibling(self):
        self.assertEqual('Air Bwak', self._plus_proche('air bwak'))

    def test_nothing_within_the_ceiling_gives_silence(self):
        self.assertIsNone(self._plus_proche('zzzzzzzzz'))

    def test_the_search_band_is_wider_than_the_ceiling(self):
        """Searching at the ceiling clamps the runner-up to the winner's own
        value, the gap becomes unreachable, and everything past one error goes
        silent. That looks like a verdict on the method and is a verdict on
        the arithmetic."""
        from chardata.forgemagie_view import _NAME_MAX_EDITS, _NAME_MIN_GAP
        self.assertGreater(_NAME_MAX_EDITS + _NAME_MIN_GAP - 1,
                           _NAME_MAX_EDITS)

    def test_the_distance_is_a_real_edit_distance(self):
        from chardata.forgemagie_view import _bounded_edit_distance
        for premier, second, attendu in (('chat', 'chat', 0),
                                         ('chat', 'chats', 1),
                                         ('chat', 'chien', 3),
                                         ('', 'abc', 3)):
            with self.subTest(premier=premier, second=second):
                self.assertEqual(attendu,
                                 _bounded_edit_distance(premier, second, 9))

    def test_the_ceiling_stops_the_work_early(self):
        """A distance past the ceiling is reported as ceiling + 1, not
        computed exactly: the caller only ever compares it to the ceiling."""
        from chardata.forgemagie_view import _bounded_edit_distance
        self.assertEqual(3, _bounded_edit_distance('chat', 'chien', 2))


class PastedTextNeedsNoModelTests(InventoryScriptHarness):
    """Reading a screenshot pulls a 2 MB model from a CDN into the reader's
    browser. Reading text costs nothing, and everything downstream never cared
    where the text came from, so the same pipeline now has a second entrance.

    The hint deliberately does not tell anyone to copy the text out of the
    game: nothing establishes that a Dofus tooltip can be selected, and the
    site is not going to claim it can.
    """

    def _lexique(self, langue):
        from chardata.inventory_view import _ocr_stat_lexicon
        from fashionistapulp.structure import get_structure
        return _ocr_stat_lexicon(get_structure('dofus3'))[langue]

    def _lire(self, lignes, langue):
        source = self._source()
        morceaux = [self._extract(source, 'ocrNormalize'),
                    self._extract(source, 'parseStatLine')]
        script = '\n'.join(morceaux) + (
            '\nconst lexicon = %s;\n'
            'console.log(JSON.stringify(%s.map('
            'l => parseStatLine(l, lexicon))));\n'
            % (json.dumps(self._lexique(langue)), json.dumps(lignes)))
        return json.loads(self._node(script))

    def test_the_example_we_show_people_actually_parses(self):
        """The placeholder is an instruction. If it did not parse, the first
        thing anyone tried would fail."""
        from chardata.inventory_view import LOCALIZED_UI
        for langue in ('en', 'fr', 'es', 'pt', 'de'):
            with self.subTest(langue=langue):
                lignes = LOCALIZED_UI[langue]['text_placeholder'].split('\n')
                self.assertEqual(3, len(lignes), lignes)
                lus = self._lire(lignes[1:], langue)
                self.assertEqual([{'key': 'vit', 'value': 201},
                                  {'key': 'str', 'value': 15}], lus)

    def test_the_first_placeholder_line_is_the_item_name(self):
        """It must NOT parse as a stat, or the name line would be eaten."""
        from chardata.inventory_view import LOCALIZED_UI
        for langue in ('en', 'fr', 'es', 'pt', 'de'):
            with self.subTest(langue=langue):
                premiere = LOCALIZED_UI[langue]['text_placeholder'].split('\n')[0]
                self.assertEqual([None], self._lire([premiere], langue))

    def test_the_hint_never_claims_the_game_can_be_copied(self):
        """A Dofus tooltip is not known to be selectable. Saying otherwise
        would send people looking for something that may not exist."""
        from chardata.inventory_view import LOCALIZED_UI
        interdits = ('in-game', 'in game', 'depuis le jeu', 'dans le jeu',
                     'del juego', 'en el juego', 'do jogo', 'no jogo',
                     'aus dem spiel', 'im spiel')
        for langue in ('en', 'fr', 'es', 'pt', 'de'):
            with self.subTest(langue=langue):
                hint = LOCALIZED_UI[langue]['text_hint'].lower()
                for interdit in interdits:
                    self.assertNotIn(interdit, hint)

    def test_the_text_path_loads_no_engine(self):
        """The whole point. ensureTesseract and recognize belong to the
        screenshot path and must not appear in the text one."""
        source = self._source()
        process_text = self._extract(source, 'processText')
        self.assertNotIn('ensureTesseract', process_text)
        self.assertNotIn('Tesseract', process_text)
        self.assertIn('parseScreenshot', process_text)
        self.assertIn('searchCandidates', process_text)

    def test_the_result_panel_is_shared_by_both_entrances(self):
        """It used to live inside the screenshot box, so hiding that box hid
        the results with it and the text path would have had nowhere to draw."""
        source = self._source()
        debut = source.index('id="inv-ocr-box"')
        fin = source.index('</div>', source.index('id="inv-ocr-status"'))
        self.assertNotIn('id="inv-ocr-result"', source[debut:fin])
        self.assertIn('id="inv-ocr-result"', source)


class InventoryTemplateOnlyUsesLabelsThatExistTests(SimpleTestCase):
    """This page reads its labels from a plain dict rather than through
    gettext, so a mistyped key renders as an empty string and nothing
    complains: no exception, no test failure, just a button with no text."""

    def test_every_label_the_template_asks_for_exists(self):
        from chardata.inventory_view import LOCALIZED_UI
        chemin = os.path.join(os.path.dirname(__file__), 'templates',
                              'chardata', 'inventory.html')
        source = io.open(chemin, encoding='utf-8').read()
        demandes = set(re.findall(r'\{\{\s*t\.([a-zA-Z_]+)', source))
        self.assertGreater(len(demandes), 20, demandes)
        manquantes = sorted(demandes - set(LOCALIZED_UI['en']))
        self.assertEqual([], manquantes,
                         'inventory.html asks for labels the dict does not '
                         'have: %s' % manquantes)


class InventoryPageRendersBothEntrancesTests(TestCase):
    """The page had no rendering test of any kind, so a template that stopped
    drawing the screenshot panel, or a label that came out empty, would have
    shipped green.
    """

    def setUp(self):
        from django.contrib.auth.models import User
        from chardata.models import InventoryFolder
        self.user = User.objects.create_user('inv', 'inv@test.local', 'x')
        self.folder = InventoryFolder.objects.create(
            user=self.user, name='Imagiro', game_version='dofus3')
        self.client.force_login(self.user)

    def _page(self, **params):
        resp = self.client.get('/inventory/',
                               dict({'folder': self.folder.id}, **params))
        self.assertEqual(resp.status_code, 200)
        return resp.content.decode('utf-8')

    def test_both_entrances_are_on_the_page(self):
        page = self._page()
        self.assertIn('inv-ocr-toggle', page)
        self.assertIn('inv-text-toggle', page)
        self.assertIn('inv-text-input', page)

    def test_the_labels_are_not_empty(self):
        """A mistyped dict key renders as nothing at all, silently."""
        from chardata.inventory_view import LOCALIZED_UI
        page = self._page()
        for cle in ('text_button', 'text_read', 'ocr_button'):
            with self.subTest(cle=cle):
                self.assertIn(LOCALIZED_UI['en'][cle], page)

    def test_the_page_is_translated(self):
        page = self.client.get('/inventory/', {'folder': self.folder.id},
                               HTTP_ACCEPT_LANGUAGE='fr').content.decode('utf-8')
        from chardata.inventory_view import LOCALIZED_UI
        self.assertIn(LOCALIZED_UI['fr']['text_button'], page)

    def test_the_result_panel_is_not_inside_the_screenshot_panel(self):
        """Rendered, not just in the source: hiding one used to hide the
        other, which would have left the text path nowhere to draw."""
        page = self._page()
        boite = page.index('id="inv-ocr-box"')
        resultat = page.index('id="inv-ocr-result"')
        statut = page.index('id="inv-ocr-status"')
        self.assertLess(boite, statut)
        self.assertLess(statut, resultat)


class HowItWorksGuideSaysWhatTheSolverDoesTests(SimpleTestCase):
    """This guide is the page the repositioning points at, so every claim on
    it is checked against the catalogue and the solver rather than trusted.

    Two of them were wrong when this class was written, and both had shipped:
    the guide said the tool walks through thousands of combinations and keeps
    the best, and it said twelve equipment slots.
    """

    LANGUES = ('en', 'fr', 'es', 'pt', 'de')

    @staticmethod
    def _corps(langue):
        from chardata.guides_content import GUIDES
        return GUIDES['how-it-works']['i18n'][langue]['body']

    @staticmethod
    def _espace_de_recherche():
        """How many ways the sixteen slots can be filled at level 200."""
        import math
        from fashionistapulp.dofus_constants import SLOTS
        from fashionistapulp.structure import get_structure
        structure = get_structure('dofus3')
        niveau = max(structure.types)
        par_type = {nom: len([item for item in structure.types[niveau][nom]
                              if not item.removed])
                    for nom in structure.types[niveau]}
        combinaisons = 1
        for nom in ('Weapon', 'Shield', 'Hat', 'Cloak', 'Amulet', 'Belt',
                    'Boots', 'Pet'):
            combinaisons *= par_type[nom]
        # Two rings and six dofus are chosen from one pool each, and the same
        # item cannot be worn twice.
        combinaisons *= math.comb(par_type['Ring'], 2)
        combinaisons *= math.comb(par_type['Dofus'], 6)
        return len(SLOTS), par_type, combinaisons

    def test_the_search_space_really_is_past_ten_to_the_thirty_seventh(self):
        """The guide says "more than 10 to the power of 37". Measured
        2026-09-09 it is 2.6 times that, so an ordinary content patch cannot
        make the sentence false, but a collapse would and this would catch
        it."""
        _slots, _par_type, combinaisons = self._espace_de_recherche()
        self.assertGreater(combinaisons, 10 ** 37,
                           'the guide claims more than 10^37 and the '
                           'catalogue now gives %d' % combinaisons)

    def test_every_slot_really_has_over_a_hundred_candidates(self):
        """The guide says "well over a hundred candidates for every single one
        of them". Shields are the thinnest at 129."""
        _slots, par_type, _combinaisons = self._espace_de_recherche()
        maigre = min(par_type, key=lambda nom: par_type[nom])
        self.assertGreater(par_type[maigre], 100,
                           '%s has only %d' % (maigre, par_type[maigre]))

    def test_the_game_really_has_sixteen_slots(self):
        """It said twelve for as long as the guide existed."""
        slots, _par_type, _combinaisons = self._espace_de_recherche()
        self.assertEqual(16, slots)

    def test_no_guide_claims_the_solver_walks_the_combinations(self):
        """A MILP solver does not enumerate. Measured on a real Dofus 3 solve,
        CBC closed the problem at the root and reported "Enumerated nodes: 0",
        so a sentence about trying thousands of combinations describes a
        machine that does not exist, and it is exactly the reproach aimed at
        systems that produce a plausible answer."""
        from chardata.guides_content import GUIDES
        interdits = ('thousands of legal item combinations',
                     'milliers de combinaisons',
                     'miles de combinaciones',
                     'milhares de combina',
                     'tausende erlaubte item-kombinationen')
        for slug, guide in GUIDES.items():
            groupes = ([guide['i18n']] if 'i18n' in guide
                       else list(guide['i18n_by_group'].values()))
            for groupe in groupes:
                for langue, contenu in groupe.items():
                    corps = contenu['body'].lower()
                    for interdit in interdits:
                        with self.subTest(slug=slug, langue=langue):
                            self.assertNotIn(interdit, corps)

    def test_the_three_steps_come_before_the_technical_detail(self):
        """ChatGPT's own point, and the right one: what you do first, why it
        is trustworthy second, how it works third."""
        premiers = {'en': 'In three steps', 'fr': 'En trois \u00e9tapes',
                    'es': 'En tres pasos', 'pt': 'Em tr\u00eas passos',
                    'de': 'In drei Schritten'}
        rassurants = {'en': 'No magic', 'fr': 'Pas de magie',
                      'es': 'Nada de magia', 'pt': 'Nada de magia',
                      'de': 'Keine Magie'}
        for langue in self.LANGUES:
            with self.subTest(langue=langue):
                corps = self._corps(langue)
                titres = re.findall(r'<h2>(.*?)</h2>', corps)
                self.assertGreaterEqual(len(titres), 6, titres)
                self.assertIn(premiers[langue], titres[0])
                self.assertIn(rassurants[langue], titres[1])

    def test_the_guide_lists_what_the_reader_can_overrule(self):
        """Every one of these exists on a solution item, checked in
        solution_item.html: Lock, Forbid, Switch, Remove, Lock empty, plus the
        roll override and the smithmagic link. A list of controls that did not
        exist would be the worst kind of wrong on this page."""
        gabarit = os.path.join(os.path.dirname(__file__), 'templates',
                               'chardata', 'solution_item.html')
        rendu = io.open(gabarit, encoding='utf-8').read()
        for action in ('"Lock" context', '{% trans "Forbid" %}',
                       '{% trans "Switch" %}', '{% trans "Remove" %}',
                       '{% trans "Lock empty" %}'):
            with self.subTest(action=action):
                self.assertIn(action, rendu)
        self.assertIn('stat-override-btn-sol-', rendu)
        ateliers = {'en': 'smithmagic workbench', 'fr': 'atelier de forgemagie',
                    'es': 'taller de forjamagia', 'pt': 'oficina de forjamagia',
                    'de': 'schmiedemagie-werkstatt'}
        for langue in self.LANGUES:
            with self.subTest(langue=langue):
                self.assertIn(ateliers[langue], self._corps(langue).lower())

    def test_the_guide_never_promises_a_proven_optimum(self):
        """CBC runs with timeLimit=90 and PuLP relabels a stopped run as
        Optimal, so the site cannot tell a proved optimum from the best
        incumbent and must not claim one."""
        from fashionistapulp import lpproblem
        source = io.open(lpproblem.__file__, encoding='utf-8').read()
        from fashionistapulp.lpproblem import TIME_LIMIT_SECONDS
        self.assertEqual(90, TIME_LIMIT_SECONDS)
        self.assertIn('timeLimit=TIME_LIMIT_SECONDS', source)
        promesses = ('the optimal set', 'le set optimal', 'guaranteed best',
                     'meilleur set possible garanti')
        for langue in self.LANGUES:
            corps = self._corps(langue).lower()
            for promesse in promesses:
                with self.subTest(langue=langue, promesse=promesse):
                    self.assertNotIn(promesse, corps)


class WhyThisResultPanelTests(TestCase):
    """The panel that says whether the answer is proved or merely the best
    found in the time.

    That distinction is the site's whole claim to honesty and it was, until
    now, computed and thrown away: fashion_action read solution_is_proven()
    only to write a log line. CBC runs with a time limit and PuLP relabels a
    run it stopped as Optimal, so without sol_status the page cannot tell the
    two apart and would be claiming a proof it does not have.

    These read the PICKLED minimal solution and not what get_solution returns.
    That is the trap this feature fell into first: get_solution rebuilds a
    ModelResult through model_result_from_minimal, and the two facts do not
    survive the trip.
    """

    def _solve(self):
        from django.test import RequestFactory
        from django.contrib.auth.models import User
        from chardata.coaching_view import create_build
        owner = User.objects.create_user('whyres', 'why@test.local',
                                         'pw-42-solid')
        request = RequestFactory().post('/')
        request.user = owner
        char = create_build(request, 'Iop', 200, {'str'}, 'dofus3')
        self.client.force_login(owner)
        self.client.get('/fashion/%d/' % char.pk)
        char.refresh_from_db()
        return char

    @staticmethod
    def _rewrite(char, **champs):
        """Change the stored facts the way an old or a stopped solve would."""
        import pickle
        minimal = pickle.loads(char.minimal_solution)
        for nom, valeur in champs.items():
            if valeur is None:
                if hasattr(minimal, nom):
                    delattr(minimal, nom)
            else:
                setattr(minimal, nom, valeur)
        char.minimal_solution = pickle.dumps(minimal)
        char.save()

    def _page(self, char, **kwargs):
        resp = self.client.get('/solution/%d/' % char.pk, **kwargs)
        self.assertEqual(resp.status_code, 200)
        return resp.content.decode('utf-8')

    def test_the_solve_records_whether_it_proved_anything(self):
        if not _pulp_solver_available():
            self.skipTest('no pulp solver available')
        from chardata.solution import get_solver_facts
        char = self._solve()
        proven, seconds, _pool = get_solver_facts(char.minimal_solution)
        # `proven` must be a real boolean: False is an answer, and the
        # important one.
        self.assertIn(proven, (True, False))
        self.assertIsInstance(seconds, float)
        self.assertGreater(seconds, 0)

    def test_the_page_says_which_of_the_two_happened(self):
        if not _pulp_solver_available():
            self.skipTest('no pulp solver available')
        from chardata.solution import get_solver_facts
        char = self._solve()
        proven, _seconds, _pool = get_solver_facts(char.minimal_solution)
        page = self._page(char)
        self.assertIn('solver-why', page)
        self.assertIn('solver-priority', page)
        if proven:
            self.assertIn('Proven optimum', page)
            self.assertNotIn('not a proof', page)
        else:
            self.assertIn('not a proof', page)
            self.assertNotIn('Proven optimum', page)

    def test_an_old_solution_shows_no_panel_rather_than_a_guess(self):
        """Every solution pickled before these facts existed carries neither,
        and inventing one would be exactly the failure this panel exists to
        avoid."""
        if not _pulp_solver_available():
            self.skipTest('no pulp solver available')
        char = self._solve()
        self._rewrite(char, proven=None, solve_seconds=None)
        self.assertNotIn('solver-why', self._page(char))

    def test_false_is_shown_and_not_swallowed_as_missing(self):
        """`if solver_proven` would hide the unproven case, which is the only
        case the reader really needs to be told about."""
        if not _pulp_solver_available():
            self.skipTest('no pulp solver available')
        char = self._solve()
        self._rewrite(char, proven=False)
        page = self._page(char)
        self.assertIn('solver-why', page)
        self.assertIn('not a proof', page)
        self.assertIn('90', page)

    def test_the_page_quotes_the_solver_own_time_limit(self):
        """Two copies of the number would let the page promise a limit the
        solver no longer uses."""
        from fashionistapulp.lpproblem import TIME_LIMIT_SECONDS
        from chardata.solution_view import SOLVER_TIME_LIMIT_SECONDS
        self.assertEqual(TIME_LIMIT_SECONDS, SOLVER_TIME_LIMIT_SECONDS)
        source = io.open(os.path.join(
            os.path.dirname(__file__), '..', '..', 'fashionistapulp',
            'fashionistapulp', 'lpproblem.py'), encoding='utf-8').read()
        self.assertNotIn('timeLimit=90', source)

    def test_the_facts_do_not_survive_get_solution_which_is_why_they_are_read_raw(self):
        """Named after what it measures: the reason the view reads the blob.
        If some day the rebuilt ModelResult did carry them, this test failing
        is the signal that the helper can be simplified."""
        if not _pulp_solver_available():
            self.skipTest('no pulp solver available')
        from chardata.solution import get_solution
        char = self._solve()
        self.assertIsNone(getattr(get_solution(char), 'proven', None))

    def test_the_panel_is_translated(self):
        if not _pulp_solver_available():
            self.skipTest('no pulp solver available')
        char = self._solve()
        page = self._page(char, HTTP_ACCEPT_LANGUAGE='fr')
        self.assertIn('Pourquoi ce r\u00e9sultat', page)


class NoTranslationSaysGeneratedOnItsOwnTests(SimpleTestCase):
    """A translation must not reach for "generated" when the English does not.

    The repositioning away from generative-product vocabulary was done once by
    scanning English strings, and it missed everything in this class, because
    no scan of English can find a word that only exists in the translation.
    What it missed included the main button: the English said "Tailor a New
    Set" and the French said "Generer un nouvel equipement", so the French
    reader, who is most of the audience for a Dofus tool, had the generative
    word on the primary call to action the whole time.

    It also missed the meta descriptions, which are the text under the link in
    a search engine, because they are wrapped across several lines in the .po
    and the scan read line by line.

    The changelog is exempt: it dates what shipped and when, and rewriting it
    would be rewriting history.
    """

    #: language -> the generative verb family in that language.
    MOTS = {
        'fr': r'g\u00e9n\u00e9r[a-z\u00e9\u00e8]*',
        'es': r'gener[ao]d[ao]s?|generaci\u00f3n\w*|generar\w*',
        'pt': r'ger[ao]d[ao]s?|gera\u00e7\u00e3o|gera\u00e7\u00f5es|gerar\w*',
        'de': r'generier[a-z]*|generierung\w*',
    }
    #: The Dofus characteristic, the ordinary adjectives and the generous
    #: neighbour are not the generative vocabulary.
    INNOCENTS = r'g\u00e9n\u00e9ral\w*|general\w*|generic\w*|g\u00e9n\u00e9reux|generoso|generous'

    def test_no_translation_introduces_the_word(self):
        try:
            import polib
        except ImportError:
            self.skipTest('polib not installed')
        anglais = re.compile(r'(?i)\b(generat[a-z]*|generation\w*)\b')
        innocents = re.compile(r'(?i)\b(%s)\b' % self.INNOCENTS)
        locale_dir = os.path.join(os.path.dirname(__file__), '..', 'locale')
        for langue, mots in self.MOTS.items():
            motif = re.compile(r'(?i)\b(%s)\b' % mots)
            for po_path in glob.glob(os.path.join(
                    locale_dir, langue, 'LC_MESSAGES', '*.po')):
                po = polib.pofile(po_path)
                coupables = []
                for entree in po:
                    if entree.obsolete or not entree.msgstr:
                        continue
                    source = innocents.sub(' ', entree.msgid)
                    traduit = innocents.sub(' ', entree.msgstr)
                    if motif.search(traduit) and not anglais.search(source):
                        coupables.append(entree.msgid[:60])
                with self.subTest(po=os.path.relpath(po_path, locale_dir)):
                    self.assertEqual(coupables, [], msg=(
                        '%s: %d translation(s) say "generated" where the '
                        'English does not: %s'
                        % (langue, len(coupables), coupables)))

    def test_the_main_button_is_not_generative_in_any_language(self):
        """The one that started this. It is the primary call to action on
        every project page."""
        interdits = ('generer', 'genere', 'generar', 'gerar', 'generier')
        for langue in ('fr', 'es', 'pt', 'de'):
            with self.subTest(langue=langue):
                with translation.override(langue):
                    rendu = gettext('Tailor a New Set')
                self.assertNotEqual(rendu, 'Tailor a New Set', langue)
                plie = unicodedata.normalize('NFKD', rendu.lower())
                plie = ''.join(c for c in plie if not unicodedata.combining(c))
                for interdit in interdits:
                    self.assertNotIn(interdit, plie)

    def test_the_meta_descriptions_are_not_generative(self):
        """These are the words under the link in a search engine, so they are
        the first thing anyone reads about the site."""
        msgid = ('Get Dofus sets created automatically, based on your '
                 'specific needs.')
        for langue in ('fr', 'es', 'pt', 'de'):
            with self.subTest(langue=langue):
                with translation.override(langue):
                    rendu = gettext(msgid)
                plie = unicodedata.normalize('NFKD', rendu.lower())
                plie = ''.join(c for c in plie if not unicodedata.combining(c))
                for interdit in ('generee', 'generad', 'gerad', 'generier'):
                    self.assertNotIn(interdit, plie)


class SearchSpaceShownIsTheOneTheSolverSawTests(TestCase):
    """How big the search was, counted from the solver's own constraints.

    Recounting the catalogue in the view would have been easier and would have
    drifted: modify_forbidden_items_constraints is forty lines of shields,
    trophies, dofus modes, mount families and prysmaradites, and a second copy
    of that logic would eventually disagree with the first. Reading the right
    hand sides the solver was actually given cannot disagree with it.
    """

    def _solve(self, forbid=None):
        from django.test import RequestFactory
        from django.contrib.auth.models import User
        from chardata.coaching_view import create_build
        owner = User.objects.create_user('space%s' % (forbid or 'none'),
                                         'space@test.local', 'pw-42-solid')
        request = RequestFactory().post('/')
        request.user = owner
        char = create_build(request, 'Iop', 200, {'str'}, 'dofus3')
        self.client.force_login(owner)
        self.client.get('/fashion/%d/' % char.pk)
        char.refresh_from_db()
        return char

    def test_the_pool_is_what_the_solver_could_choose_from(self):
        if not _pulp_solver_available():
            self.skipTest('no pulp solver available')
        from chardata.solution import get_solver_facts
        from fashionistapulp.structure import get_structure
        char = self._solve()
        _proven, _seconds, pool = get_solver_facts(char.minimal_solution)
        self.assertTrue(pool, pool)
        # Never more than the catalogue itself, and not a rounding of it
        # either: a level 200 Iop cannot reach every item, and the default
        # exclusions take more out.
        structure = get_structure('dofus3')
        self.assertLessEqual(sum(pool.values()), len(structure.items_dict))
        self.assertGreater(sum(pool.values()), 1000)
        for type_name in ('Hat', 'Cloak', 'Amulet', 'Belt', 'Boots', 'Ring',
                          'Weapon'):
            with self.subTest(type_name=type_name):
                self.assertGreater(pool.get(type_name, 0), 0)

    def test_forbidding_an_item_takes_it_out_of_the_pool(self):
        """The number has to move when the player moves it, or it is
        decoration."""
        if not _pulp_solver_available():
            self.skipTest('no pulp solver available')
        from chardata.lock_forbid import (get_all_exclusions_en_names,
                                          set_exclusions_list_by_name)
        from chardata.solution import get_solver_facts
        from fashionistapulp.structure import get_structure
        char = self._solve()
        _p, _s, avant = get_solver_facts(char.minimal_solution)
        structure = get_structure('dofus3')
        # The union, not a replacement: a new project already carries default
        # exclusions, and handing over a bare list of five hats DELETES those,
        # which put more hats on offer than before. The first version of this
        # test did exactly that and read 377 where it expected 370.
        deja = set(get_all_exclusions_en_names(char))
        chapeaux = [item.name for item in structure.types[200]['Hat']
                    if not item.removed and item.name not in deja][:5]
        self.assertEqual(5, len(chapeaux))
        set_exclusions_list_by_name(char, sorted(deja | set(chapeaux)))
        self.client.get('/fashion/%d/' % char.pk)
        char.refresh_from_db()
        _p2, _s2, apres = get_solver_facts(char.minimal_solution)
        self.assertEqual(avant['Hat'] - 5, apres['Hat'],
                         'forbidding five hats must remove five hats')

    def test_the_exponent_counts_empty_slots_as_a_choice(self):
        """Exactly k per type would make a player who forbids every dofus get
        C(0, 6) = 0, and the whole product would collapse to zero possible
        sets. Summing over 0..k says the truth and never collapses."""
        from chardata.solution_view import _search_space_exponent
        sans_dofus = {'Hat': 300, 'Cloak': 300, 'Amulet': 300, 'Belt': 300,
                      'Boots': 300, 'Shield': 100, 'Weapon': 700,
                      'Ring': 300, 'Pet': 400, 'Dofus': 0}
        exposant = _search_space_exponent(sans_dofus)
        self.assertIsNotNone(exposant)
        self.assertGreater(exposant, 6)

    def test_a_tiny_pool_says_nothing_rather_than_something_silly(self):
        """"More than 10 to the power of 2" is not an argument."""
        from chardata.solution_view import _search_space_exponent
        self.assertIsNone(_search_space_exponent({'Hat': 2}))
        self.assertIsNone(_search_space_exponent({}))
        self.assertIsNone(_search_space_exponent(None))

    def test_the_exponent_is_a_floor_and_never_overstates(self):
        """The page says "more than 10 to the power of N", so N must be at
        most the real log10, never above it."""
        import math
        from chardata.solution_view import _search_space_exponent
        pool = {'Hat': 10, 'Cloak': 10, 'Amulet': 10, 'Belt': 10, 'Boots': 10,
                'Shield': 10, 'Weapon': 10, 'Ring': 10, 'Pet': 10, 'Dofus': 10}
        total = 1
        from fashionistapulp.dofus_constants import TYPE_NAME_TO_SLOT_NUMBER
        for type_name, slots in TYPE_NAME_TO_SLOT_NUMBER.items():
            n = pool.get(type_name, 0)
            total *= sum(math.comb(n, k) for k in range(0, min(n, slots) + 1))
        self.assertEqual(len(str(total)) - 1, _search_space_exponent(pool))
        self.assertGreater(total, 10 ** _search_space_exponent(pool))

    def test_the_page_shows_both_numbers(self):
        if not _pulp_solver_available():
            self.skipTest('no pulp solver available')
        from chardata.solution import get_solver_facts
        char = self._solve()
        _proven, _seconds, pool = get_solver_facts(char.minimal_solution)
        page = self.client.get('/solution/%d/' % char.pk).content.decode('utf-8')
        self.assertIn('%d items were on offer' % sum(pool.values()), page)
        self.assertIn('10 to the power of', page)

    def test_an_old_solution_shows_no_numbers(self):
        if not _pulp_solver_available():
            self.skipTest('no pulp solver available')
        import pickle
        char = self._solve()
        minimal = pickle.loads(char.minimal_solution)
        del minimal.candidate_pool
        char.minimal_solution = pickle.dumps(minimal)
        char.save()
        page = self.client.get('/solution/%d/' % char.pk).content.decode('utf-8')
        self.assertNotIn('items were on offer', page)
        # The rest of the panel still shows: the facts are independent.
        self.assertIn('solver-why', page)


class DofusBookLinkIsReadTests(SimpleTestCase):
    """Reading a public DofusBook build from its link.

    Everything asserted here was measured against their live site on
    2026-09-09 and is then replayed from a stub, so the suite stays offline
    and still describes what really happens.
    """

    LIEN = 'https://www.dofusbook.net/fr/stuff/7894460-zobal-m-200'

    #: Two real items from build 7894460, with their real Ankama ids in the
    #: field DofusBook calls `official`.
    CHARGE = {
        'stuff': {'name': 'Zobal M 200', 'character_level': 200,
                  'character_class': 12},
        'items': [{'official': 17998, 'name': 'Anneau Crustique'},
                  {'official': 18000, 'name': 'Masque de Koutoulou'}],
    }

    def _opener(self, charge=None, erreur=None, attendu=None):
        """Stands in for urlopen and checks what we would have sent."""
        essai = self

        class Reponse(object):
            def __init__(self, contenu):
                self.contenu = contenu

            def read(self, *args):
                return json.dumps(self.contenu).encode('utf-8')

            def __enter__(self):
                return self

            def __exit__(self, *args):
                return False

        def ouvrir(request, timeout=None):
            if attendu is not None:
                essai.assertEqual(attendu, request.full_url)
            # Their site answers 403 without a Referer on their own domain.
            essai.assertTrue(request.get_header('Referer', '')
                             .startswith('https://'))
            essai.assertIn('Mozilla', request.get_header('User-agent', ''))
            if erreur is not None:
                raise erreur
            return Reponse(charge if charge is not None else self.CHARGE)

        return ouvrir

    def test_the_host_decides_the_version_and_is_never_guessed(self):
        """A build id is NOT unique across their hosts. Measured live: id
        2558915 is a 404 on www, an 8 item level 21 build called "Bas Level"
        on retro, and a 16 item level 170 build called "Feu eau" on touch.
        Trying hosts until one answers would import a different player's build
        from a different game."""
        from chardata.dofusbook_import import HOSTS, parse_link
        self.assertEqual(('www.dofusbook.net', '7894460'),
                         parse_link(self.LIEN))
        self.assertEqual(
            ('retro.dofusbook.net', '2558915'),
            parse_link('https://retro.dofusbook.net/fr/stuff/2558915-bas-level'))
        self.assertEqual(
            ('touch.dofusbook.net', '2558915'),
            parse_link('https://touch.dofusbook.net/fr/stuff/2558915-feu-eau'))
        self.assertEqual({'dofus3', 'retro', 'touch'}, set(HOSTS.values()))

    def test_the_base_stats_and_scrolls_are_read_from_stuffcarac(self):
        """Their `stuff.stuffCarac`, read on build 7894460 on 2026-09-11:
        base_* is what the player invested, scroll_* the scroll, in their
        order vi, sa, fo, in, ch, ag which is ours."""
        from chardata.dofusbook_import import base_stats
        carac = {'scroll_vi': 100, 'scroll_sa': 100, 'scroll_fo': 100,
                 'scroll_in': 100, 'scroll_ch': 100, 'scroll_ag': 100,
                 'base_vi': 395, 'base_sa': 0, 'base_fo': 300, 'base_in': 0,
                 'base_ch': 0, 'base_ag': 0}
        points, parchos = base_stats({'stuffCarac': carac})
        self.assertEqual({'Vitality': 395, 'Strength': 300}, points)
        self.assertEqual({'Vitality': 100, 'Wisdom': 100, 'Strength': 100,
                          'Intelligence': 100, 'Chance': 100, 'Agility': 100},
                         parchos)
        # Sans le bloc, rien; une valeur qui n'est pas un entier est laissee.
        self.assertEqual(({}, {}), base_stats({}))
        self.assertEqual(({}, {}), base_stats({'stuffCarac': None}))
        self.assertEqual(({}, {}), base_stats({'stuffCarac': {'base_vi': '395',
                                                               'scroll_vi': True}}))
        charge = dict(self.CHARGE, stuff=dict(self.CHARGE['stuff'],
                                              stuffCarac=carac))
        from chardata.dofusbook_import import read_build
        lu = read_build(self.LIEN, opener=self._opener(charge=charge))
        self.assertEqual({'Vitality': 395, 'Strength': 300}, lu['base_points'])
        self.assertEqual(100, lu['base_scrolled']['Agility'])

    #: Five of the sixteen pieces of build 23227661 (www, read 2026-09-11),
    #: with their ids, Ankama ids and forgemagie exactly as their API hands
    #: them back: `stuffItem` is {slot: their id}, `fmItems` {slot: {stat
    #: code: final value}}, `fmWeapon` an element string, `fmGlobal` empty
    #: on every real build read so far.
    CHARGE_FM = {
        'stuff': {'name': 'Terre Eau Air Transi Crit/RetPm',
                  'character_level': 200,
                  'stuffItem': {'a1': 6742, 'a2': 3173, 'am': 2805,
                                'ar': 6743, 'd6': 5123, 'mo': None}},
        'items': [{'id': 6742, 'official': 32234, 'name': 'Anneau de Culbutoeuf'},
                  {'id': 3173, 'official': 15190, 'name': 'Bracelet du Piloztere'},
                  {'id': 2805, 'official': 14094, 'name': 'Amulette du Strigide'},
                  {'id': 6743, 'official': 32235, 'name': 'Arc de Culbutoeuf'},
                  {'id': 5123, 'official': 7112, 'name': 'Dofus Tachete'}],
        'fmItems': {'a1': {'pm': 1}, 'a2': {'pa': 1}, 'am': {'cc': 8},
                    'ar': {'dc': 8}, 'd6': {'dmg': 20}, 'mo': {}},
        'fmGlobal': {},
        'fmWeapon': 'de-85',
    }

    def test_the_forgemagie_of_each_piece_is_read_through_its_slot(self):
        """Thibaud, 2026-09-11: "l'import de dofusbook ne prend pas bien en
        compte ... les FM sur les items". Measured on build 23227661 the
        same day: `fmItems` is keyed by their slot code and holds the FINAL
        value of each line, and the slot reaches the item through
        `stuff.stuffItem` (their id) then `items[].official` (Ankama's).
        Nothing is approximate: an exo MP on the ring, an exo AP on the
        bracelet, 8 critical on the amulet, 8 critical damage on the bow,
        20 damage on the Dofus."""
        from chardata.dofusbook_import import item_rolls, read_build
        from fashionistapulp.structure import get_structure
        structure = get_structure('dofus3')

        def de(ankama):
            return structure.items_dict_ankama[ankama].id

        rolls, sans_cle = item_rolls(self.CHARGE_FM, 'dofus3')
        self.assertEqual({de(32234): [{'key': 'mp', 'value': 1}],
                          de(15190): [{'key': 'ap', 'value': 1}],
                          de(14094): [{'key': 'ch', 'value': 8}],
                          de(32235): [{'key': 'cridam', 'value': 8}],
                          de(7112): [{'key': 'dam', 'value': 20}]}, rolls)
        self.assertEqual([], sans_cle)
        build = read_build(self.LIEN,
                           opener=self._opener(charge=self.CHARGE_FM))
        self.assertEqual(rolls, build['rolls'])
        self.assertEqual('de-85', build['fm_weapon'])
        self.assertEqual({}, build['fm_global'])
        self.assertEqual([], build['fm_unmapped'])

    def test_a_line_with_no_stat_on_our_side_is_reported_not_dropped(self):
        """Measured on Retro build 2541727 (2026-09-11): `d2: {deg: 10}` on
        a Black-Spotted Dofus, a code with no characteristic here. It comes
        back named with its piece, so the page can say it was left out. A
        line on a piece we do not carry says nothing more: the piece is
        already in `missing`."""
        from chardata.dofusbook_import import item_rolls
        from fashionistapulp.structure import get_structure
        structure = get_structure('dofus3')
        charge = {'stuff': {'stuffItem': {'d6': 5123, 'ch': 99}},
                  'items': [{'id': 5123, 'official': 7112, 'name': 'Dofus Tachete'},
                            {'id': 99, 'official': 999999999, 'name': 'Nowhere'}],
                  'fmItems': {'d6': {'deg': 10, 'dmg': 20}, 'ch': {'vi': 50}}}
        rolls, sans_cle = item_rolls(charge, 'dofus3')
        dofus = structure.items_dict_ankama[7112].id
        self.assertEqual({dofus: [{'key': 'dam', 'value': 20}]}, rolls)
        self.assertEqual([(dofus, 'deg', 10)], sans_cle)

    def test_a_link_that_is_not_theirs_is_not_read(self):
        from chardata.dofusbook_import import parse_link
        for url in ('https://example.com/fr/stuff/7894460-x',
                    'https://www.dofusbook.net/fr/stuff/',
                    'pas une url', ''):
            with self.subTest(url=url):
                self.assertIsNone(parse_link(url))

    def test_a_short_link_is_refused_and_not_followed(self):
        """Their d-bk.net redirect target could not be verified, and the
        catalogue cannot catch the mistake: a Retro build landing on www would
        resolve all its items under dofus3 and import silently wrong. One
        click to paste the full link beats that."""
        from chardata.dofusbook_import import ImportError_, read_build
        with self.assertRaises(ImportError_) as pris:
            read_build('https://d-bk.net/abcdef')
        self.assertEqual('short_link', pris.exception.reason)

    def test_the_ankama_id_is_what_maps_the_items(self):
        """Their `official` field is the Ankama id, which is what our own
        catalogue is keyed on, so nothing is matched by name. Measured live:
        16 of 16 items on this build."""
        from chardata.dofusbook_import import read_build
        from fashionistapulp.structure import get_structure
        build = read_build(self.LIEN, opener=self._opener(
            attendu='https://www.dofusbook.net/api/stuffs/x/public/7894460'))
        self.assertEqual('dofus3', build['game_version'])
        self.assertEqual('Zobal M 200', build['name'])
        self.assertEqual(200, build['level'])
        self.assertEqual([], build['missing'])
        structure = get_structure('dofus3')
        noms = [structure.get_item_by_id(i).name for i in build['item_ids']]
        self.assertEqual(['Crustic Ring', 'Koutoulou Mask'], noms)

    def test_the_class_is_left_for_the_player_to_pick(self):
        """Their character_class is their own numbering, not Ankama's: build
        7894460 is called "Zobal M 200" and carries character_class 12, where
        12 is Pandawa in Ankama's order. Nothing in the payload names the
        class, so guessing it would put the wrong class on the project."""
        from chardata.dofusbook_import import read_build
        build = read_build(self.LIEN, opener=self._opener())
        self.assertTrue(build['class_is_unknown'])
        self.assertNotIn('char_class', build)

    def test_an_empty_item_list_is_refused(self):
        """An unsupported x-lang answers 200 with items:[], so an empty build
        is a suspicious answer and not an empty wardrobe."""
        from chardata.dofusbook_import import ImportError_, read_build
        with self.assertRaises(ImportError_) as pris:
            read_build(self.LIEN, opener=self._opener(
                charge={'stuff': {}, 'items': []}))
        self.assertEqual('empty', pris.exception.reason)

    def test_items_that_do_not_exist_here_stop_the_import(self):
        from chardata.dofusbook_import import ImportError_, read_build
        charge = {'stuff': {'name': 'x', 'character_level': 200},
                  'items': [{'official': 999999901, 'name': 'a'},
                            {'official': 999999902, 'name': 'b'},
                            {'official': 17998, 'name': 'Anneau Crustique'}]}
        with self.assertRaises(ImportError_) as pris:
            read_build(self.LIEN, opener=self._opener(charge=charge))
        self.assertEqual('wrong_version', pris.exception.reason)

    def test_a_missing_build_says_so(self):
        from chardata.dofusbook_import import ImportError_, read_build
        erreur = urllib.error.HTTPError(self.LIEN, 404, 'Not Found', {}, None)
        with self.assertRaises(ImportError_) as pris:
            read_build(self.LIEN, opener=self._opener(erreur=erreur))
        self.assertEqual('not_found', pris.exception.reason)

    def test_their_site_being_down_is_not_our_crash(self):
        from chardata.dofusbook_import import ImportError_, read_build
        with self.assertRaises(ImportError_) as pris:
            read_build(self.LIEN, opener=self._opener(
                erreur=OSError('connection reset')))
        self.assertEqual('unreachable', pris.exception.reason)

    def test_the_catalogue_check_is_not_a_version_detector(self):
        """Named after what it measures. A Retro build's items resolve under
        retro, dofus3 AND touch, because low level items carry the same Ankama
        id in every version. So the floor cannot tell versions apart and the
        host stays the only thing that decides."""
        from chardata.dofusbook_import import map_items
        charge = {'items': [{'official': 311, 'name': 'Anneau du Bandit'}]}
        resolus = {}
        for version in ('dofus3', 'retro', 'touch'):
            trouves, _manquants = map_items(charge, version)
            resolus[version] = len(trouves)
        self.assertEqual(1, len(set(resolus.values())), resolus)


class LinkImportOnTheOnePageTests(TestCase):
    """Un lien colle dans la page d'import unique: le build est lu, montre,
    la classe demandee, puis cree.

    Le 11 septembre 2026 la page qui ne prenait qu'un lien a ete fondue dans
    la page d'import (une seule porte, neutre); son adresse redirige. Le
    reseau n'est jamais touche: read_build est remplace, puisque ce qu'il
    fait est couvert par DofusBookLinkIsReadTests contre un simulacre de
    leur API.
    """

    LIEN = 'https://www.dofusbook.net/fr/stuff/7894460-zobal-m-200'

    def _build(self, version='dofus3', ids=None, missing=None, level=200):
        from fashionistapulp.structure import get_structure
        structure = get_structure(version)
        if ids is None:
            ids = [next(item.id for item in structure.types[200][type_name]
                        if not item.removed)
                   for type_name in ('Hat', 'Cloak', 'Belt')]
        return {'game_version': version, 'source_host': 'www.dofusbook.net',
                'build_id': '7894460', 'name': 'Zobal M 200', 'level': level,
                'item_ids': ids, 'missing': missing or [],
                # Les points investis et les parchotages de la vraie charge
                # de 7894460 (stuffCarac, lu le 2026-09-11): 395 vitalite et
                # 300 force investis, tout parchote a 100.
                'base_points': {'Vitality': 395, 'Strength': 300},
                'base_scrolled': {nom: 100 for nom in (
                    'Vitality', 'Wisdom', 'Strength', 'Intelligence',
                    'Chance', 'Agility')},
                'class_is_unknown': True}

    def test_the_stats_of_the_link_come_in_with_the_gear(self):
        """Thibaud, 11 septembre 2026: <<l'import de dofusbook ne prend pas
        bien en compte mes stats (base et parcho)>>. Mesure: read_build les
        jetait. Ils sont montres avant, et ecrits tels que le site les garde
        (total = investi + parchemin, scrolled = parchemin)."""
        from chardata.models import Char, CharBaseStats
        self._patch(build=self._build())
        page = self.client.post(self._url(), {'text': self.LIEN})
        self.assertContains(page, 'Vitality: 395')
        self.assertContains(page, '100 scrolled')
        self.client.post(self._url(), {'text': self.LIEN, 'confirm': '1',
                                       'char_class': 'Iop', 'level': '200'})
        char = Char.objects.order_by('-id').first()
        lignes = {l.stat: (l.total_value, l.scrolled_value)
                  for l in CharBaseStats.objects.filter(char=char)}
        self.assertEqual((495, 100), lignes['Vitality'])
        self.assertEqual((400, 100), lignes['Strength'])
        self.assertEqual((100, 100), lignes['Agility'])

    def test_a_project_link_brings_its_class_and_names_the_fm_left_behind(self):
        """Un lien DofusCreator porte la classe dans une numerotation que
        l'on sait lire: elle est pre-selectionnee; ses exos par piece ne
        voyagent pas et la page nomme les pieces avant creation."""
        from chardata.models import Char
        from fashionistapulp.structure import get_structure
        structure = get_structure('dofus3')
        build = self._build()
        build.update({'source_host': 'dofuscreator.com', 'build_id': '6e9f4',
                      'name': 'MIAAW 420', 'char_class': 'Ecaflip',
                      'class_is_unknown': False,
                      'fm_not_carried': build['item_ids'][:2]})
        self._patch(build=build)
        lien = 'https://dofuscreator.com/projet/6e9f4'
        page = self.client.post(self._url(), {'text': lien},
                                HTTP_ACCEPT_LANGUAGE='en')
        self.assertContains(page, 'import-link-fm')
        nom = structure.get_item_name_in_language(
            structure.get_item_by_id(build['item_ids'][0]), 'en')
        self.assertContains(page, 'does not travel yet')
        self.assertContains(page, nom)
        # Le minifieur trie les attributs et retire les guillemets simples.
        self.assertRegex(page.content.decode('utf-8'),
                         r'<option[^>]*selected[^>]*value="?Ecaflip"?[^>]*>'
                         r'|<option[^>]*value="?Ecaflip"?[^>]*selected[^>]*>')
        self.client.post(self._url(), {'text': lien, 'confirm': '1',
                                       'char_class': 'Ecaflip', 'level': '200'})
        char = Char.objects.order_by('-id').first()
        self.assertEqual('Ecaflip', char.char_class)
        self.assertEqual('MIAAW 420', char.name)

    def test_the_note_under_the_field_lists_the_readable_sites(self):
        page = self.client.get(self._url(), HTTP_ACCEPT_LANGUAGE='en'
                               ).content.decode('utf-8')
        self.assertIn('dofusbook.net, dofus-stuffer.is-great.net, '
                      'dofuscreator.com', page)

    def test_the_rolls_of_the_link_land_on_the_pieces(self):
        """Thibaud, 11 septembre 2026: <<les FM sur les items>>. Un jet du
        lien suit la regle d'un jet colle: applique quand la piece porte la
        stat, exo pour les PA, PM et portee. Une ligne sur une stat que la
        piece ne porte pas est ajoutee comme exo et non refusee: un lien
        n'est pas une lecture d'OCR (8 dommages critiques sur un arc qui
        n'en porte pas, build 23227661 recoupe avec leur table d'effets).
        Tout est montre sur la puce de la piece avant la creation et ecrit
        dans les overrides du build a la confirmation, apres la pose des
        objets."""
        from chardata.lock_forbid import get_stat_overrides
        from chardata.models import Char
        from chardata.stat_range import get_stat_range
        from chardata.translation_util import localized_stat_name
        from fashionistapulp.structure import get_structure
        structure = get_structure('dofus3')
        mp = structure.get_stat_by_key('mp').id
        chapeau = next(item for item in structure.types[200]['Hat']
                       if not item.removed and mp not in dict(item.stats))
        stat_id, _valeur = next(iter(chapeau.stats))
        stat = structure.get_stat_by_id(stat_id)
        _bas, haut = get_stat_range(chapeau, stat_id)
        ajoutee = next(cle for cle in ('pshdam', 'trapdam', 'summon', 'pod')
                       if structure.get_stat_by_key(cle).id
                       not in dict(chapeau.stats))
        build = self._build()
        build['item_ids'][0] = chapeau.id
        build['rolls'] = {chapeau.id: [{'key': stat.key, 'value': haut},
                                       {'key': 'mp', 'value': 1},
                                       {'key': ajoutee, 'value': 7}]}
        self._patch(build=build)
        page = self.client.post(self._url(), {'text': self.LIEN},
                                HTTP_ACCEPT_LANGUAGE='en')
        self.assertContains(page, '%d %s' % (
            haut, localized_stat_name(stat.name, 'dofus3')))
        self.assertContains(page, 'read as an exo')
        self.assertNotContains(page, 'because the item does not carry that stat')
        self.assertContains(page, '7 %s' % localized_stat_name(
            structure.get_stat_by_key(ajoutee).name, 'dofus3'))
        self.assertEqual(2, page.content.decode('utf-8').count('read as an exo'))
        self.client.post(self._url(), {'text': self.LIEN, 'confirm': '1',
                                       'char_class': 'Iop', 'level': '200'})
        char = Char.objects.order_by('-id').first()
        self.assertEqual({stat_id: haut, mp: 1,
                          structure.get_stat_by_key(ajoutee).id: 7},
                         get_stat_overrides(char)[chapeau.id])

    def test_what_the_link_cannot_place_is_named_before_creation(self):
        """La forgemagie de l'arme (un changement d'element), les lignes au
        niveau du build et les codes sans caracteristique chez nous n'ont
        pas de piece ou aller: la page les nomme avant, dans leurs mots
        quand il le faut, au lieu de les perdre en silence. Et l'entete des
        caracteristiques ne dit plus <<dans le texte>>."""
        from django.utils.html import escape
        from fashionistapulp.structure import get_structure
        structure = get_structure('dofus3')
        build = self._build()
        chapeau = build['item_ids'][0]
        build.update({'fm_weapon': 'de-85', 'fm_global': {'pa': 1},
                      'fm_unmapped': [(chapeau, 'deg', 10)]})
        self._patch(build=build)
        page = self.client.post(self._url(), {'text': self.LIEN},
                                HTTP_ACCEPT_LANGUAGE='en')
        nom = structure.get_item_name_in_language(
            structure.get_item_by_id(chapeau), 'en')
        for temoin in ('import-link-fm-weapon', 'weapon forgemagie',
                       # Nommee dans les mots du lecteur et non dans leur
                       # code: un build que nous exportons revient avec sa
                       # forgemagie exactement la (mesure du 11 septembre).
                       'import-link-fm-global', '1 AP',
                       'import-link-fm-unmapped', escape('%s: deg 10' % nom),
                       'Characteristics read:'):
            self.assertContains(page, temoin)
        page = self.client.post(self._url(), {'text': self.LIEN},
                                HTTP_ACCEPT_LANGUAGE='fr')
        self.assertContains(page, 'reste de c\u00f4t\u00e9')
        self.assertContains(page, 'Caract\u00e9ristiques lues')

    def test_a_points_line_in_the_text_wins_over_the_link(self):
        """Une ligne Points: collee sous le lien est un choix explicite du
        lecteur; le lien fournit le reste."""
        from chardata.models import Char, CharBaseStats
        self._patch(build=self._build())
        texte = self.LIEN + '\nPoints: Vitality 100 / Wisdom 50'
        self.client.post(self._url(), {'text': texte, 'confirm': '1',
                                       'char_class': 'Iop', 'level': '200'})
        char = Char.objects.order_by('-id').first()
        lignes = {l.stat: (l.total_value, l.scrolled_value)
                  for l in CharBaseStats.objects.filter(char=char)}
        self.assertEqual((200, 100), lignes['Vitality'])
        self.assertEqual((150, 100), lignes['Wisdom'])
        self.assertEqual((400, 100), lignes['Strength'])

    def _patch(self, build=None, erreur=None):
        from chardata import text_build_view
        from chardata.dofusbook_import import ImportError_
        vrai = text_build_view.read_build

        def faux(url, opener=None):
            if erreur is not None:
                raise ImportError_(erreur)
            return build

        text_build_view.read_build = faux
        self.addCleanup(setattr, text_build_view, 'read_build', vrai)

    def _url(self, version='dofus3'):
        return ('/import/text/' if version == 'dofus3'
                else '/%s/import/text/' % version)

    def test_the_old_address_sends_to_the_one_page(self):
        for vieux, neuf in (('/import/dofusbook/', '/import/text/'),
                            ('/touch/import/dofusbook/', '/touch/import/text/')):
            reponse = self.client.get(vieux)
            self.assertEqual(301, reponse.status_code, vieux)
            self.assertEqual(neuf, reponse['Location'], vieux)

    def test_a_link_from_a_site_we_cannot_read_is_named_as_such(self):
        """Pas <<aucun objet>>: le lecteur a colle un lien, on lui repond
        sur le lien."""
        page = self.client.post(self._url(), {'text': 'https://example.com/build/42'})
        self.assertContains(page, 'cannot read links from that site yet')

    def test_a_short_link_explains_why_it_is_refused(self):
        self._patch(erreur='short_link')
        page = self.client.post(self._url(), {'text': 'https://d-bk.net/abcdef'})
        self.assertContains(page, 'do not say which game')

    def test_no_third_party_name_in_a_refusal(self):
        """Les refus valent pour n'importe quel site que le serveur saura
        lire: aucun ne nomme un site."""
        for raison in ('not_found', 'refused', 'unreachable', 'unreadable'):
            self._patch(erreur=raison)
            page = self.client.post(self._url(), {'text': self.LIEN})
            self.assertNotContains(page, 'DofusBook')

    def test_reading_a_link_creates_nothing_yet(self):
        from chardata.models import Char
        self._patch(build=self._build())
        avant = Char.objects.count()
        page = self.client.post(self._url(), {'text': self.LIEN})
        self.assertContains(page, 'import-link-read')
        self.assertContains(page, 'Zobal M 200')
        self.assertContains(page, 'Bring this build in')
        self.assertEqual(avant, Char.objects.count())

    def test_the_class_is_asked_for_and_never_guessed(self):
        self._patch(build=self._build())
        page = self.client.post(self._url(), {'text': self.LIEN})
        self.assertContains(page, 'name="char_class"')
        self.assertContains(page, 'Iop')

    def test_confirming_brings_the_gear_in_without_solving(self):
        from chardata.models import Char
        from chardata.solution import get_solution, get_solver_facts
        self._patch(build=self._build())
        reponse = self.client.post(self._url(), {
            'text': self.LIEN, 'confirm': '1', 'char_class': 'Iop',
            'level': '200'})
        self.assertEqual(302, reponse.status_code)
        char = Char.objects.order_by('-id').first()
        self.assertEqual('Iop', char.char_class)
        self.assertEqual('dofus3', char.game_version)
        self.assertEqual('Zobal M 200', char.name)
        solution = get_solution(char)
        self.assertIsNotNone(solution)
        portes = {item.name for items in solution.items.values()
                  for item in items if getattr(item, 'item_added', False)}
        self.assertEqual(3, len(portes), portes)
        proven, seconds, pool = get_solver_facts(char.minimal_solution)
        self.assertIsNone(proven)
        self.assertIsNone(seconds)
        self.assertIsNone(pool)

    def test_a_link_and_item_names_together(self):
        """Le lien d'abord, le texte ensuite, sans doublon: une amulette
        collee sous le lien rejoint les trois pieces du lien."""
        from chardata.models import Char
        from chardata.solution import get_solution
        from fashionistapulp.structure import get_structure
        structure = get_structure('dofus3')
        amulette = next(item for item in structure.types[200]['Amulet']
                        if not item.removed)
        self._patch(build=self._build())
        texte = self.LIEN + '\n' + structure.get_item_name_in_language(amulette, 'en')
        page = self.client.post(self._url(), {'text': texte})
        self.assertContains(page, structure.get_item_name_in_language(amulette, 'en'))
        self.client.post(self._url(), {'text': texte, 'confirm': '1',
                                       'char_class': 'Iop', 'level': '200'})
        char = Char.objects.order_by('-id').first()
        portes = {item.name for items in get_solution(char).items.values()
                  for item in items if getattr(item, 'item_added', False)}
        self.assertEqual(4, len(portes), portes)
        self.assertIn(amulette.name, portes)

    def test_the_link_decides_the_version_and_says_so(self):
        """Un lien Retro colle sur la page Dofus 3: le build est cree en
        Retro, la page le dit avant, et la redirection porte le prefixe."""
        from fashionistapulp.fashionista_config import get_items_db_path
        if not os.path.exists(get_items_db_path('retro')):
            self.skipTest('no retro database')
        lien = 'https://retro.dofusbook.net/fr/stuff/2558915-bas-level'
        self._patch(build=self._build(version='retro', level=21))
        page = self.client.post(self._url(), {'text': lien})
        self.assertContains(page, 'created in that version')
        reponse = self.client.post(self._url(), {
            'text': lien, 'confirm': '1', 'char_class': 'Iop', 'level': '21'})
        self.assertEqual(302, reponse.status_code)
        self.assertTrue(reponse['Location'].startswith('/retro/solution/'),
                        reponse['Location'])

    def test_items_we_do_not_have_are_named_before_anything_is_created(self):
        self._patch(build=self._build(missing=['Chapeau Inconnu']))
        page = self.client.post(self._url(), {'text': self.LIEN})
        self.assertContains(page, 'import-link-missing')
        self.assertContains(page, 'not in our catalogue')
        self.assertContains(page, 'Chapeau Inconnu')

    def test_the_page_is_translated(self):
        page = self.client.get(self._url(),
                               HTTP_ACCEPT_LANGUAGE='fr').content.decode('utf-8')
        self.assertIn('Importer un build', page)
        self.assertIn('Lire tout ça', page)
        self.assertNotIn('Import a build', page)


class ConstraintsReachedAreShownTests(TestCase):
    """The minimums the project asked for, each with what the result reached.

    ChatGPT asked for exactly this under the result, and it is the part of the
    panel a reader can check against their own build at a glance. Both numbers
    are read rather than recomputed for display: the minimums out of the
    project, the totals out of the solution the page is already rendering.
    """

    def _char_with_minimum(self, stat_name='Vitality', value=1000):
        from django.test import RequestFactory
        from django.contrib.auth.models import User
        from chardata.coaching_view import create_build
        from chardata.min_stats import set_min_stats
        owner = User.objects.create_user('mins', 'mins@test.local',
                                         'pw-42-solid')
        request = RequestFactory().post('/')
        request.user = owner
        char = create_build(request, 'Iop', 200, {'str'}, 'dofus3')
        set_min_stats(char, {stat_name: value})
        self.client.force_login(owner)
        self.client.get('/fashion/%d/' % char.pk)
        char.refresh_from_db()
        return char

    def test_the_minimum_and_what_was_reached_are_both_shown(self):
        if not _pulp_solver_available():
            self.skipTest('no pulp solver available')
        from chardata.solution import get_solution
        from chardata.solution_view import _constraints_reached
        char = self._char_with_minimum()
        lignes = _constraints_reached(char, get_solution(char))
        self.assertTrue(lignes, lignes)
        vitalite = [l for l in lignes if l['asked'] == 1000]
        self.assertEqual(1, len(vitalite), lignes)
        # The solver only returns a set when every constraint holds, so a
        # minimum it accepted must be met.
        self.assertTrue(vitalite[0]['met'], vitalite)
        self.assertGreaterEqual(vitalite[0]['reached'], 1000)

    def test_the_chips_reach_the_page(self):
        if not _pulp_solver_available():
            self.skipTest('no pulp solver available')
        char = self._char_with_minimum()
        page = self.client.get('/solution/%d/' % char.pk).content.decode('utf-8')
        self.assertIn('solver-why-goal', page)

    def test_a_project_with_no_minimum_shows_no_chips(self):
        """Nothing to say is said with nothing."""
        if not _pulp_solver_available():
            self.skipTest('no pulp solver available')
        from django.test import RequestFactory
        from django.contrib.auth.models import User
        from chardata.coaching_view import create_build
        from chardata.solution import get_solution
        from chardata.solution_view import _constraints_reached
        owner = User.objects.create_user('nomins', 'nomins@test.local',
                                         'pw-42-solid')
        request = RequestFactory().post('/')
        request.user = owner
        char = create_build(request, 'Iop', 200, {'str'}, 'dofus3')
        self.client.force_login(owner)
        self.client.get('/fashion/%d/' % char.pk)
        char.refresh_from_db()
        self.assertEqual([], _constraints_reached(char, get_solution(char)))

    def test_a_missed_minimum_is_shown_and_not_hidden(self):
        """It should never happen, since the solver returns nothing when a
        constraint cannot hold. Hiding it anyway would hide the only case
        worth seeing."""
        from chardata.solution_view import _constraints_reached

        class FausseSolution(object):
            def get_stats_total(self):
                return {'vit': 800}

        class FauxChar(object):
            id = 1
            minimum_stats = None
            game_version = 'dofus3'

        from chardata import solution_view
        vrai = solution_view.get_min_stats_digested_by_key
        solution_view.get_min_stats_digested_by_key = lambda char: {'vit': 1000}
        self.addCleanup(setattr, solution_view,
                        'get_min_stats_digested_by_key', vrai)
        lignes = _constraints_reached(FauxChar(), FausseSolution())
        self.assertEqual(1, len(lignes))
        self.assertFalse(lignes[0]['met'])
        self.assertEqual(800, lignes[0]['reached'])
        self.assertEqual(1000, lignes[0]['asked'])

    def test_the_advanced_minimums_are_left_out(self):
        """adv_mins is a nested structure of per element and per situation
        minimums; one flat line each would say less than the stat table already
        below."""
        from chardata.solution_view import _constraints_reached

        class FausseSolution(object):
            def get_stats_total(self):
                return {'vit': 1200}

        class FauxChar(object):
            id = 1
            minimum_stats = None
            game_version = 'dofus3'

        from chardata import solution_view
        vrai = solution_view.get_min_stats_digested_by_key
        solution_view.get_min_stats_digested_by_key = lambda char: {
            'vit': 1000, 'adv_mins': {'anything': 1}}
        self.addCleanup(setattr, solution_view,
                        'get_min_stats_digested_by_key', vrai)
        lignes = _constraints_reached(FauxChar(), FausseSolution())
        self.assertEqual(['vit'], ['vit'] if len(lignes) == 1 else lignes)


class NoPageOverclaimsWhatTheSolverDoesTests(SimpleTestCase):
    """Le meme mensonge, cherche partout et plus seulement dans les guides.

    Un garde-fou existait deja pour les guides et il a tenu. La page d'ACCUEIL,
    elle, a continue de dire pendant tout ce temps que l'outil "searches
    thousands of legal item combinations", dans les cinq langues, parce que
    c'est un gabarit et pas un guide. Un garde qui ne couvre qu'un dossier
    garde un dossier.

    Ce que le solveur fait vraiment, mesure sur une resolution Dofus 3 reelle:
    CBC ferme le probleme a la racine et rapporte `Enumerated nodes: 0`. Il ne
    parcourt rien. Et il tourne avec TIME_LIMIT_SECONDS = 90, donc rien n'est
    instantane et rien n'est garanti optimal: PuLP re-etiquette en Optimal un
    run qu'il a stoppe, ce que la page de solution dit deja mot pour mot.
    """

    #: Les surfaces ou une affirmation peut atteindre un lecteur.
    def _textes(self):
        racine = os.path.dirname(__file__)
        for dossier, _sous, fichiers in os.walk(os.path.join(racine,
                                                             'templates')):
            for f in fichiers:
                if f.endswith('.html') and 'changelog' not in f:
                    chemin = os.path.join(dossier, f)
                    yield (os.path.basename(chemin),
                           io.open(chemin, encoding='utf-8').read())
        for module in ('inventory_view', 'forgemagie_view', 'encyclopedia_view'):
            chemin = os.path.join(racine, '%s.py' % module)
            if os.path.exists(chemin):
                yield ('%s.py' % module,
                       io.open(chemin, encoding='utf-8').read())

    def test_no_page_says_the_solver_walks_the_combinations(self):
        interdits = ('thousands of legal item combinations',
                     'thousands of combinations',
                     'milliers de combinaisons',
                     'miles de combinaciones',
                     'milhares de combina',
                     'tausende erlaubte item-kombinationen')
        coupables = []
        for nom, texte in self._textes():
            bas = texte.lower()
            for interdit in interdits:
                if interdit in bas:
                    coupables.append((nom, interdit))
        self.assertEqual(coupables, [], msg=(
            'these say the solver walks combinations one by one, which is a '
            'machine that does not exist: %s' % coupables))

    def test_no_page_promises_an_instant_or_guaranteed_best(self):
        """CBC a quatre-vingt-dix secondes et PuLP ne distingue pas un optimum
        prouve du meilleur incumbent. Promettre l'un ou l'autre est faux."""
        interdits = ('instantly finds', 'your best possible set',
                     'the optimal set', 'guaranteed best',
                     'trouve instantanement', 'meilleur set possible')
        coupables = []
        for nom, texte in self._textes():
            bas = texte.lower()
            for interdit in interdits:
                if interdit in bas:
                    coupables.append((nom, interdit))
        self.assertEqual(coupables, [], msg=(
            'these promise a speed or a proof the solver cannot give: %s'
            % coupables))

    def test_no_page_claims_the_text_never_leaves_the_browser(self):
        """La phrase la plus dangereuse ecrite hier: "Nothing is downloaded and
        nothing leaves your browser", sur la lecture de texte de l'inventaire.
        Rien n'est telecharge, c'est vrai. Mais processText appelle
        searchCandidates, qui envoie le nom de l'objet a ce serveur dans la
        query string. Une promesse de vie privee doit etre exacte ou ne pas
        exister."""
        interdits = ('nothing leaves your browser',
                     'rien ne sort de votre navigateur',
                     'nada sale de su navegador',
                     'nada sai do seu navegador',
                     'nichts verl\u00e4sst ihren browser')
        coupables = []
        for nom, texte in self._textes():
            bas = texte.lower()
            for interdit in interdits:
                if interdit in bas:
                    coupables.append((nom, interdit))
        self.assertEqual(coupables, [], msg=(
            'the item name IS sent to this server to be looked up, so this '
            'promise is false: %s' % coupables))

    def test_the_sweep_actually_reads_something(self):
        """Le plancher du temoin. Sans lui, un chemin casse rendrait zero
        texte, zero faute, et un vert parfait qui ne garde rien."""
        textes = list(self._textes())
        self.assertGreater(len(textes), 50, len(textes))
        self.assertTrue(any(nom == 'home.html' for nom, _t in textes))
        self.assertTrue(any(nom == 'inventory_view.py' for nom, _t in textes))
